}

import { AppConfig } from "../types";

const CONFIG_KEY = 'id_photo_booth_config';

export const DEFAULT_CONFIG: AppConfig = {
  shopName: "ID Photo Booth Pro",
  welcomeTitle: "ID Photo Booth",
  welcomeSubtitle: "Giải pháp chụp ảnh thẻ tự động chuẩn sinh trắc học.",
  contactPhone: "0909000111",
  contactZalo: "0909000111",
  printFooterText: "Dịch vụ chụp ảnh thẻ lấy ngay",
  themeColorHex: "#3b82f6" // Default Blue
};

export const saveConfig = (config: AppConfig) => {
  localStorage.setItem(CONFIG_KEY, JSON.stringify(config));
  applyTheme(config.themeColorHex);
};

export const getConfig = (): AppConfig => {
  const saved = localStorage.getItem(CONFIG_KEY);
  if (!saved) return DEFAULT_CONFIG;
  try {
    return { ...DEFAULT_CONFIG, ...JSON.parse(saved) };
  } catch (e) {
    return DEFAULT_CONFIG;
  }
};

// Helper to convert Hex to RGB numbers string (e.g. "59 130 246") for Tailwind vars
const hexToRgb = (hex: string) => {
  let r = 0, g = 0, b = 0;
  // 3 digits
  if (hex.length === 4) {
    r = parseInt("0x" + hex[1] + hex[1]);
    g = parseInt("0x" + hex[2] + hex[2]);
    b = parseInt("0x" + hex[3] + hex[3]);
  } else if (hex.length === 7) {
    r = parseInt("0x" + hex[1] + hex[2]);
    g = parseInt("0x" + hex[3] + hex[4]);
    b = parseInt("0x" + hex[5] + hex[6]);
  }
  return `${r} ${g} ${b}`;
};

// Apply CSS variables to root
export const applyTheme = (hexColor: string) => {
  const rgb = hexToRgb(hexColor);
  const root = document.documentElement;

  // We apply the same color to 500/600/700 for simplicity in this demo,
  // or calculate shades if we wanted to be fancy.
  // For now, mapping main brand color to 500/600 and darker to 700.

  root.style.setProperty('--brand-500', rgb);
  root.style.setProperty('--brand-600', rgb); // Keeping simple, same base
  root.style.setProperty('--brand-700', rgb);

  // Lighter shades (simulated by using white overlay in CSS usually, but here specific vars)
  // Just use the same RGB, tailwind opacity utility will handle the lightness mostly
  // But strictly, let's keep it simple:
  root.style.setProperty('--brand-50', rgb);
  root.style.setProperty('--brand-100', rgb);
  root.style.setProperty('--brand-200', rgb);
};

