                  </span>
                  <input 
                    type="password" 
                    autoFocus
                    placeholder="Nhập mật khẩu..." 
                    value={adminPass}
                    onChange={(e) => setAdminPass(e.target.value)}
                    className="w-full border border-gray-300 rounded-xl py-2.5 pl-10 pr-4 focus:ring-2 focus:ring-brand-500 focus:border-brand-500 outline-none transition"
