          </button>
        </div>
      </div>

      {/* Edit/Add Modal */}
      {showClothingModal && (
        <div className="fixed inset-0 bg-black/60 z-50 flex items-center justify-center p-4 backdrop-blur-sm">
           <div className="bg-white rounded-2xl p-8 w-full max-w-md shadow-2xl animate-fadeIn">
