              <div className="space-y-5">
                 <InputGroup label="Tên hiển thị (Label)">
                    <input type="text" className={baseInputClass} value={tempClothing.label} onChange={e => setTempClothing({...tempClothing, label: e.target.value})} placeholder="Ví dụ: Vest Đen" />
                 </InputGroup>
                 <div className="grid grid-cols-2 gap-4">
                    <InputGroup label="Giới tính">
                      <select className={baseInputClass} value={tempClothing.gender} onChange={e => setTempClothing({...tempClothing, gender: e.target.value as any})}>
