              </div>
              <div className="flex justify-end gap-3 mt-8 pt-4 border-t border-gray-100">
                 <button onClick={() => setShowClothingModal(false)} className="px-5 py-2.5 text-gray-500 font-bold hover:bg-gray-100 rounded-xl transition">Hủy</button>
                 <button onClick={saveClothingItem} className="px-6 py-2.5 bg-brand-600 text-white font-bold rounded-xl hover:bg-brand-700 shadow-lg shadow-brand-500/20 transition">Lưu lại</button>
              </div>
           </div>
        </div>
      )}

      <style>{`
        @keyframes fadeIn {
          from { opacity: 0; transform: translateY(10px); }
          to { opacity: 1; transform: translateY(0); }
        }
        .animate-fadeIn {
          animation: fadeIn 0.4s ease-out forwards;
        }
      `}</style>
    </div>
  );
};

export default AdminDashboard;

import React, { useState, useEffect, useRef } from 'react';
import { AppConfig, ClothingItem } from '../types';
import { saveConfig, applyTheme } from '../services/configService';

interface AdminDashboardProps {
  currentConfig: AppConfig;
  onUpdateConfig: (newConfig: AppConfig) => void;
  onExit: () => void;
}

const COLORS = [
  { hex: '#3b82f6', label: 'Xanh Dương' },
  { hex: '#ef4444', label: 'Đỏ' },
  { hex: '#10b981', label: 'Xanh Lá' },
  { hex: '#8b5cf6', label: 'Tím' },
  { hex: '#f59e0b', label: 'Vàng Cam' },
  { hex: '#ec4899', label: 'Hồng' },
  { hex: '#0f172a', label: 'Đen' },
];

// Helper component for styled inputs
const InputGroup = ({ label, icon, children }: { label: string, icon?: React.ReactNode, children?: React.ReactNode }) => (
  <div className="group">
    <label className="block text-xs font-bold text-slate-500 uppercase tracking-wider mb-2">{label}</label>
    <div className="relative">
      {icon && <div className="absolute left-3 top-3.5 text-slate-400 group-focus-within:text-brand-500 transition-colors">{icon}</div>}
      {children}
    </div>
  </div>
);

const AdminDashboard: React.FC<AdminDashboardProps> = ({ currentConfig, onUpdateConfig, onExit }) => {
  const [form, setForm] = useState<AppConfig>(currentConfig);
  const [activeTab, setActiveTab] = useState<'general' | 'design' | 'clothing' | 'security'>('general');
  const [saveStatus, setSaveStatus] = useState('');
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Clothing Editor State
  const [editingItem, setEditingItem] = useState<ClothingItem | null>(null);
  const [showClothingModal, setShowClothingModal] = useState(false);
  const [tempClothing, setTempClothing] = useState<ClothingItem>({
    id: '', label: '', gender: 'male', icon: '👔', prompt: '', color: 'border-gray-300'
  });

  useEffect(() => {
    // Live preview theme change
    applyTheme(form.themeColorHex);
  }, [form.themeColorHex]);

  const handleChange = (field: keyof AppConfig, value: any) => {
    setForm(prev => ({ ...prev, [field]: value }));
  };

  const handleSave = () => {
    saveConfig(form);
    onUpdateConfig(form);
    setSaveStatus('Đã lưu cấu hình thành công!');
    setTimeout(() => setSaveStatus(''), 2000);
  };

  const handleLogoUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      if (file.size > 1024 * 1024) { // Limit 1MB
        alert("Ảnh quá lớn! Vui lòng chọn ảnh dưới 1MB.");
        return;
      }
      const reader = new FileReader();
      reader.onloadend = () => {
        setForm(prev => ({ ...prev, logoUrl: reader.result as string }));
      };
      reader.readAsDataURL(file);
    }
  };

  const handleRemoveLogo = () => {
    setForm(prev => ({ ...prev, logoUrl: '' }));
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  // Clothing CRUD
  const openAddClothing = () => {
    setEditingItem(null);
    setTempClothing({ id: `custom_${Date.now()}`, label: '', gender: 'male', icon: '👔', prompt: '', color: 'border-blue-500' });
    setShowClothingModal(true);
  };

  const openEditClothing = (item: ClothingItem) => {
    setEditingItem(item);
    setTempClothing({ ...item });
    setShowClothingModal(true);
  };

  const saveClothingItem = () => {
    let newOptions = [...form.clothingOptions];
    if (editingItem) {
      // Edit
      newOptions = newOptions.map(item => item.id === editingItem.id ? tempClothing : item);
    } else {
      // Add
      newOptions.push(tempClothing);
    }
    setForm(prev => ({ ...prev, clothingOptions: newOptions }));
    setShowClothingModal(false);
  };

  const deleteClothingItem = (id: string) => {
    if (confirm('Bạn có chắc chắn muốn xóa trang phục này?')) {
      const newOptions = form.clothingOptions.filter(item => item.id !== id);
      setForm(prev => ({ ...prev, clothingOptions: newOptions }));
    }
  };

  const baseInputClass = "w-full bg-slate-50 border border-slate-200 text-slate-700 font-medium rounded-xl p-3 focus:bg-white focus:ring-4 focus:ring-brand-500/10 focus:border-brand-500 outline-none transition-all duration-200 placeholder:text-slate-400";

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col font-sans">

      {/* Admin Header */}
      <header className="bg-white border-b border-gray-200 sticky top-0 z-40 px-6 py-3 flex justify-between items-center shadow-sm">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 bg-gradient-to-br from-brand-500 to-brand-700 text-white rounded-xl flex items-center justify-center font-bold text-xl shadow-brand-500/30 shadow-lg">
            A
          </div>
          <div>
            <h1 className="font-bold text-gray-800 text-lg leading-tight">Quản trị hệ thống</h1>
            <p className="text-xs text-gray-500">ID Photo Booth Pro</p>
          </div>
        </div>
        <div className="flex items-center gap-4">
          <span className={`text-sm font-bold transition-all duration-300 ${saveStatus ? 'text-green-600 opacity-100 translate-y-0' : 'opacity-0 translate-y-2'}`}>
            {saveStatus}
          </span>
          <button 
            onClick={onExit}
            className="px-4 py-2 bg-gray-100 hover:bg-gray-200 text-gray-600 rounded-lg text-sm font-bold transition"
          >
            Thoát
          </button>
        </div>
      </header>

      <div className="flex-1 max-w-7xl w-full mx-auto p-6 grid grid-cols-1 lg:grid-cols-4 gap-8 items-start">

        {/* Sidebar Navigation */}
        <nav className="space-y-1 lg:sticky lg:top-24">
          {[
            { id: 'general', label: 'Thông tin chung', icon: (active: boolean) => <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 21V5a2 2 0 00-2-2H7a2 2 0 00-2 2v16m14 0h2m-2 0h-5m-9 0H3m2 0h5M9 7h1m-1 4h1m4-4h1m-1 4h1m-5 10v-5a1 1 0 011-1h2a1 1 0 011 1v5m-4 0h4"></path></svg> },
            { id: 'design', label: 'Giao diện & Màu sắc', icon: (active: boolean) => <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M7 21a4 4 0 01-4-4V5a2 2 0 012-2h4a2 2 0 012 2v12a4 4 0 01-4 4zm0 0h12a2 2 0 002-2v-4a2 2 0 00-2-2h-2.343M11 7.343l1.657-1.657a2 2 0 012.828 0l2.829 2.829a2 2 0 010 2.828l-8.486 8.485M7 17h.01"></path></svg> },
            { id: 'clothing', label: 'Quản lý Trang phục', icon: (active: boolean) => <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M20 7l-8-4-8 4m16 0l-8 4m8-4v10l-8 4m0-10L4 7m8 4v10M4 7v10l8 4"></path></svg> },
            { id: 'security', label: 'Bảo mật', icon: (active: boolean) => <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 15v2m-6 4h12a2 2 0 002-2v-6a2 2 0 00-2-2H6a2 2 0 00-2 2v6a2 2 0 002 2zm10-10V7a4 4 0 00-8 0v4h8z"></path></svg> }
          ].map(tab => {
            const isActive = activeTab === tab.id;
            return (
              <button 
                key={tab.id}
