                  {tab.icon(isActive)}
                </div>
                {tab.label}
              </button>
            )
          })}
        </nav>

        {/* Content Area */}
        <div className="lg:col-span-3 space-y-8 pb-24">

          {/* GENERAL TAB */}
          {activeTab === 'general' && (
            <div className="space-y-6 animate-fadeIn">

              {/* Section 1: Branding */}
              <div className="bg-white p-6 rounded-2xl shadow-sm border border-gray-100">
                <h3 className="text-lg font-bold text-gray-800 mb-6 flex items-center gap-2 pb-2 border-b border-gray-50">
                  <span className="w-8 h-8 rounded-lg bg-blue-100 text-blue-600 flex items-center justify-center text-sm">
                    <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 21V5a2 2 0 00-2-2H7a2 2 0 00-2 2v16m14 0h2m-2 0h-5m-9 0H3m2 0h5M9 7h1m-1 4h1m4-4h1m-1 4h1m-5 10v-5a1 1 0 011-1h2a1 1 0 011 1v5m-4 0h4"></path></svg>
                  </span>
                  Nhận diện thương hiệu
