                        onClick={() => fileInputRef.current?.click()}
                       >
                          {form.logoUrl ? (
                             <img src={form.logoUrl} alt="Logo" className="w-full h-full object-contain p-2" />
                          ) : (
                             <div className="text-center p-4">
                               <svg className="w-8 h-8 text-slate-300 mx-auto mb-1" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z"></path></svg>
                               <span className="text-xs text-slate-400 font-bold">Tải ảnh lên</span>
                             </div>
                          )}
                          <div className="absolute inset-0 bg-black/0 group-hover:bg-black/5 transition-colors"></div>
                       </div>

                       <input 
                         type="file" 
                         accept="image/*" 
                         ref={fileInputRef}
                         onChange={handleLogoUpload}
                         className="hidden"
                       />

                       {form.logoUrl && (
                         <button onClick={handleRemoveLogo} className="text-xs text-red-500 font-bold hover:bg-red-50 px-2 py-1 rounded transition">
                            Gỡ bỏ Logo
                         </button>
                       )}
                    </div>
                  </div>

                  {/* Brand Inputs */}
                  <div className="flex-1 space-y-5">
                    <InputGroup label="Tên cửa hàng (Hiển thị khi không có Logo)" icon={<svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M3 12l2-2m0 0l7-7 7 7M5 10v10a1 1 0 001 1h3m10-11l2 2m-2-2v10a1 1 0 01-1 1h-3m-6 0a1 1 0 001-1v-4a1 1 0 011-1h2a1 1 0 011 1v4a1 1 0 001 1m-6 0h6"></path></svg>}>
                      <input 
