                        <option value="female">Nữ</option>
                      </select>
                    </InputGroup>
                    <InputGroup label="Biểu tượng">
                      <input type="text" className={`${baseInputClass} text-center text-xl`} value={tempClothing.icon} onChange={e => setTempClothing({...tempClothing, icon: e.target.value})} placeholder="👔" />
                    </InputGroup>
                 </div>
                 <InputGroup label="Câu lệnh AI (Prompt)">
                    <textarea className={`${baseInputClass} h-24 text-sm`} value={tempClothing.prompt} onChange={e => setTempClothing({...tempClothing, prompt: e.target.value})} placeholder="wearing a black suit..." />
                 </InputGroup>
                 <InputGroup label="Màu viền (Tailwind CSS)">
                    <input type="text" className={`${baseInputClass} font-mono text-xs`} value={tempClothing.color} onChange={e => setTempClothing({...tempClothing, color: e.target.value})} placeholder="border-blue-500" />
