export default AdminDashboard;

import React, { useState, useEffect, useRef } from 'react';
import { AppConfig, ClothingItem } from '../types';
import { saveConfig, applyTheme } from '../services/configService';

interface AdminDashboardProps {
  currentConfig: AppConfig;
  onUpdateConfig: (newConfig: AppConfig) => void;
  onExit: () => void;
}

const COLORS = [
  { hex: '#3b82f6', label: 'Xanh Dương' },
  { hex: '#ef4444', label: 'Đỏ' },
  { hex: '#10b981', label: 'Xanh Lá' },
  { hex: '#8b5cf6', label: 'Tím' },
  { hex: '#f59e0b', label: 'Vàng Cam' },
  { hex: '#ec4899', label: 'Hồng' },
  { hex: '#0f172a', label: 'Đen' },
];

// Helper component for styled inputs
const InputGroup = ({ label, icon, children }: { label: string, icon?: React.ReactNode, children?: React.ReactNode }) => (
  <div className="group w-full">
    <label className="block text-xs font-bold text-slate-500 uppercase tracking-wider mb-2">{label}</label>
    <div className="relative w-full">
      {icon && <div className="absolute left-3 top-3.5 text-slate-400 group-focus-within:text-brand-500 transition-colors pointer-events-none z-10">{icon}</div>}
      {children}
    </div>
  </div>
);

const AdminDashboard: React.FC<AdminDashboardProps> = ({ currentConfig, onUpdateConfig, onExit }) => {
  const [form, setForm] = useState<AppConfig>(currentConfig);
  const [activeTab, setActiveTab] = useState<'general' | 'design' | 'clothing' | 'security'>('general');
  const [saveStatus, setSaveStatus] = useState('');
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Clothing Editor State
  const [editingItem, setEditingItem] = useState<ClothingItem | null>(null);
  const [showClothingModal, setShowClothingModal] = useState(false);
  const [tempClothing, setTempClothing] = useState<ClothingItem>({
    id: '', label: '', gender: 'male', icon: '👔', prompt: '', color: 'border-gray-300'
  });

  useEffect(() => {
    // Live preview theme change
    applyTheme(form.themeColorHex);
  }, [form.themeColorHex]);

  const handleChange = (field: keyof AppConfig, value: any) => {
    setForm(prev => ({ ...prev, [field]: value }));
  };

  const handleSave = () => {
    saveConfig(form);
    onUpdateConfig(form);
    setSaveStatus('Đã lưu!');
    setTimeout(() => setSaveStatus(''), 2000);
  };

  const handleLogoUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      if (file.size > 1024 * 1024) { // Limit 1MB
        alert("Ảnh quá lớn! Vui lòng chọn ảnh dưới 1MB.");
        return;
      }
      const reader = new FileReader();
      reader.onloadend = () => {
        setForm(prev => ({ ...prev, logoUrl: reader.result as string }));
      };
      reader.readAsDataURL(file);
    }
  };

  const handleRemoveLogo = () => {
    setForm(prev => ({ ...prev, logoUrl: '' }));
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  // Clothing CRUD
  const openAddClothing = () => {
    setEditingItem(null);
    setTempClothing({ id: `custom_${Date.now()}`, label: '', gender: 'male', icon: '👔', prompt: '', color: 'border-blue-500' });
    setShowClothingModal(true);
  };

  const openEditClothing = (item: ClothingItem) => {
    setEditingItem(item);
    setTempClothing({ ...item });
    setShowClothingModal(true);
  };

  const saveClothingItem = () => {
    let newOptions = [...form.clothingOptions];
    if (editingItem) {
      // Edit
      newOptions = newOptions.map(item => item.id === editingItem.id ? tempClothing : item);
    } else {
      // Add
      newOptions.push(tempClothing);
    }
    setForm(prev => ({ ...prev, clothingOptions: newOptions }));
    setShowClothingModal(false);
  };

  const deleteClothingItem = (id: string) => {
    if (confirm('Bạn có chắc chắn muốn xóa trang phục này?')) {
      const newOptions = form.clothingOptions.filter(item => item.id !== id);
      setForm(prev => ({ ...prev, clothingOptions: newOptions }));
    }
  };

  const baseInputClass = "w-full bg-slate-50 border border-slate-200 text-slate-700 font-medium rounded-xl p-3 focus:bg-white focus:ring-4 focus:ring-brand-500/10 focus:border-brand-500 outline-none transition-all duration-200 placeholder:text-slate-400";
  const iconInputClass = `${baseInputClass} pl-10`;

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col font-sans">

      {/* Admin Header - Sticky Top */}
      <header className="bg-white border-b border-gray-200 sticky top-0 z-50 px-4 py-3 flex justify-between items-center shadow-sm">
        <div className="flex items-center gap-3">
          <div className="w-9 h-9 bg-gradient-to-br from-brand-500 to-brand-700 text-white rounded-lg flex items-center justify-center font-bold text-lg shadow-brand-500/30 shadow-md">
            A
          </div>
          <div className="leading-tight">
            <h1 className="font-bold text-gray-800 text-base">Quản trị</h1>
            <p className="text-[10px] text-gray-400 hidden sm:block">ID Photo Booth Pro</p>
          </div>
        </div>
        <div className="flex items-center gap-3">
          <span className={`text-sm font-bold transition-all duration-300 ${saveStatus ? 'text-green-600 opacity-100 translate-y-0' : 'opacity-0 translate-y-2'}`}>
            {saveStatus}
          </span>
          <button 
            onClick={onExit}
            className="px-3 py-2 bg-gray-100 hover:bg-gray-200 text-gray-600 rounded-lg text-sm font-bold transition flex items-center gap-1 active:scale-95"
          >
            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M17 16l4-4m0 0l-4-4m4 4H7m6 4v1a3 3 0 01-3 3H6a3 3 0 01-3-3V7a3 3 0 013-3h4a3 3 0 013 3v1"></path></svg>
            <span className="hidden sm:inline">Thoát</span>
          </button>
        </div>
      </header>

      <div className="flex-1 max-w-7xl w-full mx-auto p-4 lg:p-6 grid grid-cols-1 lg:grid-cols-4 gap-6 lg:gap-8 items-start">

        {/* Navigation - Horizontal Scroll on Mobile, Vertical Sticky on Desktop */}
