export default AdminDashboard;

import React, { useRef, useState, useEffect, useCallback } from 'react';
import { PhotoSize } from '../types';
import { analyzeIDPhotoFrame } from '../services/geminiService';

interface CameraCaptureProps {
  onCapture: (imageSrc: string) => void;
  selectedSize: PhotoSize;
  onSizeChange: (size: PhotoSize) => void;
}

// Strict State Machine for Biometric Validation
type ValidationStatus = 'searching' | 'analyzing' | 'adjusting' | 'valid';

const CameraCapture: React.FC<CameraCaptureProps> = ({ onCapture, selectedSize, onSizeChange }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const analysisCanvasRef = useRef<HTMLCanvasElement>(null); // Separate canvas for low-res analysis

  const [stream, setStream] = useState<MediaStream | null>(null);
  const [error, setError] = useState<string>('');
  const [countdown, setCountdown] = useState<number | null>(null);

  const [devices, setDevices] = useState<MediaDeviceInfo[]>([]);
  const [selectedDeviceId, setSelectedDeviceId] = useState<string>('');

  // AI Validation State
  const [validationStatus, setValidationStatus] = useState<ValidationStatus>('searching');
  const [feedbackMessage, setFeedbackMessage] = useState<string>('Đang khởi động AI...');
  const [instruction, setInstruction] = useState<string>('');

  // Ref to track if an analysis request is currently in flight
  const isAnalyzingRef = useRef(false);
  // Using ReturnType<typeof setInterval> to handle both NodeJS and Browser environments
  const analysisIntervalRef = useRef<ReturnType<typeof setInterval> | null>(null);

  useEffect(() => {
    getDevices();
    startCamera();
    return () => {
      stopCamera();
      if (analysisIntervalRef.current) clearInterval(analysisIntervalRef.current);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  useEffect(() => {
    if (selectedDeviceId) startCamera(selectedDeviceId);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [selectedDeviceId]);

  // Start AI Analysis Loop when stream is active
  useEffect(() => {
    if (stream && !countdown) {
      // Run analysis every 1.5 seconds to avoid rate limits but keep it snappy
      analysisIntervalRef.current = setInterval(performAIAnalysis, 1500);
    } else {
      if (analysisIntervalRef.current) clearInterval(analysisIntervalRef.current);
    }
    return () => {
      if (analysisIntervalRef.current) clearInterval(analysisIntervalRef.current);
    };
  }, [stream, countdown, selectedSize]); // Added selectedSize dependency

  // Helper to calculate exact crop coordinates based on current video and selected size
  const getCropDimensions = (videoW: number, videoH: number) => {
    let targetRatio = 2/3; // Default 4x6
    if (selectedSize === PhotoSize.SIZE_5X5) targetRatio = 1;
    if (selectedSize === PhotoSize.SIZE_3X4) targetRatio = 3/4;

    const videoRatio = videoW / videoH;
    let cropW, cropH, startX, startY;

    if (videoRatio > targetRatio) {
      // Source is wider than target: Crop Width (vertical bars)
      cropH = videoH;
      cropW = cropH * targetRatio;
      startX = (videoW - cropW) / 2;
      startY = 0;
    } else {
      // Source is taller than target: Crop Height (horizontal bars)
      cropW = videoW;
      cropH = cropW / targetRatio;
      startX = 0;
      startY = (videoH - cropH) / 2;
    }

    return {
      x: Math.floor(startX),
      y: Math.floor(startY),
      w: Math.floor(cropW),
      h: Math.floor(cropH)
    };
  };

  const performAIAnalysis = async () => {
    if (isAnalyzingRef.current || !videoRef.current || !analysisCanvasRef.current) return;

    try {
      isAnalyzingRef.current = true;
      const video = videoRef.current;
      const canvas = analysisCanvasRef.current;
      const ctx = canvas.getContext('2d');

      if (video.readyState === 4 && ctx) {
        // Calculate the exact crop that the user sees and will capture
        const crop = getCropDimensions(video.videoWidth, video.videoHeight);

        // Resize for analysis (height 320px is sufficient for face detection)
        // Maintain aspect ratio of the CROP, not the full video
        const analysisH = 320;
        const analysisW = Math.floor(analysisH * (crop.w / crop.h));

        canvas.width = analysisW;
        canvas.height = analysisH;

        // Draw MIRRORED crop to match user experience
        ctx.save();
        ctx.translate(canvas.width, 0);
        ctx.scale(-1, 1);
        ctx.drawImage(video, crop.x, crop.y, crop.w, crop.h, 0, 0, canvas.width, canvas.height);
        ctx.restore();

        const base64 = canvas.toDataURL('image/jpeg', 0.6); // Low quality is enough for structure check

        // Show "Scanning" state briefly if we were previously idle
        if (validationStatus === 'searching') setValidationStatus('analyzing');

        const result = await analyzeIDPhotoFrame(base64);

        if (!result.faceDetected) {
           setValidationStatus('searching');
           setFeedbackMessage('Không tìm thấy mặt');
           setInstruction('Di chuyển vào khung hình');
        } else if (result.isCompliant) {
           setValidationStatus('valid');
           setFeedbackMessage('ĐẠT CHUẨN');
           setInstruction(result.instruction || 'Giữ nguyên tư thế!');
        } else {
           setValidationStatus('adjusting');
           setFeedbackMessage(result.feedback || 'Cần điều chỉnh');
           setInstruction(result.instruction || 'Chỉnh lại tư thế');
        }
      }
    } catch (err) {
      console.error("AI check failed", err);
    } finally {
      isAnalyzingRef.current = false;
    }
  };

  const getDevices = async () => {
    try {
      const allDevices = await navigator.mediaDevices.enumerateDevices();
      const videoDevices = allDevices.filter(device => device.kind === 'videoinput');
      setDevices(videoDevices);
      const canon = videoDevices.find(d => d.label.toLowerCase().includes('canon') || d.label.toLowerCase().includes('eos'));
      if (canon) setSelectedDeviceId(canon.deviceId);
    } catch (err) {
      console.error("Error enumerating devices", err);
    }
  };

  const startCamera = async (deviceId?: string) => {
    stopCamera();
    try {
      const constraints: MediaStreamConstraints = {
        video: {
          deviceId: deviceId ? { exact: deviceId } : undefined,
          width: { ideal: 1920 }, // High resolution for quality crop
          height: { ideal: 1080 },
        },
        audio: false
      };
      const mediaStream = await navigator.mediaDevices.getUserMedia(constraints);
      setStream(mediaStream);
      if (videoRef.current) videoRef.current.srcObject = mediaStream;
      setError('');
    } catch (err) {
      setError('Không thể truy cập camera. Kiểm tra kết nối.');
    }
  };

  const stopCamera = () => {
    if (stream) {
      stream.getTracks().forEach(track => track.stop());
      setStream(null);
    }
  };

  const captureFrame = useCallback(() => {
    if (videoRef.current && canvasRef.current) {
      const video = videoRef.current;
      const canvas = canvasRef.current;
      const context = canvas.getContext('2d');

      if (context && video.videoWidth > 0 && video.videoHeight > 0) {
        // Use exact same crop logic
        const crop = getCropDimensions(video.videoWidth, video.videoHeight);

        canvas.width = crop.w;
        canvas.height = crop.h;

        // Mirror effect for selfie camera
        context.translate(canvas.width, 0);
        context.scale(-1, 1); 

        // Draw the cropped area
        context.drawImage(video, crop.x, crop.y, crop.w, crop.h, 0, 0, canvas.width, canvas.height);

        const dataUrl = canvas.toDataURL('image/jpeg', 1.0);
        onCapture(dataUrl);
      }
    }
  }, [onCapture, selectedSize]);

  useEffect(() => {
    if (countdown === null) return;

    if (countdown > 0) {
      const timer = setTimeout(() => {
        setCountdown(countdown - 1);
      }, 1000);
      return () => clearTimeout(timer);
    } else if (countdown === 0) {
      captureFrame();
      setCountdown(null);
    }
  }, [countdown, captureFrame]);

  const handleCaptureClick = () => {
    // Allows manual override if AI is stuck, but encourages valid state
    setCountdown(3);
  };

  const isUSVisa = selectedSize === PhotoSize.SIZE_5X5;
  const is3x4 = selectedSize === PhotoSize.SIZE_3X4;

  // Determine UI Colors based on Strict State
  const getStatusColor = () => {
    switch (validationStatus) {
      case 'valid': return 'border-green-500 shadow-[0_0_30px_rgba(34,197,94,0.6)]';
      case 'adjusting': return 'border-yellow-400 shadow-[0_0_20px_rgba(250,204,21,0.4)]';
      case 'analyzing': return 'border-blue-400 shadow-[0_0_20px_rgba(96,165,250,0.4)]';
      case 'searching': 
      default: return 'border-red-500 shadow-[0_0_20px_rgba(239,68,68,0.6)]';
    }
  };

  const getOverlayColor = () => {
     switch (validationStatus) {
      case 'valid': return '#22c55e'; // Green
      case 'adjusting': return '#facc15'; // Yellow
      case 'analyzing': return '#60a5fa'; // Blue
      default: return '#ef4444'; // Red
    }
  };

  return (
    <div className="flex flex-col items-center justify-center h-full w-full bg-gray-900 relative select-none">

      {/* Top Bar */}
      <div className="absolute top-0 left-0 right-0 z-50 p-4 flex justify-between items-start bg-gradient-to-b from-black/80 to-transparent pb-12">
        <select 
          value={selectedDeviceId}
          onChange={(e) => setSelectedDeviceId(e.target.value)}
          className="bg-black/50 text-white text-xs border border-gray-600 rounded px-3 py-1.5 outline-none backdrop-blur-md pointer-events-auto"
        >
          <option value="">-- Chọn Camera --</option>
          {devices.map((device, idx) => (
            <option key={device.deviceId || idx} value={device.deviceId}>
              {device.label || `Camera ${idx + 1}`}
            </option>
          ))}
        </select>

        {/* Realtime Feedback Status - LARGE & CENTRAL */}
        <div className={`
          absolute top-16 left-1/2 transform -translate-x-1/2
          px-6 py-3 rounded-xl backdrop-blur-md border-2 flex flex-col items-center gap-1 transition-all duration-300 min-w-[280px] text-center shadow-lg
          ${validationStatus === 'valid' ? 'bg-green-600/90 border-green-400 text-white scale-110' : 
            validationStatus === 'adjusting' ? 'bg-yellow-600/80 border-yellow-400 text-white' :
            validationStatus === 'analyzing' ? 'bg-blue-600/80 border-blue-400 text-white' :
            'bg-red-600/80 border-red-500 text-white'}
        `}>
          <div className="flex items-center gap-2">
             {validationStatus === 'valid' ? (
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M5 13l4 4L19 7"></path></svg>
             ) : (
                <div className="animate-spin w-4 h-4 border-2 border-current border-t-transparent rounded-full" />
             )}
             <span className="font-bold text-sm tracking-wide uppercase">{feedbackMessage}</span>
          </div>
          <span className="text-xs font-medium opacity-90">{instruction}</span>
        </div>
      </div>

      {error && <div className="absolute z-50 bg-red-600 text-white p-4 rounded-lg shadow-xl font-bold animate-pulse">{error}</div>}

      {/* Camera Feed with Aspect Ratio Crop Preview */}
      <div 
        className={`relative transition-all duration-300 bg-black rounded-lg overflow-hidden flex items-center justify-center border-4
          ${isUSVisa ? 'aspect-square h-[75vh]' : is3x4 ? 'aspect-[3/4] h-[75vh]' : 'aspect-[2/3] h-[75vh]'}
          ${getStatusColor()}
        `}
      >
        <video
          ref={videoRef}
          autoPlay
          playsInline
          className="absolute inset-0 w-full h-full object-cover transform -scale-x-100" 
        />

        {/* =============================================
            ENHANCED SVG OVERLAY WITH MASKING
           ============================================= */}
        <div className="relative z-10 w-full h-full">
          {/* Scanning Effect */}
          {(validationStatus === 'searching' || validationStatus === 'analyzing') && (
            <div className="absolute top-0 left-0 w-full h-1 bg-white/80 shadow-[0_0_15px_rgba(255,255,255,1)] animate-[scan_1.5s_ease-in-out_infinite]" />
          )}

          {isUSVisa ? (
            // --- VISA MỸ (5x5) GUIDE ---
            <svg viewBox="0 0 100 100" className="absolute inset-0 w-full h-full opacity-90 pointer-events-none transition-colors duration-300">
               <defs>
                 <mask id="faceMaskUS">
                   <rect x="0" y="0" width="100" height="100" fill="white" />
                   {/* Hole for Face (rx=35, ry=42) */}
                   <ellipse cx="50" cy="50" rx="35" ry="42" fill="black" />
                 </mask>
               </defs>

               {/* Darkened Background (Masked) */}
               <rect x="0" y="0" width="100" height="100" fill="rgba(0,0,0,0.6)" mask="url(#faceMaskUS)" />

               {/* Center Line */}
               <line x1="50" y1="0" x2="50" y2="100" stroke={getOverlayColor()} strokeWidth="0.2" strokeDasharray="2,2" />

               {/* Eye Zone (28mm-35mm from bottom) */}
               <rect x="0" y="31" width="100" height="13" fill={validationStatus === 'valid' ? "rgba(34, 197, 94, 0.15)" : "rgba(239, 68, 68, 0.1)"} stroke="none" />
               <line x1="0" y1="31" x2="100" y2="31" stroke={getOverlayColor()} strokeWidth="0.3" strokeDasharray="4,2" />
               <line x1="0" y1="44" x2="100" y2="44" stroke={getOverlayColor()} strokeWidth="0.3" strokeDasharray="4,2" />

               {/* Head Size Limit Markers */}
               <line x1="40" y1="10" x2="60" y2="10" stroke={getOverlayColor()} strokeWidth="0.5" />
               <text x="50" y="8" fill="white" fontSize="2.5" textAnchor="middle">Đỉnh đầu (Max)</text>

               <line x1="40" y1="88" x2="60" y2="88" stroke={getOverlayColor()} strokeWidth="0.5" />
               <text x="50" y="92" fill="white" fontSize="2.5" textAnchor="middle">Cằm (Min)</text>

               {/* Oval Outline */}
               <ellipse cx="50" cy="50" rx="35" ry="42" fill="none" stroke={getOverlayColor()} strokeWidth={validationStatus === 'valid' ? "1" : "0.5"} strokeDasharray={validationStatus === 'valid' ? "0" : "6,4"} />
            </svg>
          ) : (
             // --- STANDARD 4x6 / 3x4 GUIDE (75% FACE AREA) ---
            <svg viewBox="0 0 100 100" className="absolute inset-0 w-full h-full opacity-90 pointer-events-none transition-colors duration-300">
              <defs>
                 <mask id="faceMaskStd">
                   <rect x="0" y="0" width="100" height="100" fill="white" />
                   {/* Hole for Face (rx=32, ry=42) - Covers ~75% height */}
                   <ellipse cx="50" cy="49" rx="32" ry="42" fill="black" />
                 </mask>
               </defs>

               {/* Darkened Background */}
               <rect x="0" y="0" width="100" height="100" fill="rgba(0,0,0,0.6)" mask="url(#faceMaskStd)" />

              <line x1="50" y1="0" x2="50" y2="100" stroke={getOverlayColor()} strokeWidth="0.2" strokeDasharray="2,2" />

              {/* Top of Head Marker (~8-10%) */}
              <line x1="30" y1="8" x2="70" y2="8" stroke={getOverlayColor()} strokeWidth="0.5" />
              <text x="50" y="6" fill="white" fontSize="2.5" textAnchor="middle" style={{textShadow: '0 1px 2px black'}}>ĐỈNH ĐẦU</text>

              {/* Chin Marker (~90%) */}
              <line x1="35" y1="90" x2="65" y2="90" stroke={getOverlayColor()} strokeWidth="0.5" />
              <text x="50" y="94" fill="white" fontSize="2.5" textAnchor="middle" style={{textShadow: '0 1px 2px black'}}>CẰM</text>

              {/* Eye Line (~40%) */}
              <line x1="15" y1="40" x2="85" y2="40" stroke={getOverlayColor()} strokeWidth="0.5" strokeDasharray="4,4" />
              <text x="88" y="39" fill="white" fontSize="2.5" fontWeight="bold" style={{textShadow: '0 1px 2px black'}}>MẮT</text>

              {/* OVAL GUIDE - 75% AREA */}
              <ellipse cx="50" cy="49" rx="32" ry="42" fill="none" stroke={getOverlayColor()} strokeWidth={validationStatus === 'valid' ? "1" : "0.5"} strokeDasharray={validationStatus === 'valid' ? "0" : "2,2"} />

              <text x="50" y="98" fill="white" fontSize="3" textAnchor="middle" fontWeight="bold" style={{textShadow: '0 1px 2px black'}}>
                {is3x4 ? 'THẺ 3x4 (75% MẶT)' : 'HỘ CHIẾU 4x6 (75% MẶT)'}
              </text>
            </svg>
          )}
        </div>

        {/* Countdown Overlay */}
        {countdown !== null && (
          <div className="absolute inset-0 flex items-center justify-center bg-black/60 z-40 backdrop-blur-sm">
            <span className="text-[120px] font-bold text-white animate-ping">{countdown}</span>
          </div>
        )}
      </div>

      {/* Capture Controls - STRICTLY DISABLED WHEN NOT VALID */}
      <div className="absolute bottom-8 left-0 right-0 flex flex-col justify-end items-center gap-4 z-50 pointer-events-auto">
        <div className={`text-sm font-bold px-4 py-1.5 rounded-full shadow-lg backdrop-blur transition-colors ${validationStatus === 'valid' ? 'bg-green-500 text-white' : 'bg-gray-800/80 text-gray-400'}`}>
           {validationStatus === 'valid' ? '✔ AI CHẤP NHẬN' : '⚠️ AI ĐANG KIỂM TRA QUY ĐỊNH'}
        </div>

        <button
          onClick={handleCaptureClick}
          disabled={countdown !== null}
          className={`
            w-20 h-20 rounded-full border-4 transition-all duration-300 flex items-center justify-center shadow-2xl relative
            ${validationStatus === 'valid' 
              ? 'bg-white border-green-500 hover:border-green-400 hover:scale-105 active:scale-95 cursor-pointer ring-4 ring-green-500/30' 
              : 'bg-gray-700 border-gray-600 opacity-90 cursor-pointer'} 
          `}
        >
           {/* Inner Circle / Lock Icon */}
           <div className={`w-16 h-16 rounded-full transition-all duration-300 flex items-center justify-center ${validationStatus === 'valid' ? 'bg-green-600' : 'bg-gray-600'}`}>
              {validationStatus !== 'valid' && (
                 <svg className="w-8 h-8 text-gray-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M3 9a2 2 0 012-2h.93a2 2 0 001.664-.89l.812-1.22A2 2 0 0110.07 4h3.86a2 2 0 011.664.89l.812 1.22A2 2 0 0018.07 7H19a2 2 0 012 2v9a2 2 0 01-2 2H5a2 2 0 01-2-2V9z"></path><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 13a3 3 0 11-6 0 3 3 0 016 0z"></path></svg>
              )}
           </div>
        </button>
      </div>

      <canvas ref={canvasRef} className="hidden" />
      <canvas ref={analysisCanvasRef} className="hidden" />

      <style>{`
        @keyframes scan {
          0% { top: 0%; opacity: 0; }
          10% { opacity: 1; }
          90% { opacity: 1; }
          100% { top: 100%; opacity: 0; }
        }
      `}</style>
    </div>
  );
};

export default CameraCapture;

import React, { useState, useEffect } from 'react';
import { PhotoSettings, PhotoSize, AppConfig } from '../types';
import { savePhotoToCloud } from '../services/databaseService';

interface PrintPreviewProps {
  processedImage: string;
  size: PhotoSize;
  settings: PhotoSettings;
  onBack: () => void;
  onNew: () => void;
  onSaved?: () => void;
  onHome: () => void;
  config: AppConfig;
}

const PrintPreview: React.FC<PrintPreviewProps> = ({ 
  processedImage, 
  size, 
  settings, 
  onBack, 
  onNew,
  onSaved,
  onHome,
  config
}) => {
  const [isSaving, setIsSaving] = useState(false);
  const [saveSuccess, setSaveSuccess] = useState(false);
  const [downloadProcessing, setDownloadProcessing] = useState(false);

  // Zalo & QR State
  const [phoneNumber, setPhoneNumber] = useState(settings.phoneNumber || config.contactZalo);
  const [isSendingZalo, setIsSendingZalo] = useState(false);
  const [showQR, setShowQR] = useState(false);
  const [photoId] = useState(`ID-${Date.now().toString().slice(-6)}`);

  // Configuration constants
  const DPI = 300; // Print resolution
  const mmToPx = (mm: number) => (mm / 25.4) * DPI;

  // Grid Layout Logic
  const getLayoutConfig = () => {
    if (size === PhotoSize.SIZE_3X4) {
      return {
        cols: 4,
        rows: 4,
        photoW_mm: 30,
        photoH_mm: 40,
        rotated: false,
        maxOnSheet: 16
      };
    } else if (size === PhotoSize.SIZE_5X5) {
      return {
        cols: 2,
        rows: 3,
        photoW_mm: 50,
        photoH_mm: 50,
        rotated: false,
        maxOnSheet: 6
      };
    } else {
      // 4x6 Default - Rotated to Landscape on sheet for efficiency (2x4=8)
      return {
        cols: 2,
        rows: 4,
        photoW_mm: 60, // Slot width (rotated 4x6)
        photoH_mm: 40, // Slot height
        rotated: true, // Needs CSS rotation
        maxOnSheet: 8
      };
    }
  };

  const layout = getLayoutConfig();
  const photosToRender = Math.min(settings.printQuantity, layout.maxOnSheet);

  // Generate QR Data
  const qrDataUrl = `https://photobooth-demo.com/d/${photoId}`;
  const qrImageUrl = `https://api.qrserver.com/v1/create-qr-code/?size=150x150&data=${encodeURIComponent(qrDataUrl)}&color=000000&bgcolor=FFFFFF&margin=0`;

  const handlePrint = () => {
    window.print();
  };

  const handleDownloadSingle = () => {
    const link = document.createElement('a');
    link.href = processedImage;
    link.download = `${photoId}-Single.jpg`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  /**
   * Generates a high-res canvas of the 13x18 sheet and downloads it.
   */
  const handleDownloadSheet = async () => {
    setDownloadProcessing(true);

    try {
      const canvas = document.createElement('canvas');
      const ctx = canvas.getContext('2d');
      if (!ctx) throw new Error("No Canvas Context");

      const width = Math.round(mmToPx(130));
      const height = Math.round(mmToPx(180));

      canvas.width = width;
      canvas.height = height;

      // 1. Draw White Background
      ctx.fillStyle = '#ffffff';
      ctx.fillRect(0, 0, width, height);

      // 2. Load Photo
      const img = new Image();
      img.crossOrigin = "anonymous";
      img.src = processedImage;
      await new Promise((resolve, reject) => {
        img.onload = resolve;
        img.onerror = reject;
      });

      // 3. Draw Grid
      const photoSlotW = Math.round(mmToPx(layout.photoW_mm));
      const photoSlotH = Math.round(mmToPx(layout.photoH_mm));

      const totalContentW = layout.cols * photoSlotW;
      const startX = (width - totalContentW) / 2;
      const startY = Math.round(mmToPx(5)); // 5mm top margin

      for (let i = 0; i < photosToRender; i++) {
        const col = i % layout.cols;
        const row = Math.floor(i / layout.cols);
        const x = startX + col * photoSlotW;
        const y = startY + row * photoSlotH;

        // Note: Removed strokeRect (cut lines/photo code) as per request

        // Draw Image
        if (layout.rotated) {
          // Rotate 90 degrees CCW to fit portrait photo into landscape slot
          ctx.save();
          ctx.translate(x + photoSlotW / 2, y + photoSlotH / 2);
          ctx.rotate(-90 * Math.PI / 180);
          ctx.drawImage(img, -photoSlotH / 2, -photoSlotW / 2, photoSlotH, photoSlotW);
          ctx.restore();
        } else {
          ctx.drawImage(img, x, y, photoSlotW, photoSlotH);
        }
      }

      // 4. Draw Footer Area
      const footerH = Math.round(mmToPx(20)); // 20mm footer
      const footerY = height - footerH;

      ctx.fillStyle = '#f1f5f9'; // Slate-100
      ctx.fillRect(0, footerY, width, footerH);

      // Footer Logo Text (Use Logo Image if available, else text)
      if (config.logoUrl) {
         const logoImg = new Image();
         logoImg.src = config.logoUrl;
         await new Promise(r => { logoImg.onload = r; logoImg.onerror = r; });

         // Keep aspect ratio, max height 14mm
         const maxLogoH = Math.round(mmToPx(14));
         const logoRatio = logoImg.width / logoImg.height;
         const drawW = maxLogoH * logoRatio;
         const drawH = maxLogoH;

         ctx.drawImage(logoImg, Math.round(mmToPx(8)), footerY + Math.round(mmToPx(3)), drawW, drawH);
      } else {
         ctx.fillStyle = '#1e293b'; // Slate-800
         ctx.font = 'bold 50px sans-serif';
         ctx.fillText(config.shopName, Math.round(mmToPx(8)), footerY + Math.round(mmToPx(8)));
      }

      // Footer Info
      ctx.fillStyle = '#64748b'; // Slate-500
      ctx.font = '40px sans-serif';
      const dateStr = new Date().toLocaleDateString('vi-VN');

      const textX = Math.round(mmToPx(8));
      const textY = footerY + Math.round(mmToPx(16)); // Near bottom of footer
      ctx.fillText(`${config.printFooterText} | ${dateStr}`, textX, textY);

      // Footer QR Code
      const qrImg = new Image();
      qrImg.crossOrigin = "anonymous";
      qrImg.src = qrImageUrl;
      await new Promise((resolve) => {
        qrImg.onload = resolve;
        qrImg.onerror = resolve; // Continue even if QR fails
      });

      const qrSize = Math.round(mmToPx(16));
      ctx.drawImage(qrImg, width - qrSize - Math.round(mmToPx(5)), footerY + Math.round(mmToPx(2)), qrSize, qrSize);

      // 5. Download
      const dataUrl = canvas.toDataURL('image/jpeg', 0.95);
      const link = document.createElement('a');
      link.href = dataUrl;
      link.download = `${photoId}-Sheet.jpg`;
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);

    } catch (error) {
      console.error("Sheet generation failed", error);
      alert("Lỗi tạo ảnh khổ in. Vui lòng thử lại.");
    } finally {
      setDownloadProcessing(false);
    }
  };

  const handleSaveToDB = async () => {
    setIsSaving(true);
    const currentSettings = { ...settings, phoneNumber };
    const success = await savePhotoToCloud({
      id: photoId,
      dataUrl: processedImage,
      timestamp: Date.now(),
      settings: currentSettings
    });
    setIsSaving(false);
    if (success) {
      setSaveSuccess(true);
      setTimeout(() => setSaveSuccess(false), 3000);
      if (onSaved) onSaved();
    } else {
      alert("Lỗi khi lưu vào cơ sở dữ liệu");
    }
  };

  const handleSendZalo = async () => {
    if (!phoneNumber || phoneNumber.length < 9) {
      alert("Vui lòng nhập số điện thoại hợp lệ.");
      return;
    }
    setIsSendingZalo(true);
    setTimeout(() => {
      setIsSendingZalo(false);
      alert(`Đã gửi ảnh thành công tới Zalo: ${phoneNumber}`);
    }, 1500);
  };

  // Styles for the visible DOM preview (mimicking the canvas layout)
  const cellW = layout.photoW_mm + 'mm';
  const cellH = layout.photoH_mm + 'mm';

  return (
    <div className="flex flex-col h-full bg-slate-100 relative">

      {/* QR Code Modal */}
      {showQR && (
        <div className="fixed inset-0 z-50 bg-black/60 flex items-center justify-center p-4 backdrop-blur-sm" onClick={() => setShowQR(false)}>
          <div className="bg-white rounded-2xl p-6 max-w-sm w-full shadow-2xl text-center transform transition-all scale-100" onClick={e => e.stopPropagation()}>
            <h3 className="text-xl font-bold text-gray-800 mb-2">Quét mã để tải ảnh</h3>
            <p className="text-sm text-gray-500 mb-4">Sử dụng Camera hoặc Zalo để quét</p>

            <div className="bg-white p-2 rounded-xl border-2 border-brand-100 inline-block mb-4 shadow-inner">
               <img src={qrImageUrl} alt="QR Download" className="w-48 h-48 mix-blend-multiply" />
            </div>
            <p className="font-mono text-xs text-gray-400 mb-4">{photoId}</p>
            <button onClick={() => setShowQR(false)} className="w-full py-3 bg-gray-100 hover:bg-gray-200 text-gray-800 rounded-xl font-bold transition">Đóng</button>
          </div>
        </div>
      )}

      {/* Header */}
      <header className="bg-white shadow-sm p-4 flex justify-between items-center no-print z-20">
        <h1 className="text-xl font-extrabold text-slate-800 flex items-center gap-2">
          <svg className="w-6 h-6 text-brand-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M17 17h2a2 2 0 002-2v-4a2 2 0 00-2-2H5a2 2 0 00-2 2v4a2 2 0 002 2h2m2 4h6a2 2 0 002-2v-4a2 2 0 00-2-2H9a2 2 0 00-2 2v4a2 2 0 002 2zm8-12V5a2 2 0 00-2-2H9a2 2 0 00-2 2v4h10z"></path></svg>
          Print Preview <span className="text-xs bg-slate-100 px-2 py-0.5 rounded text-slate-500 font-normal">Paper: 13x18cm</span>
        </h1>
        <div className="flex gap-3">
          <button onClick={onBack} className="px-4 py-2 text-sm font-bold text-slate-600 hover:bg-slate-100 rounded-lg transition">Chỉnh sửa lại</button>
          <button onClick={onNew} className="px-4 py-2 text-sm font-bold text-white bg-slate-800 hover:bg-black rounded-lg transition shadow-md">Khách mới</button>
        </div>
      </header>

      <div className="flex-1 overflow-hidden flex justify-center items-start gap-8 p-8">

        {/* Print Canvas DOM Container (Visual Preview) */}
        <div className="h-full overflow-auto flex items-center justify-center scrollbar-hide">
            {/* The Sheet */}
            <div 
              className="bg-white shadow-2xl overflow-hidden relative print:shadow-none flex flex-col print:fixed print:top-0 print:left-0 print:m-0" 
              style={{ 
                width: '130mm', 
                height: '180mm', 
                minWidth: '130mm', 
                minHeight: '180mm',
                border: '1px solid #e5e7eb'
              }}
            >
                {/* Photo Grid Area (Top 160mm) */}
                <div 
                  className="w-full flex-1 flex flex-wrap content-start items-start justify-center"
                  style={{ paddingTop: '5mm', paddingBottom: '0' }} // 5mm top margin
                >
                  {Array.from({ length: photosToRender }).map((_, i) => (
                    <div 
                      key={i} 
                      className="overflow-hidden" /* Removed border border-dashed classes */
                      style={{ 
                        width: cellW, 
                        height: cellH,
                        // If rotated, we use flex center to hold the rotated image
                        display: layout.rotated ? 'flex' : 'block',
                        alignItems: 'center',
                        justifyContent: 'center'
                      }}
                    >
                      <img 
                        src={processedImage} 
                        className="object-cover" 
                        style={{
                           width: layout.rotated ? 'auto' : '100%',
                           height: layout.rotated ? '100%' : '100%',
                           // CSS visual rotation to match print logic
                           transform: layout.rotated ? 'rotate(-90deg)' : 'none',
                           // For rotated images, the width becomes the height visually
                           aspectRatio: layout.rotated ? '2/3' : 'auto' 
                        }}
                        alt="ID Photo" 
                      />
                    </div>
                  ))}
                </div>

                {/* Footer Area (Bottom 20mm) */}
                <div className="h-[20mm] bg-slate-50 border-t border-slate-200 flex items-center justify-between px-6">
                    <div className="flex items-center gap-4">
                       {/* DYNAMIC LOGO IN FOOTER PREVIEW */}
                       {config.logoUrl ? (
                          <img src={config.logoUrl} className="h-10 w-auto object-contain max-w-[120px]" alt="Logo" />
                       ) : (
                          <h3 className="font-bold text-slate-800 text-lg leading-tight">{config.shopName}</h3>
                       )}
                       <div>
                          <div className="h-4"></div> {/* Spacer */}
                          <p className="text-xs text-slate-500 font-mono mt-0.5">{config.printFooterText} | Date: {new Date().toLocaleDateString('vi-VN')}</p>
                       </div>
                    </div>
                    <div className="bg-white p-1 rounded border border-slate-200">
                        <img src={qrImageUrl} className="w-[14mm] h-[14mm] mix-blend-multiply opacity-90" alt="QR" />
                    </div>
                </div>
            </div>
        </div>

        {/* Action Panel - Right Sidebar */}
        <div className="w-80 bg-white p-6 rounded-2xl shadow-xl flex flex-col gap-6 no-print h-fit">

          {/* PRIMARY ACTION: PRINT */}
          <div>
            <div className="flex justify-between items-center mb-4">
               <h3 className="font-bold text-gray-800">Thao tác chính</h3>
               <span className="text-xs bg-green-100 text-green-700 px-2 py-1 rounded-full font-bold">{settings.printQuantity} ảnh/tờ</span>
            </div>

            <button 
              onClick={handlePrint}
              className="group w-full py-4 bg-brand-600 hover:bg-brand-700 text-white rounded-xl font-bold text-lg shadow-lg hover:shadow-xl transition-all flex flex-col items-center justify-center gap-1"
            >
              <div className="flex items-center gap-2">
                <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M17 17h2a2 2 0 002-2v-4a2 2 0 00-2-2H5a2 2 0 00-2 2v4a2 2 0 002 2h2m2 4h6a2 2 0 002-2v-4a2 2 0 00-2-2H9a2 2 0 00-2 2v4a2 2 0 002 2zm8-12V5a2 2 0 00-2-2H9a2 2 0 00-2 2v4h10z"></path></svg>
                <span>IN NGAY</span>
              </div>
              <span className="text-[10px] opacity-80 font-normal">Kết nối máy in (Ctrl + P)</span>
            </button>

            <button 
              onClick={handleSaveToDB}
              disabled={isSaving || saveSuccess}
              className={`mt-3 w-full py-2.5 rounded-lg font-bold text-sm transition-all flex items-center justify-center gap-2 ${
                saveSuccess ? 'bg-green-50 text-green-700 border border-green-200' : 'bg-gray-50 hover:bg-gray-100 text-gray-700 border border-gray-200'
              }`}
            >
