                    <input type="range" min="80" max="130" value={settings.brightness} onChange={(e) => onUpdateSettings({...settings, brightness: Number(e.target.value)})} className="w-full h-2 bg-gray-200 rounded-lg appearance-none cursor-pointer accent-brand-600 group-hover:accent-brand-500" />
