export default CameraCapture;

import { GoogleGenAI, Type } from "@google/genai";
import { BackgroundType, BeautySettings, PhotoSize } from "../types";

const API_KEY = process.env.API_KEY || '';

const ai = new GoogleGenAI({ apiKey: API_KEY });

// Schema for the AI Camera analysis response
const analysisSchema = {
  type: Type.OBJECT,
  properties: {
    isCompliant: { type: Type.BOOLEAN },
    status: { type: Type.STRING, enum: ['VALID', 'ADJUSTING', 'INVALID'] },
    feedback: { type: Type.STRING },
    instruction: { type: Type.STRING },
    faceDetected: { type: Type.BOOLEAN }
  },
  required: ['isCompliant', 'status', 'feedback', 'instruction', 'faceDetected']
};

/**
 * Analyzes a webcam frame for ID photo compliance.
 */
export const analyzeIDPhotoFrame = async (base64Frame: string): Promise<{
  isCompliant: boolean;
  status: 'VALID' | 'ADJUSTING' | 'INVALID';
  feedback: string;
  instruction: string;
  faceDetected: boolean;
}> => {
  if (!API_KEY) return { isCompliant: true, status: 'VALID', feedback: 'API Key Missing', instruction: 'Ready', faceDetected: true };

  const cleanBase64 = base64Frame.replace(/^data:image\/(png|jpeg|jpg);base64,/, "");

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: {
        parts: [
          { inlineData: { mimeType: 'image/jpeg', data: cleanBase64 } },
          { text: `You are an automated ID Photo Biometric Compliance System. 
            Analyze this selfie frame for a formal ID/Passport photo.

            Strictly Check:
            1. Face visible and front-facing? (No profile views).
            2. Eyes open and looking at camera?
            3. Mouth closed (neutral expression)?
            4. Head straight (not tilted left/right/up/down)?
            5. Lighting sufficient (not too dark, no harsh shadows)?
            6. No objects covering face (hands, masks, dark glasses)?

            Output JSON. 
            - 'instruction' should be a short, direct command in Vietnamese (e.g., "Mở mắt to hơn", "Nhìn thẳng", "Ngẩng đầu lên").
            - If everything is perfect, 'instruction' should be "Giữ nguyên tư thế".
            ` 
          }
        ]
      },
      config: {
        responseMimeType: 'application/json',
        responseSchema: analysisSchema
      }
    });

    const text = response.text;
    if (!text) throw new Error("No response from AI");

    return JSON.parse(text);

  } catch (error: any) {
    console.error("AI Analysis Error", error);

    // DETECT QUOTA EXHAUSTION (HTTP 429)
    const errorStr = error.toString();
    const isQuotaError = errorStr.includes('429') || 
                         error.message?.includes('quota') || 
                         error.message?.includes('limit') ||
                         error.status === 429;

    if (isQuotaError) {
      return { 
        isCompliant: true, 
        status: 'VALID', 
        feedback: 'AI_LIMIT', 
        instruction: 'Chuyển chế độ thủ công', 
        faceDetected: true 
      };
    }

    // Fallback to valid to not block user in case of generic network error
    return { 
      isCompliant: true, 
      status: 'VALID', 
      feedback: 'Lỗi mạng', 
      instruction: 'Chụp thủ công', 
      faceDetected: true 
    };
  }
};

/**
 * Processes the ID photo with strict biometric preservation rules.
 * CRITICAL: NO CROPPING OR RESIZING ALLOWED IN THIS STEP.
 */
export const processIDPhoto = async (
  imageBase64: string, 
  bgType: BackgroundType, 
  clothingPrompt: string | undefined,
  beautySettings: BeautySettings,
  size: PhotoSize
): Promise<string> => {
  if (!API_KEY) {
    throw new Error("API Key chưa được cấu hình.");
  }

  const cleanBase64 = imageBase64.replace(/^data:image\/(png|jpeg|jpg);base64,/, "");

  // Constructing a structured prompt focused on IN-PLACE EDITING with HARD BIOMETRIC LOCK
  let prompt = `ROLE: Hệ thống bảo mật sinh trắc học & xử lý ảnh thẻ (Biometric Security & ID Photo Editor).
INPUT: Ảnh chân dung gốc.
OUTPUT: Ảnh đã xử lý nhưng BẮT BUỘC giữ nguyên 100% cấu trúc khuôn mặt.

================================================================
⚠️ YÊU CẦU BẮT BUỘC VỀ SINH TRẮC HỌC (ABSOLUTE CONSTRAINT)
================================================================
Trong mọi trường hợp, TUYỆT ĐỐI KHÔNG được:
1. Thay đổi hình dạng khuôn mặt (Face Shape/Jawline/Chin).
2. Biến dạng khuôn mặt dưới bất kỳ hình thức nào (Warping/Morphing).
3. Làm thay đổi đặc điểm nhận dạng sinh trắc học (Eyes, Nose, Mouth coordinates).

Cụ thể, KHÔNG được phép thay đổi:
- Khoảng cách giữa hai mắt.
- Vị trí, kích thước, hình dạng của mắt, mũi, miệng.
- Đường viền hàm, cằm, trán.
- Tỷ lệ tổng thể khuôn mặt.

NẾU việc thay áo hoặc làm đẹp có nguy cơ che lấp cằm, hoặc làm méo mặt:
-> BỎ QUA YÊU CẦU ĐÓ.
-> GIỮ NGUYÊN ẢNH GỐC tại vùng đó.
-> ƯU TIÊN: Sinh trắc học > Trang phục > Phông nền > Làm đẹp.

================================================================
NHIỆM VỤ CỤ THỂ (LAYER-BASED EDITING)
================================================================

LAYER 1: KHUÔN MẶT (LOCKED 🔒)
- Giữ nguyên pixel của mắt, mũi, miệng, khung xương mặt.
- Chỉ cho phép xử lý DA (Skin texture):
`;

  // Beauty Logic - Strict "Texture Only" instructions
  if (beautySettings.smoothSkin > 0) prompt += `  + Làm mịn da nhẹ (High Frequency Separation), giữ lại lỗ chân lông. KHÔNG làm mờ (Blur) đường nét.\n`;
  if (beautySettings.removeBlemishes) prompt += `  + Xóa mụn/thâm đỏ cục bộ. KHÔNG xóa nốt ruồi. KHÔNG xóa sẹo nhận dạng.\n`;
  if (beautySettings.fixLighting) prompt += `  + Cân bằng sáng (Dodge & Burn) nhẹ nhàng. Không thay đổi khối (3D Shape).\n`;
  if (beautySettings.fillHair) prompt += `  + Tóc con lòa xòa có thể xử lý, nhưng đường chân tóc (Hairline) phải giữ nguyên.\n`;

  prompt += `\nLAYER 2: TRANG PHỤC (REPLACEABLE)\n`;
  if (clothingPrompt) {
    prompt += `- Thay trang phục: "${clothingPrompt}".
- QUAN TRỌNG: Cổ áo MỚI phải nằm DƯỚI cằm và DƯỚI đường viền hàm của ảnh gốc.
- KHÔNG ĐƯỢC để cổ áo mới che khuất cằm hoặc làm thay đổi độ dài cổ.
- Ghép nối tự nhiên tại phần cổ, giữ nguyên màu da cổ gốc.`;
  } else {
    prompt += `- Giữ nguyên trang phục gốc.`;
  }

  prompt += `\n\nLAYER 3: PHÔNG NỀN (BACKGROUND)\n`;
  if (bgType === BackgroundType.WHITE) {
    prompt += `- Thay nền bằng TRẮNG TUYỆT ĐỐI (#FFFFFF). Tách tóc chính xác từng sợi.`;
  } else if (bgType === BackgroundType.BLUE) {
    prompt += `- Thay nền bằng XANH DƯƠNG (#0057B7).`;
  } else if (bgType === BackgroundType.GRAY) {
    prompt += `- Thay nền bằng XÁM TRUNG TÍNH (#E5E7EB).`;
  } else {
    prompt += `- Giữ nguyên nền.`;
  }

  prompt += `
================================================================
ĐỊNH DẠNG ĐẦU RA
================================================================
- Trả về ảnh JPEG chất lượng cao.
- Kích thước ảnh đầu ra PHẢI TRÙNG KHỚP hoàn toàn với ảnh đầu vào.
- Nếu không thể thực hiện yêu cầu mà không vi phạm sinh trắc học -> Trả về ảnh gần giống gốc nhất có thể.
`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: {
        parts: [
          {
            inlineData: {
              mimeType: 'image/jpeg',
              data: cleanBase64
            }
          },
          {
            text: prompt
          }
        ]
      }
    });

    const parts = response.candidates?.[0]?.content?.parts;
    if (parts) {
      for (const part of parts) {
        if (part.inlineData && part.inlineData.data) {
          return `data:image/jpeg;base64,${part.inlineData.data}`;
        }
      }
    }

    throw new Error("Không nhận được dữ liệu ảnh từ Gemini.");

  } catch (error) {
    console.error("Gemini processing error:", error);
    throw error;
  }
};

import React, { useState, useEffect, useRef } from 'react';
import { BackgroundType, PhotoSettings, PhotoSize, AppConfig } from '../types';
import { processIDPhoto } from '../services/geminiService';

interface ImageEditorProps {
  originalImage: string;
  settings: PhotoSettings;
  onUpdateSettings: (newSettings: PhotoSettings) => void;
  onProcessedImage: (img: string) => void;
  onNext: () => void;
  onRetake: () => void;
  config: AppConfig;
}

type EditorTab = 'background' | 'beauty' | 'clothing';

const ImageEditor: React.FC<ImageEditorProps> = ({ 
  originalImage, 
  settings, 
  onUpdateSettings,
  onProcessedImage,
  onNext,
  onRetake,
  config
}) => {
  const [processedUrl, setProcessedUrl] = useState<string>(originalImage);
  const [isProcessing, setIsProcessing] = useState(false);
  const [activeTab, setActiveTab] = useState<EditorTab>('background');
  const [loadingAction, setLoadingAction] = useState<string>(''); // For granular feedback

  // Before/After Slider State
  const [sliderPosition, setSliderPosition] = useState(50);
  const imageContainerRef = useRef<HTMLDivElement>(null);
  const isDraggingRef = useRef(false);

  // Local state for UI controls before applying AI
  const [clothingInput, setClothingInput] = useState('');
  const [genderTab, setGenderTab] = useState<'male' | 'female'>('male');
  const [apiError, setApiError] = useState('');
  const [securityWarning, setSecurityWarning] = useState('');

  useEffect(() => {
    if (settings.background !== BackgroundType.ORIGINAL && processedUrl === originalImage) {
      triggerAI(settings.background, undefined, undefined, "Đang tách nền tự động...");
    }
  }, []);

  const filterStyle = {
    filter: `brightness(${settings.brightness}%) contrast(${settings.contrast}%)`,
  };

  // --- CORE AI HANDLER ---
  const triggerAI = async (
    overrideBg?: BackgroundType, 
    overrideClothing?: string,
    overrideBeauty?: any,
    actionName: string = "Đang xử lý..."
  ) => {
    setIsProcessing(true);
    setLoadingAction(actionName);
    setApiError('');
    setSecurityWarning('');

    const effBg = overrideBg !== undefined ? overrideBg : settings.background;
    const effClothing = overrideClothing !== undefined ? overrideClothing : settings.clothingPrompt;
    const effBeauty = overrideBeauty !== undefined ? overrideBeauty : settings.beauty;

    try {
      const isDefault = effBg === BackgroundType.ORIGINAL && !effClothing && 
        Object.values(effBeauty).every(v => !v || v === 0);

      if (isDefault) {
        setProcessedUrl(originalImage);
      } else {
        const result = await processIDPhoto(originalImage, effBg, effClothing, effBeauty, settings.size);
        setProcessedUrl(result);
      }

      onUpdateSettings({ 
        ...settings, 
        background: effBg, 
        clothingPrompt: effClothing,
        beauty: effBeauty 
      });
    } catch (err: any) {
      console.error(err);
      setSecurityWarning("Hiệu ứng này không được phép vì ảnh hưởng sinh trắc học khuôn mặt.");
    } finally {
      setIsProcessing(false);
      setLoadingAction('');
    }
  };

  // --- HANDLERS ---
  const handleBgChange = (bg: BackgroundType) => triggerAI(bg, undefined, undefined, "Đang đổi phông nền...");
  const handleClothingClick = (prompt: string) => {
    setClothingInput(prompt);
    triggerAI(undefined, prompt, undefined, prompt ? "Đang thay trang phục..." : "Đang khôi phục áo gốc...");
  };
  const handleBeautyToggle = (key: keyof typeof settings.beauty) => {
    const newBeauty = { ...settings.beauty, [key]: !settings.beauty[key as keyof typeof settings.beauty] };
    triggerAI(undefined, undefined, newBeauty, "Đang áp dụng làm đẹp...");
  };
  const handleSmoothnessChange = (val: number) => {
    onUpdateSettings({ ...settings, beauty: { ...settings.beauty, smoothSkin: val } });
  };
  const handleSliderMouseUp = () => {
     triggerAI(undefined, undefined, undefined, "Đang làm mịn da...");
  };

  const handleMouseMove = (e: React.MouseEvent | React.TouchEvent) => {
    if (!isDraggingRef.current || !imageContainerRef.current) return;
    const rect = imageContainerRef.current.getBoundingClientRect();
    const clientX = 'touches' in e ? e.touches[0].clientX : e.clientX;
    const x = Math.max(0, Math.min(clientX - rect.left, rect.width));
    setSliderPosition((x / rect.width) * 100);
  };

  const handleFinish = () => {
    const canvas = document.createElement('canvas');
    const img = new Image();
    img.src = processedUrl;
    img.crossOrigin = "anonymous";
    img.onload = () => {
      canvas.width = img.width;
      canvas.height = img.height;
      const ctx = canvas.getContext('2d');
      if (ctx) {
        ctx.filter = `brightness(${settings.brightness}%) contrast(${settings.contrast}%)`;
        ctx.drawImage(img, 0, 0);
        onProcessedImage(canvas.toDataURL('image/jpeg', 0.95));
        onNext();
      }
    };
  };

  // Filter clothing options based on config and gender tab
  const activeClothingOptions = config.clothingOptions.filter(item => item.gender === genderTab);

  return (
    <div className="flex flex-col md:flex-row h-full w-full bg-slate-100 overflow-hidden font-sans"
      onMouseMove={handleMouseMove}
      onTouchMove={handleMouseMove}
      onMouseUp={() => { isDraggingRef.current = false; }}
      onTouchEnd={() => { isDraggingRef.current = false; }}
    >

      {/* LEFT: Sidebar / Controls */}
      <div className="w-full md:w-[420px] bg-white shadow-2xl z-20 flex flex-col h-full border-r border-gray-200">

        {/* Header */}
        <div className="p-5 border-b border-gray-100 bg-white flex justify-between items-center">
          <h2 className="text-xl font-extrabold text-gray-800 flex items-center gap-2">
            <span className="text-brand-600 text-2xl">✨</span> Chỉnh sửa
          </h2>
          <div className="text-[10px] font-bold text-gray-400 uppercase tracking-wider">AI Powered</div>
        </div>

        {/* SEGMENTED CONTROL TABS */}
        <div className="px-5 pt-4 pb-2">
          <div className="flex bg-gray-100 p-1 rounded-xl">
            {(['background', 'beauty', 'clothing'] as EditorTab[]).map((tab) => (
               <button
                key={tab}
                onClick={() => setActiveTab(tab)}
                className={`flex-1 py-3 text-xs font-bold uppercase tracking-wide rounded-lg transition-all duration-200 ${
                  activeTab === tab 
                    ? 'bg-white text-brand-600 shadow-sm' 
                    : 'text-gray-500 hover:text-gray-700'
                }`}
              >
                {tab === 'background' ? 'Phông nền' : tab === 'beauty' ? 'Làm đẹp' : 'Trang phục'}
              </button>
            ))}
          </div>
        </div>

        {/* SCROLLABLE CONTENT */}
        <div className="flex-1 overflow-y-auto p-5 bg-white scrollbar-hide">

          {/* --- BACKGROUND TAB --- */}
          {activeTab === 'background' && (
            <div className="space-y-6 animate-fadeIn">
              <div className="grid grid-cols-2 gap-4">
                {[
                  { type: BackgroundType.WHITE, label: 'Trắng (Visa/ID)', color: 'bg-white border-gray-200' },
                  { type: BackgroundType.BLUE, label: 'Xanh (Hồ sơ)', color: 'bg-[#2792ff]' },
                  { type: BackgroundType.GRAY, label: 'Xám (CV)', color: 'bg-gray-300' },
                  { type: BackgroundType.ORIGINAL, label: 'Ảnh Gốc', color: "bg-[url('https://placehold.co/32x32/png')] bg-cover opacity-50" }
                ].map((bg) => (
                  <button 
                    key={bg.type}
                    onClick={() => handleBgChange(bg.type)} 
                    disabled={isProcessing}
                    className={`relative h-32 rounded-2xl border-2 flex flex-col items-center justify-center gap-3 transition-all group ${
                      settings.background === bg.type 
                        ? 'border-brand-500 bg-brand-50 shadow-md ring-1 ring-brand-200' 
                        : 'border-slate-100 hover:border-brand-200 hover:bg-slate-50'
                    }`}
                  >
                    <div className={`w-12 h-12 rounded-full shadow-inner ${bg.color} ${settings.background === bg.type ? 'ring-2 ring-offset-2 ring-brand-400' : ''}`}></div>
                    <span className={`text-xs font-bold ${settings.background === bg.type ? 'text-brand-700' : 'text-gray-600'}`}>{bg.label}</span>

