}

export enum BackgroundType {
  WHITE = 'white',
  BLUE = 'blue',
  GRAY = 'gray', // Added neutral gray
  ORIGINAL = 'original'
}

export enum AppStep {
  CONFIG = 'config', // New start screen
  CAPTURE = 'capture',
  EDIT = 'edit',
  PRINT = 'print'
}

export interface BeautySettings {
  smoothSkin: number; // 0-5
  skinTone: number;   // -50 (Cool) to +50 (Warm)
  makeupIntensity: number; // 0-100
  lighting: number;   // -50 to +50 (Brightness applied to person)
  contrast: number;   // -50 to +50 (Applied to person)
  removeBlemishes: boolean;
  fillHair: boolean;
}

export interface PhotoSettings {
