import { GoogleGenAI, Type } from "@google/genai";
import { BackgroundType, BeautySettings, PhotoSize } from "../types";

const API_KEY = process.env.API_KEY || '';

const ai = new GoogleGenAI({ apiKey: API_KEY });

// Schema for the AI Camera analysis response
const analysisSchema = {
  type: Type.OBJECT,
  properties: {
    isCompliant: { type: Type.BOOLEAN },
    status: { type: Type.STRING, enum: ['VALID', 'ADJUSTING', 'INVALID'] },
    feedback: { type: Type.STRING },
    instruction: { type: Type.STRING },
    faceDetected: { type: Type.BOOLEAN }
  },
  required: ['isCompliant', 'status', 'feedback', 'instruction', 'faceDetected']
};

/**
 * Analyzes a webcam frame for ID photo compliance.
 */
export const analyzeIDPhotoFrame = async (base64Frame: string): Promise<{
  isCompliant: boolean;
  status: 'VALID' | 'ADJUSTING' | 'INVALID';
  feedback: string;
  instruction: string;
  faceDetected: boolean;
}> => {
  if (!API_KEY) return { isCompliant: true, status: 'VALID', feedback: 'API Key Missing', instruction: 'Ready', faceDetected: true };

  const cleanBase64 = base64Frame.replace(/^data:image\/(png|jpeg|jpg);base64,/, "");

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: {
        parts: [
          { inlineData: { mimeType: 'image/jpeg', data: cleanBase64 } },
          { text: `You are an automated ID Photo Biometric Compliance System. 
            Analyze this selfie frame for a formal ID/Passport photo.

            Strictly Check:
            1. Face visible and front-facing? (No profile views).
            2. Eyes open and looking at camera?
            3. Mouth closed (neutral expression)?
            4. Head straight (not tilted left/right/up/down)?
            5. Lighting sufficient (not too dark, no harsh shadows)?
            6. No objects covering face (hands, masks, dark glasses)?

            Output JSON. 
            - 'instruction' should be a short, direct command in Vietnamese (e.g., "Mở mắt to hơn", "Nhìn thẳng", "Ngẩng đầu lên").
            - If everything is perfect, 'instruction' should be "Giữ nguyên tư thế".
            ` 
          }
        ]
      },
      config: {
        responseMimeType: 'application/json',
        responseSchema: analysisSchema
      }
    });

    const text = response.text;
    if (!text) throw new Error("No response from AI");

    return JSON.parse(text);

  } catch (error: any) {
    console.error("AI Analysis Error", error);

    // DETECT QUOTA EXHAUSTION (HTTP 429)
    const errorStr = error.toString();
    const isQuotaError = errorStr.includes('429') || 
                         error.message?.includes('quota') || 
                         error.message?.includes('limit') ||
                         error.status === 429;

    if (isQuotaError) {
      return { 
        isCompliant: true, 
        status: 'VALID', 
        feedback: 'AI_LIMIT', 
        instruction: 'Chuyển chế độ thủ công', 
        faceDetected: true 
      };
    }

    // Fallback to valid to not block user in case of generic network error
    return { 
      isCompliant: true, 
      status: 'VALID', 
      feedback: 'Lỗi mạng', 
      instruction: 'Chụp thủ công', 
      faceDetected: true 
    };
  }
};

/**
 * Processes the ID photo with strict biometric preservation rules.
 * CRITICAL: NO CROPPING OR RESIZING ALLOWED IN THIS STEP.
 */
export const processIDPhoto = async (
  imageBase64: string, 
  bgType: BackgroundType, 
  clothingPrompt: string | undefined,
  beautySettings: BeautySettings,
  size: PhotoSize
): Promise<string> => {
  if (!API_KEY) {
    throw new Error("API Key chưa được cấu hình.");
  }

  const cleanBase64 = imageBase64.replace(/^data:image\/(png|jpeg|jpg);base64,/, "");

  // Build Background Instruction
  let bgInstruction = "";
  if (bgType === BackgroundType.WHITE) {
    bgInstruction = "REPLACE BACKGROUND with PURE WHITE (#FFFFFF). Hair must be perfectly segmented.";
  } else if (bgType === BackgroundType.BLUE) {
    bgInstruction = "REPLACE BACKGROUND with STANDARD ID BLUE (#0057B7).";
  } else if (bgType === BackgroundType.GRAY) {
    bgInstruction = "REPLACE BACKGROUND with NEUTRAL GRAY (#E5E7EB).";
  } else {
    bgInstruction = "KEEP ORIGINAL BACKGROUND.";
  }

  // Build Beauty Instructions
  let beautyInstructions = [];
  if (beautySettings.smoothSkin > 0) beautyInstructions.push(`Skin Smoothing: Level ${beautySettings.smoothSkin}/5 (Retain pores, remove only noise)`);
  if (beautySettings.removeBlemishes) beautyInstructions.push(`Blemish Removal: YES (Acne/Spots only, keep moles)`);

  if (beautySettings.makeupIntensity > 0) {
    beautyInstructions.push(`Light Makeup: Level ${beautySettings.makeupIntensity}% (Natural formal style)`);
  }

  if (beautySettings.skinTone !== 0) {
    const toneDir = beautySettings.skinTone > 0 ? "WARMER" : "COOLER";
    beautyInstructions.push(`Skin Tone Correction: Make skin ${toneDir} by ${Math.abs(beautySettings.skinTone)}%`);
  }

  if (beautySettings.lighting !== 0) {
    const lightDir = beautySettings.lighting > 0 ? "BRIGHTER" : "DARKER";
    beautyInstructions.push(`Subject Brightness: Make subject ${lightDir} by ${Math.abs(beautySettings.lighting)}%`);
  }

  if (beautySettings.contrast !== 0) {
     const contrastDir = beautySettings.contrast > 0 ? "INCREASE" : "DECREASE";
     beautyInstructions.push(`Subject Contrast: ${contrastDir} by ${Math.abs(beautySettings.contrast)}%`);
  }

  if (beautySettings.fillHair) beautyInstructions.push(`Hair Fix: Tame stray hairs, fill gaps.`);

  // Constructing a structured prompt focused on IN-PLACE EDITING with HARD BIOMETRIC LOCK
  let prompt = `ROLE: Biometric ID Photo Editor.
INPUT: Portrait photo.
OUTPUT: Processed ID Photo.

================================================================
MASKING & TARGETING RULES (CRITICAL)
================================================================
1. **TARGET**: All beauty, lighting, and contrast adjustments below apply ONLY to the SUBJECT (Face, Body, Clothes).
2. **PROTECT**: The BACKGROUND must remain EXACTLY as specified in the Background Instruction. Do NOT apply brightness/contrast filters to the background color.

================================================================
LAYER 1: BIOMETRIC PRESERVATION (LOCKED 🔒)
================================================================
- DO NOT CHANGE: Face shape, eye distance, jawline, nose shape, ear shape.
- DO NOT ADD: Text, watermarks, hex codes.

================================================================
LAYER 2: BEAUTY & ADJUSTMENTS (SUBJECT ONLY)
================================================================
${beautyInstructions.map(i => `- ${i}`).join('\n')}

================================================================
LAYER 3: CLOTHING (OPTIONAL)
================================================================
${clothingPrompt ? `- REPLACE CLOTHES WITH: "${clothingPrompt}" (Ensure collar is below chin).` : '- Keep original clothes.'}

================================================================
LAYER 4: BACKGROUND (FINAL)
================================================================
- ${bgInstruction}

Process now. Return high-quality JPEG.
`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: {
        parts: [
          {
            inlineData: {
              mimeType: 'image/jpeg',
              data: cleanBase64
            }
          },
          {
            text: prompt
          }
        ]
      }
    });

    const parts = response.candidates?.[0]?.content?.parts;
    if (parts) {
      for (const part of parts) {
        if (part.inlineData && part.inlineData.data) {
          return `data:image/jpeg;base64,${part.inlineData.data}`;
        }
      }
    }

    throw new Error("Không nhận được dữ liệu ảnh từ Gemini.");

  } catch (error) {
    console.error("Gemini processing error:", error);
    throw error;
  }
};

import React, { useState } from 'react';
import StartScreen from './StartScreen';
import CameraCapture from './CameraCapture';
import ImageEditor from './ImageEditor';
import PrintPreview from './PrintPreview';
import { AppStep, BackgroundType, PhotoSettings, PhotoSize, SavedPhoto, AppConfig } from '../types';

interface PhotoBoothProps {
  onSaveToGallery?: () => void;
  initialPhoto?: SavedPhoto | null;
  onHome: () => void;
  config: AppConfig;
}

const PhotoBooth: React.FC<PhotoBoothProps> = ({ onSaveToGallery, initialPhoto, onHome, config }) => {
  // If loading from gallery, skip config and capture, go to print
  const [step, setStep] = useState<AppStep>(initialPhoto ? AppStep.PRINT : AppStep.CONFIG);

  // Data State
  const [capturedImage, setCapturedImage] = useState<string>(initialPhoto ? initialPhoto.dataUrl : '');
  const [processedImage, setProcessedImage] = useState<string>(initialPhoto ? initialPhoto.dataUrl : '');

  // Settings State
  const [settings, setSettings] = useState<PhotoSettings>(initialPhoto ? initialPhoto.settings : {
    size: PhotoSize.SIZE_4X6, // Default
    background: BackgroundType.WHITE,
    clothingPrompt: undefined,
    beauty: {
      smoothSkin: 0,
      skinTone: 0,
      makeupIntensity: 0,
      lighting: 0,
      contrast: 0,
      removeBlemishes: false,
      fillHair: false
    },
    printQuantity: 4,
    phoneNumber: config.contactZalo // Default phone from config
  });

  const handleStartConfig = (config: { size: PhotoSize; background: BackgroundType; quantity: number }) => {
    setSettings({
      ...settings,
      size: config.size,
      background: config.background,
      printQuantity: config.quantity
    });
    setStep(AppStep.CAPTURE);
  };

  const handleCapture = (imageSrc: string) => {
    setCapturedImage(imageSrc);
    setStep(AppStep.EDIT);
  };

  const handleProcessedImage = (img: string) => {
    setProcessedImage(img);
  };

  const resetFlow = () => {
    setCapturedImage('');
    setProcessedImage('');
    // Go back to start screen to allow choosing new customer type
    setStep(AppStep.CONFIG); 
  };

  const handleRetake = () => {
    setCapturedImage('');
    setStep(AppStep.CAPTURE);
  };

  return (
    <div className="h-full w-full">
      {step === AppStep.CONFIG && (
        <StartScreen onStart={handleStartConfig} onHome={onHome} config={config} />
      )}

      {step === AppStep.CAPTURE && (
        <CameraCapture 
          onCapture={handleCapture}
          selectedSize={settings.size}
          // In this flow, we don't usually change size during capture anymore, but we keep the handler if needed
          onSizeChange={(s) => setSettings({...settings, size: s})}
        />
      )}

      {step === AppStep.EDIT && (
        <ImageEditor 
          originalImage={capturedImage}
          settings={settings}
          onUpdateSettings={setSettings}
          onProcessedImage={handleProcessedImage}
          onNext={() => setStep(AppStep.PRINT)}
          onRetake={handleRetake}
          config={config}
        />
      )}

      {step === AppStep.PRINT && (
        <PrintPreview 
          processedImage={processedImage}
          size={settings.size}
          settings={settings}
          onBack={() => setStep(AppStep.EDIT)}
          onNew={resetFlow}
          onSaved={onSaveToGallery}
          onHome={onHome}
          config={config}
        />
      )}
    </div>
  );
};

export default PhotoBooth;

export enum PhotoSize {
  SIZE_3X4 = '3x4',
  SIZE_4X6 = '4x6',
  SIZE_5X5 = '5x5' // US Visa / International
}

export enum BackgroundType {
  WHITE = 'white',
  BLUE = 'blue',
  GRAY = 'gray', // Added neutral gray
  ORIGINAL = 'original'
}

export enum AppStep {
  CONFIG = 'config', // New start screen
  CAPTURE = 'capture',
  EDIT = 'edit',
  PRINT = 'print'
}

export enum SkinToneType {
  NATURAL = 'natural', // Tự nhiên
  FAIR = 'fair',       // Trắng sáng
  ROSY = 'rosy',       // Trắng hồng
  TAN = 'tan'          // Ngăm khỏe
}

export interface BeautySettings {
  // Skin
  smoothSkin: number;        // 0-5
  removeBlemishes: boolean;

  // Skin Tone Detailed
  skinToneType: SkinToneType;
  skinToneIntensity: number; // 0-100 (How much to apply the tone)

  // Lighting & Contrast (Subject Only)
  lighting: number;          // -50 to +50
  contrast: number;          // -50 to +50

  // Detailed Makeup
  lipstickColor: string;     // 'red', 'pink', 'orange', 'nude'
  lipstickIntensity: number; // 0-100

  eyebrowIntensity: number;  // 0-100 (Darken/Define)
  contourIntensity: number;  // 0-100
  blushIntensity: number;    // 0-100

  fillHair: boolean;
}

export interface PhotoSettings {
  size: PhotoSize;
  background: BackgroundType;
  clothingPrompt?: string;
  beauty: BeautySettings; 
  printQuantity: number;
  phoneNumber?: string; 
}

export interface SavedPhoto {
  id: string;
  dataUrl: string;
  timestamp: number;
  settings: PhotoSettings;
}

export interface ClothingItem {
  id: string;
  label: string;
  gender: 'male' | 'female';
  icon: string; // Emoji or URL
  prompt: string;
  color: string; // Tailwind class for border/bg
}

export interface AppConfig {
  shopName: string;
  welcomeTitle: string;
  welcomeSubtitle: string;
  contactPhone: string;
  contactZalo: string;
  printFooterText: string;
  themeColorHex: string; // Base HEX color to generate brand palette
  clothingOptions: ClothingItem[];
  adminPassword?: string; // Optional for backward compatibility, defaults to 'admin'
  logoUrl?: string; // Base64 or URL string
}

