export default ImageEditor;

import { GoogleGenAI, Type } from "@google/genai";
import { BackgroundType, BeautySettings, PhotoSize, SkinToneType } from "../types";

const API_KEY = process.env.API_KEY || '';

const ai = new GoogleGenAI({ apiKey: API_KEY });

// Schema for the AI Camera analysis response
const analysisSchema = {
  type: Type.OBJECT,
  properties: {
    isCompliant: { type: Type.BOOLEAN },
    status: { type: Type.STRING, enum: ['VALID', 'ADJUSTING', 'INVALID'] },
    feedback: { type: Type.STRING },
    instruction: { type: Type.STRING },
    faceDetected: { type: Type.BOOLEAN }
  },
  required: ['isCompliant', 'status', 'feedback', 'instruction', 'faceDetected']
};

/**
 * Analyzes a webcam frame for ID photo compliance.
 */
export const analyzeIDPhotoFrame = async (base64Frame: string): Promise<{
  isCompliant: boolean;
  status: 'VALID' | 'ADJUSTING' | 'INVALID';
  feedback: string;
  instruction: string;
  faceDetected: boolean;
}> => {
  if (!API_KEY) return { isCompliant: true, status: 'VALID', feedback: 'API Key Missing', instruction: 'Ready', faceDetected: true };

  const cleanBase64 = base64Frame.replace(/^data:image\/(png|jpeg|jpg);base64,/, "");

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: {
        parts: [
          { inlineData: { mimeType: 'image/jpeg', data: cleanBase64 } },
          { text: `You are an automated ID Photo Biometric Compliance System. 
            Analyze this selfie frame for a formal ID/Passport photo.

            Strictly Check:
            1. Face visible and front-facing? (No profile views).
            2. Eyes open and looking at camera?
            3. Mouth closed (neutral expression)?
            4. Head straight (not tilted left/right/up/down)?
            5. Lighting sufficient (not too dark, no harsh shadows)?
            6. No objects covering face (hands, masks, dark glasses)?

            Output JSON. 
            - 'instruction' should be a short, direct command in Vietnamese (e.g., "Mở mắt to hơn", "Nhìn thẳng", "Ngẩng đầu lên").
            - If everything is perfect, 'instruction' should be "Giữ nguyên tư thế".
            ` 
          }
        ]
      },
      config: {
        responseMimeType: 'application/json',
        responseSchema: analysisSchema
      }
    });

    const text = response.text;
    if (!text) throw new Error("No response from AI");

    return JSON.parse(text);

  } catch (error: any) {
    console.error("AI Analysis Error", error);

    // DETECT QUOTA EXHAUSTION (HTTP 429)
    const errorStr = error.toString();
    const isQuotaError = errorStr.includes('429') || 
                         error.message?.includes('quota') || 
                         error.message?.includes('limit') ||
                         error.status === 429;

    if (isQuotaError) {
      return { 
        isCompliant: true, 
        status: 'VALID', 
        feedback: 'AI_LIMIT', 
        instruction: 'Chuyển chế độ thủ công', 
        faceDetected: true 
      };
    }

    // Fallback to valid to not block user in case of generic network error
    return { 
      isCompliant: true, 
      status: 'VALID', 
      feedback: 'Lỗi mạng', 
      instruction: 'Chụp thủ công', 
      faceDetected: true 
    };
  }
};

/**
 * Processes the ID photo with strict biometric preservation rules.
 * CRITICAL: NO CROPPING OR RESIZING ALLOWED IN THIS STEP.
 */
export const processIDPhoto = async (
  imageBase64: string, 
  bgType: BackgroundType, 
  clothingPrompt: string | undefined,
  beautySettings: BeautySettings,
  size: PhotoSize
): Promise<string> => {
  if (!API_KEY) {
    throw new Error("API Key chưa được cấu hình.");
  }

  const cleanBase64 = imageBase64.replace(/^data:image\/(png|jpeg|jpg);base64,/, "");

  // Build Background Instruction
  let bgInstruction = "";
  if (bgType === BackgroundType.WHITE) {
    bgInstruction = "REPLACE BACKGROUND with PURE WHITE (#FFFFFF). Hair must be perfectly segmented.";
  } else if (bgType === BackgroundType.BLUE) {
    bgInstruction = "REPLACE BACKGROUND with STANDARD ID BLUE (#0057B7).";
  } else if (bgType === BackgroundType.GRAY) {
    bgInstruction = "REPLACE BACKGROUND with NEUTRAL GRAY (#E5E7EB).";
  } else {
    bgInstruction = "KEEP ORIGINAL BACKGROUND.";
  }

  // Build Beauty Instructions
  let beautyInstructions = [];

  // 1. Skin Texture
  if (beautySettings.smoothSkin > 0) beautyInstructions.push(`Skin Smoothing: Level ${beautySettings.smoothSkin}/5 (Retain pores, remove only noise)`);
  if (beautySettings.removeBlemishes) beautyInstructions.push(`Blemish Removal: YES (Acne/Spots only, keep moles)`);

  // 2. Skin Tone
  if (beautySettings.skinToneIntensity > 0 && beautySettings.skinToneType !== SkinToneType.NATURAL) {
      let toneDesc = "";
      switch(beautySettings.skinToneType) {
          case SkinToneType.FAIR: toneDesc = "FAIR/LIGHT (Trắng sáng)"; break;
          case SkinToneType.ROSY: toneDesc = "ROSY/PINKISH (Trắng hồng)"; break;
          case SkinToneType.TAN: toneDesc = "TAN/HEALTHY (Ngăm khỏe)"; break;
      }
      beautyInstructions.push(`Skin Tone Adjustment: Apply ${toneDesc} tone. Intensity: ${beautySettings.skinToneIntensity}%.`);
  }

  // 3. Lighting & Contrast
  if (beautySettings.lighting !== 0) {
    const lightDir = beautySettings.lighting > 0 ? "BRIGHTER" : "DARKER";
    beautyInstructions.push(`Subject Brightness: Make subject ${lightDir} by ${Math.abs(beautySettings.lighting)}%`);
  }

  if (beautySettings.contrast !== 0) {
     const contrastDir = beautySettings.contrast > 0 ? "INCREASE" : "DECREASE";
     beautyInstructions.push(`Subject Contrast: ${contrastDir} by ${Math.abs(beautySettings.contrast)}%`);
  }

  // 4. Makeup Details
  if (beautySettings.lipstickIntensity > 0) {
      beautyInstructions.push(`Lipstick: Apply ${beautySettings.lipstickColor} lipstick. Intensity: ${beautySettings.lipstickIntensity}%. (Keep natural lip shape).`);
  }

  if (beautySettings.eyebrowIntensity > 0) {
      beautyInstructions.push(`Eyebrows: Darken and define eyebrows. Intensity: ${beautySettings.eyebrowIntensity}%.`);
  }

  if (beautySettings.blushIntensity > 0) {
      beautyInstructions.push(`Blush: Apply subtle pink/peach blush to cheeks. Intensity: ${beautySettings.blushIntensity}%.`);
  }

  if (beautySettings.contourIntensity > 0) {
      beautyInstructions.push(`Contour: Apply light facial contouring to define structure. Intensity: ${beautySettings.contourIntensity}%.`);
  }

  if (beautySettings.fillHair) beautyInstructions.push(`Hair Fix: Tame stray hairs, fill gaps.`);

  // Constructing a structured prompt focused on IN-PLACE EDITING with HARD BIOMETRIC LOCK
  let prompt = `ROLE: Biometric ID Photo Editor.
INPUT: Portrait photo.
OUTPUT: Processed ID Photo.

================================================================
MASKING & TARGETING RULES (CRITICAL)
================================================================
1. **TARGET**: All beauty, lighting, and contrast adjustments below apply ONLY to the SUBJECT (Face, Body, Clothes).
2. **PROTECT**: The BACKGROUND must remain EXACTLY as specified in the Background Instruction. Do NOT apply brightness/contrast filters to the background color.

================================================================
LAYER 1: BIOMETRIC PRESERVATION (LOCKED 🔒)
================================================================
- DO NOT CHANGE: Face shape, eye distance, jawline, nose shape, ear shape.
- DO NOT ADD: Text, watermarks, hex codes.

================================================================
LAYER 2: BEAUTY & ADJUSTMENTS (SUBJECT ONLY)
================================================================
${beautyInstructions.map(i => `- ${i}`).join('\n')}

================================================================
LAYER 3: CLOTHING (OPTIONAL)
================================================================
${clothingPrompt ? `- REPLACE CLOTHES WITH: "${clothingPrompt}" (Ensure collar is below chin).` : '- Keep original clothes.'}

================================================================
LAYER 4: BACKGROUND (FINAL)
================================================================
- ${bgInstruction}

Process now. Return high-quality JPEG.
`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: {
        parts: [
          {
            inlineData: {
              mimeType: 'image/jpeg',
              data: cleanBase64
            }
          },
          {
            text: prompt
          }
        ]
      }
    });

    const parts = response.candidates?.[0]?.content?.parts;
    if (parts) {
      for (const part of parts) {
        if (part.inlineData && part.inlineData.data) {
          return `data:image/jpeg;base64,${part.inlineData.data}`;
        }
      }
    }

    throw new Error("Không nhận được dữ liệu ảnh từ Gemini.");

  } catch (error) {
    console.error("Gemini processing error:", error);
    throw error;
  }
};

import { GoogleGenAI, Type } from "@google/genai";
import { BackgroundType, BeautySettings, PhotoSize, SkinToneType } from "../types";

const API_KEY = process.env.API_KEY || '';

const ai = new GoogleGenAI({ apiKey: API_KEY });

// Schema for the AI Camera analysis response
const analysisSchema = {
  type: Type.OBJECT,
  properties: {
    isCompliant: { type: Type.BOOLEAN },
    status: { type: Type.STRING, enum: ['VALID', 'ADJUSTING', 'INVALID'] },
    feedback: { type: Type.STRING },
    instruction: { type: Type.STRING },
    faceDetected: { type: Type.BOOLEAN }
  },
  required: ['isCompliant', 'status', 'feedback', 'instruction', 'faceDetected']
};

/**
 * Analyzes a webcam frame for ID photo compliance.
 */
export const analyzeIDPhotoFrame = async (base64Frame: string): Promise<{
  isCompliant: boolean;
  status: 'VALID' | 'ADJUSTING' | 'INVALID';
  feedback: string;
  instruction: string;
  faceDetected: boolean;
}> => {
  if (!API_KEY) return { isCompliant: true, status: 'VALID', feedback: 'API Key Missing', instruction: 'Ready', faceDetected: true };

  const cleanBase64 = base64Frame.replace(/^data:image\/(png|jpeg|jpg);base64,/, "");

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: {
        parts: [
          { inlineData: { mimeType: 'image/jpeg', data: cleanBase64 } },
          { text: `You are an automated ID Photo Biometric Compliance System. 
            Analyze this selfie frame for a formal ID/Passport photo.

            Strictly Check:
            1. Face visible and front-facing? (No profile views).
            2. Eyes open and looking at camera?
            3. Mouth closed (neutral expression)?
            4. Head straight (not tilted left/right/up/down)?
            5. Lighting sufficient (not too dark, no harsh shadows)?
            6. No objects covering face (hands, masks, dark glasses)?

            Output JSON. 
            - 'instruction' should be a short, direct command in Vietnamese (e.g., "Mở mắt to hơn", "Nhìn thẳng", "Ngẩng đầu lên").
            - If everything is perfect, 'instruction' should be "Giữ nguyên tư thế".
            ` 
          }
        ]
      },
      config: {
        responseMimeType: 'application/json',
        responseSchema: analysisSchema
      }
    });

    const text = response.text;
    if (!text) throw new Error("No response from AI");

    return JSON.parse(text);

  } catch (error: any) {
    console.error("AI Analysis Error", error);

    const errorStr = error.toString();
    const isQuotaError = errorStr.includes('429') || 
                         error.message?.includes('quota') || 
                         error.message?.includes('limit') ||
                         error.status === 429;

    if (isQuotaError) {
      return { 
        isCompliant: true, 
        status: 'VALID', 
        feedback: 'AI_LIMIT', 
        instruction: 'Chuyển chế độ thủ công', 
        faceDetected: true 
      };
    }

    return { 
      isCompliant: true, 
      status: 'VALID', 
      feedback: 'Lỗi mạng', 
      instruction: 'Chụp thủ công', 
      faceDetected: true 
    };
  }
};

/**
 * Processes the ID photo with strict Layer-based logic.
 */
export const processIDPhoto = async (
  imageBase64: string, 
  bgType: BackgroundType, 
  clothingPrompt: string | undefined,
  beautySettings: BeautySettings,
  size: PhotoSize
): Promise<string> => {
  if (!API_KEY) {
    throw new Error("API Key chưa được cấu hình.");
  }

  const cleanBase64 = imageBase64.replace(/^data:image\/(png|jpeg|jpg);base64,/, "");

  // --- LAYER 3: BACKGROUND CONFIG ---
  let bgInstruction = "";
  if (bgType === BackgroundType.WHITE) {
    bgInstruction = "Layer 4 Action: MASK SUBJECT preciseley. FILL BACKGROUND with Pure White (#FFFFFF).";
  } else if (bgType === BackgroundType.BLUE) {
    bgInstruction = "Layer 4 Action: MASK SUBJECT preciseley. FILL BACKGROUND with ID Blue (#0057B7).";
  } else if (bgType === BackgroundType.GRAY) {
    bgInstruction = "Layer 4 Action: MASK SUBJECT preciseley. FILL BACKGROUND with Neutral Gray (#E5E7EB).";
  } else {
    bgInstruction = "Layer 4 Action: Keep Original Background.";
  }

  // --- LAYER 2: CLOTHING CONFIG ---
  let clothingInstruction = "";
  if (clothingPrompt) {
    clothingInstruction = `Layer 3 Action (Clothing): REPLACE current clothes with "${clothingPrompt}". 
    CRITICAL: The collar must sit naturally BELOW the chin/jawline. Do not obscure the chin. Match skin tone at neck.`;
  } else {
    clothingInstruction = "Layer 3 Action (Clothing): Preserve original clothing.";
  }

  // --- LAYER 1: BEAUTY & SKIN CONFIG ---
  let beautyOps = [];

  // Skin Texture
  if (beautySettings.smoothSkin > 0) beautyOps.push(`- Texture: Smooth skin surface (Level ${beautySettings.smoothSkin}/5) while KEEPING facial structure landmarks.`);
  if (beautySettings.removeBlemishes) beautyOps.push(`- Texture: Remove temporary acne/redness. KEEP permanent moles/scars.`);

  // Skin Tone
  if (beautySettings.skinToneIntensity > 0 && beautySettings.skinToneType !== SkinToneType.NATURAL) {
      let toneDesc = "";
      switch(beautySettings.skinToneType) {
          case SkinToneType.FAIR: toneDesc = "Fair/Bright (Sáng)"; break;
          case SkinToneType.ROSY: toneDesc = "Rosy/Pinkish (Hồng hào)"; break;
          case SkinToneType.TAN: toneDesc = "Tan/Bronze (Ngăm khỏe)"; break;
      }
      beautyOps.push(`- Color Grading: Shift skin tone towards ${toneDesc} at ${beautySettings.skinToneIntensity}% opacity.`);
  }

  // Lighting & Contrast
  if (beautySettings.lighting !== 0) {
    const lightDir = beautySettings.lighting > 0 ? "Brighten" : "Darken";
    beautyOps.push(`- Lighting: ${lightDir} the subject face/body by ${Math.abs(beautySettings.lighting)}%. Do not affect background.`);
  }

  if (beautySettings.contrast !== 0) {
     const contrastDir = beautySettings.contrast > 0 ? "Increase" : "Decrease";
     beautyOps.push(`- Contrast: ${contrastDir} contrast on subject by ${Math.abs(beautySettings.contrast)}%.`);
  }

  // Makeup (Virtual Overlay)
  if (beautySettings.lipstickIntensity > 0) {
      beautyOps.push(`- Makeup (Lips): Apply ${beautySettings.lipstickColor} lipstick. Opacity: ${beautySettings.lipstickIntensity}%. Strictly adhere to original lip boundaries.`);
  }

  if (beautySettings.eyebrowIntensity > 0) {
      beautyOps.push(`- Makeup (Brows): Darken/Define eyebrows. Opacity: ${beautySettings.eyebrowIntensity}%.`);
  }

  if (beautySettings.blushIntensity > 0) {
      beautyOps.push(`- Makeup (Cheeks): Apply soft blush. Opacity: ${beautySettings.blushIntensity}%.`);
  }

  if (beautySettings.contourIntensity > 0) {
      beautyOps.push(`- Makeup (Face): Apply soft contouring shadows. Opacity: ${beautySettings.contourIntensity}%.`);
  }

  if (beautySettings.fillHair) beautyOps.push(`- Hair: Tame stray hairs (flyaways) on the outer perimeter.`);

  const beautyInstructionBlock = beautyOps.length > 0 
    ? `Layer 2 Action (Beauty & Retouching):\n${beautyOps.join('\n')}` 
    : "Layer 2 Action: No beauty changes.";

  // --- FINAL PROMPT CONSTRUCTION ---
  let prompt = `ROLE: Advanced Image Compositor & Biometric ID Specialist.
TASK: Process the input image through a strict 4-Layer Pipeline. 
OUTPUT: Return the Final Composite Image.

================================================================
🔒 LAYER 0: BIOMETRIC BASE (LOCKED - IMMUTABLE)
================================================================
- DEFINITION: The geometric structure of the face (Eyes, Nose, Mouth, Jawline, Chin, Ears).
- RULE: ZERO TOLERANCE for warping, morphing, or reshaping. 
- The distance between eyes, nose width, and mouth shape MUST be pixel-perfect to original.
- IDENTITY MUST BE PRESERVED 100%.

================================================================
🎨 LAYER 1: BEAUTY & RETOUCHING (SURFACE ONLY)
================================================================
- TARGET: Skin texture and Color pixels ONLY. Do not move edges.
${beautyInstructionBlock}

================================================================
👕 LAYER 2: CLOTHING (OVERLAY)
================================================================
- TARGET: Area below the neck.
${clothingInstruction}
- CONSTRAINT: Clothing layer must NOT overlap the chin or face (Layer 0).

================================================================
🖼️ LAYER 3: BACKGROUND (BOTTOM LAYER)
================================================================
- TARGET: All pixels NOT part of the Subject (Layer 0, 1, 2).
${bgInstruction}
- CONSTRAINT: Hair segmentation must be precise (strands). No "halo" effect.

================================================================
EXECUTION ORDER
================================================================
1. Mask Subject (Keep Face Protected).
2. Apply Layer 3 (Background).
3. Apply Layer 2 (Clothing) if requested.
4. Apply Layer 1 (Beauty) on Face Skin.
5. Merge Layers -> Output JPEG.
`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: {
        parts: [
          {
            inlineData: {
              mimeType: 'image/jpeg',
              data: cleanBase64
            }
          },
          {
            text: prompt
          }
        ]
      }
    });

    const parts = response.candidates?.[0]?.content?.parts;
    if (parts) {
      for (const part of parts) {
        if (part.inlineData && part.inlineData.data) {
          return `data:image/jpeg;base64,${part.inlineData.data}`;
        }
      }
    }

    throw new Error("Không nhận được dữ liệu ảnh từ Gemini.");

  } catch (error) {
    console.error("Gemini processing error:", error);
    throw error;
  }
};

import React, { useState, useEffect, useRef } from 'react';
import { BackgroundType, PhotoSettings, PhotoSize, AppConfig, SkinToneType } from '../types';
import { processIDPhoto } from '../services/geminiService';

interface ImageEditorProps {
  originalImage: string;
  settings: PhotoSettings;
  onUpdateSettings: (newSettings: PhotoSettings) => void;
  onProcessedImage: (img: string) => void;
  onNext: () => void;
  onRetake: () => void;
  config: AppConfig;
}

type EditorTab = 'background' | 'beauty' | 'clothing';

const ImageEditor: React.FC<ImageEditorProps> = ({ 
  originalImage, 
  settings, 
  onUpdateSettings,
  onProcessedImage,
  onNext,
  onRetake,
  config
}) => {
  const [processedUrl, setProcessedUrl] = useState<string>(originalImage);
  const [isProcessing, setIsProcessing] = useState(false);
  const [activeTab, setActiveTab] = useState<EditorTab>('background');
  const [loadingAction, setLoadingAction] = useState<string>('');

  // Before/After Slider State
  const [sliderPosition, setSliderPosition] = useState(50);
  const imageContainerRef = useRef<HTMLDivElement>(null);
  const isDraggingRef = useRef(false);

  // UI state for debouncing AI calls
  const [clothingInput, setClothingInput] = useState('');
  const [genderTab, setGenderTab] = useState<'male' | 'female'>('male');
  const [securityWarning, setSecurityWarning] = useState('');

  // Accordion state for Beauty Tab
  const [beautySection, setBeautySection] = useState<'skin' | 'makeup' | 'light'>('skin');

  useEffect(() => {
    // Initial auto-background removal if set
    if (settings.background !== BackgroundType.ORIGINAL && processedUrl === originalImage) {
      triggerAI(settings.background, undefined, undefined, "Đang xử lý lớp Phông nền...");
    }
  }, []);

  // --- CORE AI HANDLER ---
  const triggerAI = async (
    overrideBg?: BackgroundType, 
    overrideClothing?: string,
    overrideBeauty?: any,
    actionName: string = "Đang xử lý..."
  ) => {
    setIsProcessing(true);
    setLoadingAction(actionName);
    setSecurityWarning('');

    // Get effective values for all layers to send to AI
    const effBg = overrideBg !== undefined ? overrideBg : settings.background;
    const effClothing = overrideClothing !== undefined ? overrideClothing : settings.clothingPrompt;
    const effBeauty = overrideBeauty !== undefined ? overrideBeauty : settings.beauty;

    try {
      const isDefault = effBg === BackgroundType.ORIGINAL && !effClothing && 
        Object.values(effBeauty).every(v => !v || v === 0 || v === false);

      if (isDefault) {
        setProcessedUrl(originalImage);
      } else {
        const result = await processIDPhoto(originalImage, effBg, effClothing, effBeauty, settings.size);
        setProcessedUrl(result);
      }

      onUpdateSettings({ 
        ...settings, 
        background: effBg, 
        clothingPrompt: effClothing,
        beauty: effBeauty 
      });
    } catch (err: any) {
      console.error(err);
      setSecurityWarning("Lỗi xử lý AI. Vui lòng thử lại.");
    } finally {
      setIsProcessing(false);
      setLoadingAction('');
    }
  };

  // --- HANDLERS ---
  const handleBgChange = (bg: BackgroundType) => triggerAI(bg, undefined, undefined, "Đang thay đổi lớp Phông nền...");

  const handleClothingClick = (prompt: string) => {
    setClothingInput(prompt);
    triggerAI(undefined, prompt, undefined, prompt ? "Đang thay thế lớp Trang phục..." : "Đang hoàn tác lớp Trang phục...");
  };

  const handleBeautyChange = (key: keyof typeof settings.beauty, value: any) => {
    const newBeauty = { ...settings.beauty, [key]: value };
    onUpdateSettings({ ...settings, beauty: newBeauty });
  };

  // Trigger AI only when slider is released to save API calls
  const handleSliderRelease = () => {
    triggerAI(undefined, undefined, settings.beauty, "Đang cập nhật lớp Làm đẹp...");
  };

  const handleMouseMove = (e: React.MouseEvent | React.TouchEvent) => {
    if (!isDraggingRef.current || !imageContainerRef.current) return;
    const rect = imageContainerRef.current.getBoundingClientRect();
    const clientX = 'touches' in e ? e.touches[0].clientX : e.clientX;
    const x = Math.max(0, Math.min(clientX - rect.left, rect.width));
    setSliderPosition((x / rect.width) * 100);
  };

  const handleFinish = () => {
    const canvas = document.createElement('canvas');
    const img = new Image();
    img.src = processedUrl;
    img.crossOrigin = "anonymous";
    img.onload = () => {
      canvas.width = img.width;
      canvas.height = img.height;
      const ctx = canvas.getContext('2d');
      if (ctx) {
        ctx.drawImage(img, 0, 0);
        onProcessedImage(canvas.toDataURL('image/jpeg', 0.95));
        onNext();
      }
    };
  };

  // Filter clothing options
  const activeClothingOptions = config.clothingOptions.filter(item => item.gender === genderTab);

  const LipstickColors = [
    { id: 'red', label: 'Đỏ', hex: '#ef4444' },
    { id: 'pink', label: 'Hồng', hex: '#ec4899' },
    { id: 'orange', label: 'Cam', hex: '#f97316' },
    { id: 'nude', label: 'Nude', hex: '#d6a692' },
  ];

  const SkinToneOptions = [
    { id: SkinToneType.NATURAL, label: 'Tự nhiên', color: '#e5cba6' },
    { id: SkinToneType.FAIR, label: 'Trắng Sáng', color: '#fcebe3' },
    { id: SkinToneType.ROSY, label: 'Trắng Hồng', color: '#ffdee8' },
    { id: SkinToneType.TAN, label: 'Ngăm Khỏe', color: '#cd9b75' },
  ];

  return (
    <div className="flex flex-col md:flex-row h-full w-full bg-slate-100 overflow-hidden font-sans"
      onMouseMove={handleMouseMove}
      onTouchMove={handleMouseMove}
      onMouseUp={() => { isDraggingRef.current = false; }}
      onTouchEnd={() => { isDraggingRef.current = false; }}
    >

      {/* LEFT: Sidebar / Controls */}
      <div className="w-full md:w-[420px] bg-white shadow-2xl z-20 flex flex-col h-full border-r border-gray-200">

        {/* Header */}
        <div className="p-5 border-b border-gray-100 bg-white flex justify-between items-center">
          <h2 className="text-xl font-extrabold text-gray-800 flex items-center gap-2">
            <span className="text-brand-600 text-2xl">✨</span> Chỉnh sửa
          </h2>
          <div className="text-[10px] font-bold text-gray-400 uppercase tracking-wider">AI Layers</div>
        </div>

        {/* SEGMENTED CONTROL TABS */}
        <div className="px-5 pt-4 pb-2">
          <div className="flex bg-gray-100 p-1 rounded-xl">
            {(['background', 'beauty', 'clothing'] as EditorTab[]).map((tab) => (
               <button
                key={tab}
                onClick={() => setActiveTab(tab)}
                className={`flex-1 py-3 text-xs font-bold uppercase tracking-wide rounded-lg transition-all duration-200 ${
                  activeTab === tab 
                    ? 'bg-white text-brand-600 shadow-sm' 
                    : 'text-gray-500 hover:text-gray-700'
                }`}
              >
                {tab === 'background' ? 'Phông nền' : tab === 'beauty' ? 'Làm đẹp' : 'Trang phục'}
              </button>
            ))}
          </div>
        </div>

        {/* SCROLLABLE CONTENT */}
        <div className="flex-1 overflow-y-auto p-5 bg-white scrollbar-hide">

          {/* --- BACKGROUND TAB --- */}
          {activeTab === 'background' && (
            <div className="space-y-6 animate-fadeIn">
              <div className="grid grid-cols-2 gap-4">
                {[
                  { type: BackgroundType.WHITE, label: 'Trắng (Visa/ID)', color: 'bg-white border-gray-200' },
                  { type: BackgroundType.BLUE, label: 'Xanh (Hồ sơ)', color: 'bg-[#2792ff]' },
                  { type: BackgroundType.GRAY, label: 'Xám (CV)', color: 'bg-gray-300' },
                  { type: BackgroundType.ORIGINAL, label: 'Ảnh Gốc', color: "bg-[url('https://placehold.co/32x32/png')] bg-cover opacity-50" }
