export default ImageEditor;

import React, { useState, useEffect } from 'react';
import { PhotoSettings, PhotoSize, AppConfig } from '../types';
import { savePhotoToCloud } from '../services/databaseService';

interface PrintPreviewProps {
  processedImage: string;
  size: PhotoSize;
  settings: PhotoSettings;
  onBack: () => void;
  onNew: () => void;
  onSaved?: () => void;
  onHome: () => void;
  config: AppConfig;
}

const PrintPreview: React.FC<PrintPreviewProps> = ({ 
  processedImage, 
  size, 
  settings, 
  onBack, 
  onNew,
  onSaved,
  onHome,
  config
}) => {
  const [isSaving, setIsSaving] = useState(false);
  const [saveSuccess, setSaveSuccess] = useState(false);
  const [downloadProcessing, setDownloadProcessing] = useState(false);

  // Zalo & QR State
  const [phoneNumber, setPhoneNumber] = useState(settings.phoneNumber || config.contactZalo);
  const [isSendingZalo, setIsSendingZalo] = useState(false);
  const [showQR, setShowQR] = useState(false);
  const [photoId] = useState(`ID-${Date.now().toString().slice(-6)}`);

  // Configuration constants
  const DPI = 300; // Print resolution
  const mmToPx = (mm: number) => (mm / 25.4) * DPI;

  // Grid Layout Logic
  const getLayoutConfig = () => {
    if (size === PhotoSize.SIZE_3X4) {
      return {
        cols: 4,
        rows: 4,
        photoW_mm: 30,
        photoH_mm: 40,
        rotated: false,
        maxOnSheet: 16
      };
    } else if (size === PhotoSize.SIZE_5X5) {
      return {
        cols: 2,
        rows: 3,
        photoW_mm: 50,
        photoH_mm: 50,
        rotated: false,
        maxOnSheet: 6
      };
    } else {
      // 4x6 Default - Rotated to Landscape on sheet for efficiency (2x4=8)
      return {
        cols: 2,
        rows: 4,
        photoW_mm: 60, // Slot width (rotated 4x6)
        photoH_mm: 40, // Slot height
        rotated: true, // Needs CSS rotation
        maxOnSheet: 8
      };
    }
  };

  const layout = getLayoutConfig();

  // Pagination Logic
  const totalPhotosNeeded = settings.printQuantity;
  const totalSheets = Math.ceil(totalPhotosNeeded / layout.maxOnSheet);

  // Generate QR Data
  const qrDataUrl = `https://photobooth-demo.com/d/${photoId}`;
  const qrImageUrl = `https://api.qrserver.com/v1/create-qr-code/?size=150x150&data=${encodeURIComponent(qrDataUrl)}&color=000000&bgcolor=FFFFFF&margin=0`;

  const handlePrint = () => {
    window.print();
  };

  const handleDownloadSingle = () => {
    const link = document.createElement('a');
    link.href = processedImage;
    link.download = `${photoId}-Single.png`; // Changed to PNG
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  /**
   * Generates a high-res canvas for a SPECIFIC sheet index and downloads it.
   */
  const generateAndDownloadSheet = async (sheetIndex: number) => {
    const canvas = document.createElement('canvas');
    const ctx = canvas.getContext('2d');
    if (!ctx) throw new Error("No Canvas Context");

    const width = Math.round(mmToPx(130));
    const height = Math.round(mmToPx(180));

    canvas.width = width;
    canvas.height = height;

    // 1. Draw White Background
    ctx.fillStyle = '#ffffff';
    ctx.fillRect(0, 0, width, height);

    // 2. Load Photo
    const img = new Image();
    img.crossOrigin = "anonymous";
    img.src = processedImage;
    await new Promise((resolve, reject) => {
      img.onload = resolve;
      img.onerror = reject;
    });

    // 3. Draw Grid & Photos
    const photoSlotW = Math.round(mmToPx(layout.photoW_mm));
    const photoSlotH = Math.round(mmToPx(layout.photoH_mm));

    const totalContentW = layout.cols * photoSlotW;
    const startX = (width - totalContentW) / 2;
    const startY = Math.round(mmToPx(5)); // 5mm top margin

    // Calculate which photos belong to this sheet
    const startPhotoIdx = sheetIndex * layout.maxOnSheet;
    const endPhotoIdx = Math.min(startPhotoIdx + layout.maxOnSheet, totalPhotosNeeded);
    const photosOnThisSheet = endPhotoIdx - startPhotoIdx;

    for (let i = 0; i < photosOnThisSheet; i++) {
      const col = i % layout.cols;
      const row = Math.floor(i / layout.cols);
      const x = startX + col * photoSlotW;
      const y = startY + row * photoSlotH;

      // --- CROP GRID (Dashed Lines for Cutting) ---
      ctx.save();
      ctx.strokeStyle = '#cbd5e1'; // Light Gray (Slate 300)
      ctx.lineWidth = 2; // Thicker line for high res
      ctx.setLineDash([15, 15]); // Dashed pattern
      ctx.strokeRect(x, y, photoSlotW, photoSlotH);
      ctx.restore();

      // Draw Image (Inset slightly to not overlap grid line)
      // We draw the image *inside* the grid
      if (layout.rotated) {
        // Rotate 90 degrees CCW to fit portrait photo into landscape slot
        ctx.save();
        ctx.translate(x + photoSlotW / 2, y + photoSlotH / 2);
        ctx.rotate(-90 * Math.PI / 180);
        ctx.drawImage(img, -photoSlotH / 2, -photoSlotW / 2, photoSlotH, photoSlotW);
        ctx.restore();
      } else {
        ctx.drawImage(img, x, y, photoSlotW, photoSlotH);
      }
    }

    // 4. Draw Footer Area
    const footerH = Math.round(mmToPx(20)); // 20mm footer
    const footerY = height - footerH;

    ctx.fillStyle = '#f1f5f9'; // Slate-100
    ctx.fillRect(0, footerY, width, footerH);

    // Footer Logo/Text
    if (config.logoUrl) {
        const logoImg = new Image();
        logoImg.src = config.logoUrl;
        await new Promise(r => { logoImg.onload = r; logoImg.onerror = r; });
        const maxLogoH = Math.round(mmToPx(14));
        const logoRatio = logoImg.width / logoImg.height;
        const drawW = maxLogoH * logoRatio;
        const drawH = maxLogoH;
        ctx.drawImage(logoImg, Math.round(mmToPx(8)), footerY + Math.round(mmToPx(3)), drawW, drawH);
    } else {
        ctx.fillStyle = '#1e293b';
        ctx.font = 'bold 50px sans-serif';
        ctx.fillText(config.shopName, Math.round(mmToPx(8)), footerY + Math.round(mmToPx(8)));
    }

    // Footer Info
    ctx.fillStyle = '#64748b';
    ctx.font = '40px sans-serif';
    const dateStr = new Date().toLocaleDateString('vi-VN');
    const textX = Math.round(mmToPx(8));
    const textY = footerY + Math.round(mmToPx(16));
    ctx.fillText(`${config.printFooterText} | Sheet ${sheetIndex + 1}/${totalSheets} | ${dateStr}`, textX, textY);

    // Footer QR
    const qrImg = new Image();
    qrImg.crossOrigin = "anonymous";
    qrImg.src = qrImageUrl;
    await new Promise((resolve) => { qrImg.onload = resolve; qrImg.onerror = resolve; });
    const qrSize = Math.round(mmToPx(16));
    ctx.drawImage(qrImg, width - qrSize - Math.round(mmToPx(5)), footerY + Math.round(mmToPx(2)), qrSize, qrSize);

    // 5. Convert to Blob/Download
    return new Promise<void>((resolve) => {
        canvas.toBlob((blob) => {
            if (blob) {
                const link = document.createElement('a');
                link.href = URL.createObjectURL(blob);
                link.download = `${photoId}-Sheet-${sheetIndex + 1}.png`; // PNG format
                document.body.appendChild(link);
                link.click();
                document.body.removeChild(link);
                URL.revokeObjectURL(link.href);
            }
            resolve();
        }, 'image/png', 1.0); // PNG Quality 1.0
    });
  };

  const handleDownloadAllSheets = async () => {
    setDownloadProcessing(true);
    try {
      for (let i = 0; i < totalSheets; i++) {
        await generateAndDownloadSheet(i);
        // Small delay to prevent browser blocking multiple downloads
        if (i < totalSheets - 1) await new Promise(r => setTimeout(r, 500));
      }
    } catch (error) {
      console.error("Sheet generation failed", error);
      alert("Lỗi tạo ảnh khổ in. Vui lòng thử lại.");
    } finally {
      setDownloadProcessing(false);
    }
  };

  const handleSaveToDB = async () => {
    setIsSaving(true);
    const currentSettings = { ...settings, phoneNumber };
    const success = await savePhotoToCloud({
