        {/* Right Panel: Regulations */}
        <div className="w-full md:w-2/5 bg-slate-50 p-8 lg:p-10 flex flex-col border-l border-gray-100">
          <h3 className="text-lg font-bold text-slate-700 mb-6 flex items-center gap-2">
            <span className="w-8 h-8 rounded-full bg-brand-100 text-brand-600 flex items-center justify-center">
              <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M13 16h-1v-4h-1m1-4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z"></path></svg>
            </span>
            Quy định chụp ảnh
          </h3>

          <div className="bg-white rounded-2xl p-6 shadow-sm border border-slate-100 flex-1 relative overflow-hidden">
            <div className="absolute top-0 left-0 w-1 h-full bg-brand-500"></div>
            <h4 className="font-bold text-gray-900 mb-4 text-lg">
              {photoTypes.find(t => t.id === selectedSize)?.label}
            </h4>
            <ul className="space-y-4">
              {currentRules.map((rule, idx) => (
                <li key={idx} className="flex gap-3 text-sm text-slate-600 leading-relaxed">
                  <svg className="w-5 h-5 text-green-500 shrink-0 mt-0.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M5 13l4 4L19 7"></path></svg>
                  <span>{rule}</span>
                </li>
              ))}
            </ul>
          </div>

          <div className="mt-8">
            <div className="bg-yellow-50 p-4 rounded-xl border border-yellow-100 flex gap-3">
              <svg className="w-6 h-6 text-yellow-600 shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z"></path></svg>
              <div>
                 <p className="text-xs font-bold text-yellow-800 uppercase mb-1">Lưu ý quan trọng</p>
                 <p className="text-sm text-yellow-700">Vui lòng vén tóc gọn gàng, không để tóc che lông mày hoặc tai. Trang phục có cổ.</p>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default StartScreen;

import React, { useState, useEffect, useRef } from 'react';
import { BackgroundType, PhotoSettings, PhotoSize, AppConfig, SkinToneType } from '../types';
import { processIDPhoto } from '../services/geminiService';

interface ImageEditorProps {
  originalImage: string;
  settings: PhotoSettings;
  onUpdateSettings: (newSettings: PhotoSettings) => void;
  onProcessedImage: (img: string) => void;
  onNext: () => void;
  onRetake: () => void;
  config: AppConfig;
}

type EditorTab = 'background' | 'beauty' | 'clothing';

const ImageEditor: React.FC<ImageEditorProps> = ({ 
  originalImage, 
  settings, 
  onUpdateSettings,
  onProcessedImage,
  onNext,
  onRetake,
  config
}) => {
  const [processedUrl, setProcessedUrl] = useState<string>(originalImage);
  const [isProcessing, setIsProcessing] = useState(false);
  const [activeTab, setActiveTab] = useState<EditorTab>('background');
  const [loadingAction, setLoadingAction] = useState<string>('');

  // Before/After Slider State
  const [sliderPosition, setSliderPosition] = useState(50);
  const imageContainerRef = useRef<HTMLDivElement>(null);
  const isDraggingRef = useRef(false);

  // UI state for debouncing AI calls
  const [clothingInput, setClothingInput] = useState('');
  const [genderTab, setGenderTab] = useState<'male' | 'female'>('male');
  const [securityWarning, setSecurityWarning] = useState('');

  // Accordion state for Beauty Tab
  const [beautySection, setBeautySection] = useState<'skin' | 'makeup' | 'light'>('skin');

  useEffect(() => {
    // Initial auto-background removal if set
    if (settings.background !== BackgroundType.ORIGINAL && processedUrl === originalImage) {
      triggerAI(settings.background, undefined, undefined, "Đang xử lý lớp Phông nền...");
    }
  }, []);

  // --- CORE AI HANDLER ---
  const triggerAI = async (
    overrideBg?: BackgroundType, 
    overrideClothing?: string,
    overrideBeauty?: any,
    actionName: string = "Đang xử lý..."
  ) => {
    setIsProcessing(true);
    setLoadingAction(actionName);
    setSecurityWarning('');

    // Get effective values for all layers to send to AI
    const effBg = overrideBg !== undefined ? overrideBg : settings.background;
    const effClothing = overrideClothing !== undefined ? overrideClothing : settings.clothingPrompt;
    const effBeauty = overrideBeauty !== undefined ? overrideBeauty : settings.beauty;

    try {
      const isDefault = effBg === BackgroundType.ORIGINAL && !effClothing && 
        Object.values(effBeauty).every(v => !v || v === 0 || v === false);

      if (isDefault) {
        setProcessedUrl(originalImage);
      } else {
        const result = await processIDPhoto(originalImage, effBg, effClothing, effBeauty, settings.size);
        setProcessedUrl(result);
      }

      onUpdateSettings({ 
        ...settings, 
        background: effBg, 
        clothingPrompt: effClothing,
        beauty: effBeauty 
      });
    } catch (err: any) {
      console.error(err);
      setSecurityWarning("Lỗi xử lý AI. Vui lòng thử lại.");
    } finally {
      setIsProcessing(false);
      setLoadingAction('');
    }
  };

  // --- HANDLERS ---
  const handleBgChange = (bg: BackgroundType) => triggerAI(bg, undefined, undefined, "Đang thay đổi lớp Phông nền...");

  const handleClothingClick = (prompt: string) => {
    setClothingInput(prompt);
    triggerAI(undefined, prompt, undefined, prompt ? "Đang thay thế lớp Trang phục..." : "Đang hoàn tác lớp Trang phục...");
  };

  const handleBeautyChange = (key: keyof typeof settings.beauty, value: any) => {
    const newBeauty = { ...settings.beauty, [key]: value };
    onUpdateSettings({ ...settings, beauty: newBeauty });
  };

  // Trigger AI only when slider is released to save API calls
  const handleSliderRelease = () => {
    triggerAI(undefined, undefined, settings.beauty, "Đang cập nhật lớp Làm đẹp...");
  };

  const handleMouseMove = (e: React.MouseEvent | React.TouchEvent) => {
    if (!isDraggingRef.current || !imageContainerRef.current) return;
    const rect = imageContainerRef.current.getBoundingClientRect();
    const clientX = 'touches' in e ? e.touches[0].clientX : e.clientX;
    const x = Math.max(0, Math.min(clientX - rect.left, rect.width));
    setSliderPosition((x / rect.width) * 100);
  };

  const handleFinish = () => {
    const canvas = document.createElement('canvas');
    const img = new Image();
    img.src = processedUrl;
    img.crossOrigin = "anonymous";
    img.onload = () => {
      canvas.width = img.width;
      canvas.height = img.height;
      const ctx = canvas.getContext('2d');
      if (ctx) {
        ctx.drawImage(img, 0, 0);
        onProcessedImage(canvas.toDataURL('image/jpeg', 0.95));
        onNext();
      }
    };
  };

  // Filter clothing options
  const activeClothingOptions = config.clothingOptions.filter(item => item.gender === genderTab);

  const SkinToneOptions = [
    { id: SkinToneType.NATURAL, label: 'Tự nhiên', color: '#e5cba6' },
    { id: SkinToneType.FAIR, label: 'Trắng Sáng', color: '#fcebe3' },
    { id: SkinToneType.ROSY, label: 'Trắng Hồng', color: '#ffdee8' },
    { id: SkinToneType.TAN, label: 'Ngăm Khỏe', color: '#cd9b75' },
  ];

  // Helper to render backgrounds from Config
  const renderBackgrounds = () => {
    const bgs = [...config.backgroundConfig];
    // Always add Original as the last option
    return (
      <>
        {bgs.map(bg => (
           <button 
              key={bg.type}
              onClick={() => handleBgChange(bg.type)} 
              disabled={isProcessing}
              className={`relative h-32 rounded-2xl border-2 flex flex-col items-center justify-center gap-3 transition-all group ${
                settings.background === bg.type 
                  ? 'border-brand-500 bg-brand-50 shadow-md ring-1 ring-brand-200' 
                  : 'border-slate-100 hover:border-brand-200 hover:bg-slate-50'
              }`}
            >
              <div 
                className={`w-12 h-12 rounded-full shadow-inner ${settings.background === bg.type ? 'ring-2 ring-offset-2 ring-brand-400' : ''}`}
                style={{ backgroundColor: bg.hexColor }}
              ></div>
              <span className={`text-xs font-bold ${settings.background === bg.type ? 'text-brand-700' : 'text-gray-600'}`}>{bg.label}</span>

              {settings.background === bg.type && (
                <div className="absolute top-2 right-2 text-brand-500 bg-white rounded-full p-0.5 shadow-sm">
                  <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M5 13l4 4L19 7"></path></svg>
                </div>
              )}
            </button>
        ))}
        {/* Original */}
        <button 
          onClick={() => handleBgChange(BackgroundType.ORIGINAL)} 
          disabled={isProcessing}
          className={`relative h-32 rounded-2xl border-2 flex flex-col items-center justify-center gap-3 transition-all group ${
            settings.background === BackgroundType.ORIGINAL
              ? 'border-brand-500 bg-brand-50 shadow-md ring-1 ring-brand-200' 
              : 'border-slate-100 hover:border-brand-200 hover:bg-slate-50'
          }`}
        >
          <div className={`w-12 h-12 rounded-full shadow-inner bg-[url('https://placehold.co/32x32/png')] bg-cover opacity-50 ${settings.background === BackgroundType.ORIGINAL ? 'ring-2 ring-offset-2 ring-brand-400' : ''}`}></div>
          <span className={`text-xs font-bold ${settings.background === BackgroundType.ORIGINAL ? 'text-brand-700' : 'text-gray-600'}`}>Ảnh Gốc</span>
           {settings.background === BackgroundType.ORIGINAL && (
                <div className="absolute top-2 right-2 text-brand-500 bg-white rounded-full p-0.5 shadow-sm">
                  <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M5 13l4 4L19 7"></path></svg>
                </div>
              )}
        </button>
      </>
    );
  };

  return (
    <div className="flex flex-col md:flex-row h-full w-full bg-slate-100 overflow-hidden font-sans"
      onMouseMove={handleMouseMove}
      onTouchMove={handleMouseMove}
      onMouseUp={() => { isDraggingRef.current = false; }}
      onTouchEnd={() => { isDraggingRef.current = false; }}
    >

      {/* LEFT: Sidebar / Controls */}
      <div className="w-full md:w-[420px] bg-white shadow-2xl z-20 flex flex-col h-full border-r border-gray-200">

        {/* Header */}
        <div className="p-5 border-b border-gray-100 bg-white flex justify-between items-center">
          <h2 className="text-xl font-extrabold text-gray-800 flex items-center gap-2">
            <span className="text-brand-600 text-2xl">✨</span> Chỉnh sửa
          </h2>
          <div className="text-[10px] font-bold text-gray-400 uppercase tracking-wider">AI Layers</div>
        </div>

        {/* SEGMENTED CONTROL TABS */}
        <div className="px-5 pt-4 pb-2">
          <div className="flex bg-gray-100 p-1 rounded-xl">
            {(['background', 'beauty', 'clothing'] as EditorTab[]).map((tab) => (
               <button
                key={tab}
                onClick={() => setActiveTab(tab)}
                className={`flex-1 py-3 text-xs font-bold uppercase tracking-wide rounded-lg transition-all duration-200 ${
                  activeTab === tab 
                    ? 'bg-white text-brand-600 shadow-sm' 
                    : 'text-gray-500 hover:text-gray-700'
                }`}
              >
                {tab === 'background' ? 'Phông nền' : tab === 'beauty' ? 'Làm đẹp' : 'Trang phục'}
              </button>
            ))}
          </div>
        </div>

        {/* SCROLLABLE CONTENT */}
        <div className="flex-1 overflow-y-auto p-5 bg-white scrollbar-hide">

          {/* --- BACKGROUND TAB --- */}
          {activeTab === 'background' && (
            <div className="space-y-6 animate-fadeIn">
              <div className="grid grid-cols-2 gap-4">
                {renderBackgrounds()}
              </div>
            </div>
          )}

          {/* --- BEAUTY TAB --- */}
          {activeTab === 'beauty' && (
            <div className="space-y-4 animate-fadeIn">

              <div className="bg-blue-50/50 p-3 rounded-xl border border-blue-100 mb-2">
                <p className="text-[11px] text-blue-700 font-medium flex gap-2">
                  <svg className="w-4 h-4 shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M13 16h-1v-4h-1m1-4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z"></path></svg>
                  Chế độ đa lớp: Chỉ áp dụng lên người. Giữ nguyên phông nền.
                </p>
              </div>

              {/* SECTION: SKIN & TONE */}
              <div className="border border-gray-100 rounded-xl overflow-hidden">
                <button 
                  onClick={() => setBeautySection('skin')}
                  className={`w-full p-3 flex justify-between items-center text-sm font-bold ${beautySection === 'skin' ? 'bg-brand-50 text-brand-700' : 'bg-white text-gray-700 hover:bg-gray-50'}`}
                >
                  <span className="flex items-center gap-2">✨ Lớp Da (Skin Layer)</span>
                  <svg className={`w-4 h-4 transition-transform ${beautySection === 'skin' ? 'rotate-180' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 9l-7 7-7-7"></path></svg>
                </button>

                {beautySection === 'skin' && (
                  <div className="p-4 bg-white space-y-5 animate-fadeIn">
                     {/* Skin Tone Selector */}
                     <div>
                       <label className="text-xs font-bold text-gray-500 mb-2 block">Màu Da Chủ Đạo</label>
                       <div className="grid grid-cols-4 gap-2 mb-3">
                          {SkinToneOptions.map(tone => (
                            <button
                              key={tone.id}
                              onClick={() => {
                                handleBeautyChange('skinToneType', tone.id);
                                handleBeautyChange('skinToneIntensity', 50); // Set default intensity when clicked
                                handleSliderRelease();
                              }}
                              className={`flex flex-col items-center gap-1 p-2 rounded-lg border transition-all ${
                                settings.beauty.skinToneType === tone.id 
                                ? 'border-brand-500 bg-brand-50' 
                                : 'border-gray-100 hover:bg-gray-50'
                              }`}
                            >
                              <div className="w-6 h-6 rounded-full border shadow-sm" style={{ backgroundColor: tone.color }}></div>
                              <span className="text-[9px] font-bold text-gray-600">{tone.label}</span>
                            </button>
                          ))}
                       </div>

                       <div className="flex justify-between text-xs font-bold text-gray-700 mb-1">
                          <span>Mức độ màu da</span>
                          <span className="bg-gray-100 px-2 py-0.5 rounded text-[10px]">{settings.beauty.skinToneIntensity}%</span>
                       </div>
                       <input 
                          type="range" min="0" max="100" step="10"
                          value={settings.beauty.skinToneIntensity} 
                          onChange={(e) => handleBeautyChange('skinToneIntensity', Number(e.target.value))} 
                          onMouseUp={handleSliderRelease}
                          onTouchEnd={handleSliderRelease}
                          className="w-full h-2 bg-amber-100 rounded-lg appearance-none cursor-pointer accent-amber-600" 
                        />
                     </div>

                     <hr className="border-gray-100" />

                     {/* Smooth Skin */}
                     <div>
                       <div className="flex justify-between text-xs font-bold text-gray-700 mb-1">
                         <span>Làm mịn da</span>
                         <span className="bg-gray-100 px-2 py-0.5 rounded text-[10px]">{settings.beauty.smoothSkin > 0 ? `Cấp ${settings.beauty.smoothSkin}` : 'Off'}</span>
                       </div>
                       <input 
                        type="range" min="0" max="5" step="1" 
                        value={settings.beauty.smoothSkin} 
                        onChange={(e) => handleBeautyChange('smoothSkin', Number(e.target.value))} 
                        onMouseUp={handleSliderRelease} 
                        onTouchEnd={handleSliderRelease}
                        className="w-full h-2 bg-brand-200 rounded-lg appearance-none cursor-pointer accent-brand-600" 
                       />
                    </div>

                    <div className="flex gap-2">
                       <label className={`flex-1 flex items-center justify-center gap-2 p-2 border rounded-lg cursor-pointer text-xs font-bold transition-all ${settings.beauty.removeBlemishes ? 'bg-blue-50 border-blue-300 text-blue-700' : 'bg-gray-50 text-gray-600'}`}>
                          <input type="checkbox" checked={settings.beauty.removeBlemishes} onChange={(e) => { handleBeautyChange('removeBlemishes', e.target.checked); handleSliderRelease(); }} className="hidden" />
                          <span>Xóa Mụn/Thâm</span>
                          {settings.beauty.removeBlemishes && <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M5 13l4 4L19 7"></path></svg>}
                       </label>

                       <label className={`flex-1 flex items-center justify-center gap-2 p-2 border rounded-lg cursor-pointer text-xs font-bold transition-all ${settings.beauty.fillHair ? 'bg-blue-50 border-blue-300 text-blue-700' : 'bg-gray-50 text-gray-600'}`}>
                          <input type="checkbox" checked={settings.beauty.fillHair} onChange={(e) => { handleBeautyChange('fillHair', e.target.checked); handleSliderRelease(); }} className="hidden" />
                          <span>Bù/Chỉnh tóc</span>
                          {settings.beauty.fillHair && <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M5 13l4 4L19 7"></path></svg>}
                       </label>
                    </div>
                  </div>
                )}
              </div>

              {/* SECTION: MAKEUP */}
              <div className="border border-gray-100 rounded-xl overflow-hidden">
                <button 
                  onClick={() => setBeautySection('makeup')}
                  className={`w-full p-3 flex justify-between items-center text-sm font-bold ${beautySection === 'makeup' ? 'bg-pink-50 text-pink-700' : 'bg-white text-gray-700 hover:bg-gray-50'}`}
                >
                  <span className="flex items-center gap-2">💄 Lớp Trang điểm (Makeup Layer)</span>
                  <svg className={`w-4 h-4 transition-transform ${beautySection === 'makeup' ? 'rotate-180' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 9l-7 7-7-7"></path></svg>
                </button>

                {beautySection === 'makeup' && (
                  <div className="p-4 bg-white space-y-5 animate-fadeIn">
                     {/* Lipstick */}
                     <div>
                       <label className="text-xs font-bold text-gray-500 mb-2 block">Màu Son</label>
                       <div className="flex gap-2 mb-3">
                          {config.lipstickOptions.map(color => (
                            <button
                              key={color.id}
                              onClick={() => {
                                handleBeautyChange('lipstickColor', color.id);
                                if (settings.beauty.lipstickIntensity === 0) handleBeautyChange('lipstickIntensity', 50); // Auto enable
                                handleSliderRelease();
                              }}
                              className={`w-8 h-8 rounded-full border-2 flex items-center justify-center transition-all ${
                                settings.beauty.lipstickColor === color.id 
                                ? 'border-gray-800 scale-110' 
                                : 'border-transparent opacity-80 hover:opacity-100 hover:scale-105'
                              }`}
                              style={{ backgroundColor: color.hex }}
                              title={color.label}
                            >
                              {settings.beauty.lipstickColor === color.id && <svg className="w-4 h-4 text-white drop-shadow-md" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M5 13l4 4L19 7"></path></svg>}
                            </button>
                          ))}
                       </div>
                       <div className="flex justify-between text-xs font-bold text-gray-700 mb-1">
                          <span>Đậm nhạt son</span>
                          <span className="bg-gray-100 px-2 py-0.5 rounded text-[10px]">{settings.beauty.lipstickIntensity}%</span>
                       </div>
                       <input 
                          type="range" min="0" max="100" step="10"
                          value={settings.beauty.lipstickIntensity} 
                          onChange={(e) => handleBeautyChange('lipstickIntensity', Number(e.target.value))} 
                          onMouseUp={handleSliderRelease}
                          onTouchEnd={handleSliderRelease}
                          className="w-full h-2 bg-pink-100 rounded-lg appearance-none cursor-pointer accent-pink-500" 
                        />
                     </div>

                     {/* Eyebrows */}
                     <div>
                        <div className="flex justify-between text-xs font-bold text-gray-700 mb-1">
                          <span>Chân mày (Đậm/Nét)</span>
                          <span className="bg-gray-100 px-2 py-0.5 rounded text-[10px]">{settings.beauty.eyebrowIntensity}%</span>
                        </div>
                        <input 
                          type="range" min="0" max="100" step="10"
                          value={settings.beauty.eyebrowIntensity} 
                          onChange={(e) => handleBeautyChange('eyebrowIntensity', Number(e.target.value))} 
                          onMouseUp={handleSliderRelease}
                          onTouchEnd={handleSliderRelease}
                          className="w-full h-2 bg-gray-200 rounded-lg appearance-none cursor-pointer accent-gray-600" 
                        />
                     </div>

                     {/* Blush */}
                     <div>
                        <div className="flex justify-between text-xs font-bold text-gray-700 mb-1">
                          <span>Má hồng</span>
                          <span className="bg-gray-100 px-2 py-0.5 rounded text-[10px]">{settings.beauty.blushIntensity}%</span>
                        </div>
                        <input 
                          type="range" min="0" max="100" step="10"
                          value={settings.beauty.blushIntensity} 
                          onChange={(e) => handleBeautyChange('blushIntensity', Number(e.target.value))} 
                          onMouseUp={handleSliderRelease}
                          onTouchEnd={handleSliderRelease}
                          className="w-full h-2 bg-red-100 rounded-lg appearance-none cursor-pointer accent-red-400" 
                        />
                     </div>

                     {/* Contour */}
                     <div>
                        <div className="flex justify-between text-xs font-bold text-gray-700 mb-1">
                          <span>Tạo khối (Contour)</span>
                          <span className="bg-gray-100 px-2 py-0.5 rounded text-[10px]">{settings.beauty.contourIntensity}%</span>
                        </div>
                        <input 
                          type="range" min="0" max="100" step="10"
                          value={settings.beauty.contourIntensity} 
                          onChange={(e) => handleBeautyChange('contourIntensity', Number(e.target.value))} 
                          onMouseUp={handleSliderRelease}
                          onTouchEnd={handleSliderRelease}
                          className="w-full h-2 bg-stone-200 rounded-lg appearance-none cursor-pointer accent-stone-500" 
                        />
                     </div>
                  </div>
                )}
              </div>

              {/* SECTION: LIGHTING */}
              <div className="border border-gray-100 rounded-xl overflow-hidden">
                <button 
                  onClick={() => setBeautySection('light')}
                  className={`w-full p-3 flex justify-between items-center text-sm font-bold ${beautySection === 'light' ? 'bg-yellow-50 text-yellow-700' : 'bg-white text-gray-700 hover:bg-gray-50'}`}
                >
                  <span className="flex items-center gap-2">💡 Ánh sáng & Tương phản</span>
