  const addLipstick = () => {
    if (!newLipstick.label) return;
    const id = `lip_${Date.now()}`;
    setForm(prev => ({
        ...prev,
        lipstickOptions: [...prev.lipstickOptions, { ...newLipstick, id }]
    }));
    setNewLipstick({ id: '', label: '', hex: '#ff0000' });
  };

