  appId: "1:123..."
};

// Khởi tạo Firebase (Sử dụng try-catch để tránh crash nếu chưa config)
let db: any;
try {
  const app = initializeApp(firebaseConfig);
  db = getFirestore(app);
} catch (e) {
  console.warn("Firebase chưa được cấu hình đúng. Vui lòng cập nhật firebaseConfig trong services/databaseService.ts");
}

/**
 * Lưu ảnh lên Firestore.
 * Lưu ý: Firestore giới hạn document 1MB. Nếu ảnh quá lớn, cần nén hoặc dùng Firebase Storage.
 * Ở đây ta dùng Firestore theo yêu cầu.
 */
export const savePhotoToCloud = async (photo: SavedPhoto): Promise<string | null> => {
  if (!db) {
    alert("Chưa kết nối Database. Vui lòng cấu hình Firebase Config trong code.");
    return null;
  }

  try {
    // Thử lưu trực tiếp
    const docRef = await addDoc(collection(db, "photos"), {
      ...photo,
      timestamp: Date.now()
    });
    return docRef.id; // Trả về ID thực từ Firestore
  } catch (error: any) {
    console.error("Lỗi lưu Firestore:", error);
    // Nếu lỗi do kích thước quá lớn (code: resource-exhausted hoặc invalid-argument)
    if (error.code === 'resource-exhausted' || error.toString().includes('size')) {
       alert("Ảnh quá lớn so với giới hạn của Firestore (1MB). Vui lòng sử dụng Firebase Storage cho ảnh chất lượng cao.");
    }
    return null;
  }
};

/**
 * Lấy ảnh từ Firestore bằng ID (Dùng cho người quét QR)
 */
export const getPhotoById = async (id: string): Promise<SavedPhoto | null> => {
  if (!db) return null;
  try {
    const docRef = doc(db, "photos", id);
    const docSnap = await getDoc(docRef);

    if (docSnap.exists()) {
      return { id: docSnap.id, ...docSnap.data() } as SavedPhoto;
    } else {
      return null;
    }
  } catch (error) {
    console.error("Lỗi lấy ảnh:", error);
    return null;
  }
};

