  const [qrUrl, setQrUrl] = useState<string>('');

  // Layout Logic
  const getLayoutConfig = () => {
    if (size === PhotoSize.SIZE_3X4) {
      return { cols: 4, rows: 4, photoW_mm: 30, photoH_mm: 40, rotated: false, maxOnSheet: 16 };
    } else if (size === PhotoSize.SIZE_5X5) {
      return { cols: 2, rows: 3, photoW_mm: 50, photoH_mm: 50, rotated: false, maxOnSheet: 6 };
    } else {
      // 4x6 Default - Rotated
      return { cols: 2, rows: 4, photoW_mm: 60, photoH_mm: 40, rotated: true, maxOnSheet: 8 };
    }
  };

  const layout = getLayoutConfig();
  const totalPhotosNeeded = settings.printQuantity;
  const totalSheets = Math.ceil(totalPhotosNeeded / layout.maxOnSheet);

  // Tự động lưu lên Cloud khi vào màn hình này để tạo QR Thật
