                      {Array.from({ length: countForSheet }).map((_, i) => (
                        <div 
                          key={i} 
                          className="overflow-hidden border border-dashed border-slate-300 relative print:border-slate-400" 
                          style={{ 
                            width: cellW, 
                            height: cellH,
                            display: layout.rotated ? 'flex' : 'block',
                            alignItems: 'center',
                            justifyContent: 'center'
                          }}
                        >
                          <img 
                            src={processedImage} 
                            className="object-cover" 
                            style={{
                               width: layout.rotated ? 'auto' : '100%',
                               height: layout.rotated ? '100%' : '100%',
                               transform: layout.rotated ? 'rotate(-90deg)' : 'none',
                               aspectRatio: layout.rotated ? '2/3' : 'auto' 
                            }}
                            alt="ID Photo" 
                          />
                        </div>
                      ))}
                    </div>

                    {/* Footer Area (Bottom 20mm) */}
                    <div className="h-[20mm] bg-slate-50 border-t border-slate-200 flex items-center justify-between px-6 print:border-t print:border-black">
