interface PhotoViewerProps {
  photoId: string;
}

const PhotoViewer: React.FC<PhotoViewerProps> = ({ photoId }) => {
  const [photo, setPhoto] = useState<SavedPhoto | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  useEffect(() => {
    const fetchPhoto = async () => {
      setLoading(true);
      const data = await getPhotoById(photoId);
      if (data) {
        setPhoto(data);
      } else {
        setError('Không tìm thấy ảnh hoặc ảnh đã bị xóa.');
      }
      setLoading(false);
    };
    fetchPhoto();
  }, [photoId]);

  const handleDownload = () => {
    if (!photo) return;
    const link = document.createElement('a');
    link.href = photo.dataUrl;
    link.download = `Photo-${photo.id}.jpg`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  if (loading) return (
    <div className="h-screen w-full flex flex-col items-center justify-center bg-gray-50">
        <div className="w-12 h-12 border-4 border-brand-200 border-t-brand-600 rounded-full animate-spin mb-4"></div>
        <p className="text-gray-500 font-medium">Đang tải ảnh từ Cloud...</p>
    </div>
  );

  if (error || !photo) return (
    <div className="h-screen w-full flex flex-col items-center justify-center bg-gray-50 p-6 text-center">
        <div className="w-16 h-16 bg-red-100 text-red-500 rounded-full flex items-center justify-center mb-4">
            <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12"></path></svg>
        </div>
        <h2 className="text-xl font-bold text-gray-800 mb-2">Lỗi</h2>
        <p className="text-gray-600">{error}</p>
        <a href="/" className="mt-6 px-6 py-2 bg-gray-800 text-white rounded-lg font-bold">Về trang chủ</a>
    </div>
  );

  return (
    <div className="min-h-screen bg-gray-100 p-4 flex flex-col items-center justify-center">
       <div className="max-w-md w-full bg-white rounded-3xl shadow-xl overflow-hidden">
          <div className="bg-brand-600 p-6 text-white text-center">
             <h1 className="text-2xl font-bold">Ảnh Thẻ ID</h1>
             <p className="text-brand-100 text-sm">Chụp & Xử lý tự động</p>
          </div>

          <div className="p-6 flex flex-col items-center">
             <div className="relative w-full aspect-[2/3] rounded-lg overflow-hidden shadow-lg border border-gray-200 mb-6">
                 <img src={photo.dataUrl} className="w-full h-full object-contain bg-gray-50" alt="ID Photo" />
             </div>

             <div className="w-full space-y-3">
                 <button onClick={handleDownload} className="w-full py-3 bg-brand-600 hover:bg-brand-700 text-white rounded-xl font-bold shadow-lg shadow-brand-500/30 flex items-center justify-center gap-2">
                    <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4"></path></svg>
                    Tải ảnh gốc (HD)
                 </button>
                 <div className="text-center text-xs text-gray-400">
                    ID: {photo.id} • {new Date(photo.timestamp).toLocaleString('vi-VN')}
                 </div>
             </div>
          </div>
       </div>
    </div>
  );
};

