import { BeautySettings, SkinToneType } from "../types";

/**
 * Áp dụng các bộ lọc làm đẹp bằng thuật toán Canvas (Pixel Manipulation)
 * Không sử dụng AI.
 */
export const applyAlgorithmicBeauty = async (
  baseImageSrc: string,
  settings: BeautySettings
): Promise<string> => {
  return new Promise((resolve, reject) => {
    const img = new Image();
    img.crossOrigin = "anonymous";
    img.src = baseImageSrc;

    img.onload = () => {
      const canvas = document.createElement("canvas");
      const ctx = canvas.getContext("2d");
      if (!ctx) {
        resolve(baseImageSrc);
        return;
      }

      canvas.width = img.width;
      canvas.height = img.height;

      // 1. Vẽ ảnh gốc
      ctx.drawImage(img, 0, 0);

      // --- LAYER 1: XỬ LÝ PIXEL (Brightness, Contrast, Tone) ---
      // Lấy dữ liệu pixel để thao tác toán học
      const imageData = ctx.getImageData(0, 0, canvas.width, canvas.height);
      const data = imageData.data;

      // Pre-calculate factors
      const contrastFactor = (259 * (settings.contrast + 255)) / (255 * (259 - settings.contrast));
      const lighting = settings.lighting; // -50 to 50

      // Skin Tone Adjustment factors
      let rAdjust = 0, gAdjust = 0, bAdjust = 0;
      if (settings.skinToneIntensity > 0) {
        const intensity = settings.skinToneIntensity / 100; // 0 to 1
        switch (settings.skinToneType) {
            case SkinToneType.FAIR: // Tăng sáng, giảm vàng
                rAdjust = 10 * intensity; gAdjust = 5 * intensity; bAdjust = 10 * intensity; 
                break;
            case SkinToneType.ROSY: // Tăng đỏ/hồng
                rAdjust = 20 * intensity; gAdjust = -5 * intensity; bAdjust = 10 * intensity;
                break;
            case SkinToneType.TAN: // Giảm xanh dương, tăng đỏ
                rAdjust = 20 * intensity; gAdjust = 10 * intensity; bAdjust = -20 * intensity;
                break;
            case SkinToneType.NATURAL:
            default:
                // Nhẹ nhàng ấm
                rAdjust = 5 * intensity; gAdjust = 2 * intensity; bAdjust = -5 * intensity;
                break;
        }
      }

      // Lipstick / Makeup Simulation (Global Tint Approximation - vì không có AI landmark)
      // Nếu user chọn son, ta tăng nhẹ kênh đỏ toàn hình (cách đơn giản nhất mà không có AI)
      if (settings.lipstickIntensity > 0) {
          const lipInt = settings.lipstickIntensity / 400; // Rất nhẹ
          if (settings.lipstickColor === 'red' || settings.lipstickColor === 'pink') {
              rAdjust += 30 * lipInt;
          } else if (settings.lipstickColor === 'orange') {
              rAdjust += 20 * lipInt; gAdjust += 10 * lipInt;
          }
      }

      // Loop qua từng pixel
      for (let i = 0; i < data.length; i += 4) {
        let r = data[i];
        let g = data[i + 1];
        let b = data[i + 2];

        // 1. Contrast
        if (settings.contrast !== 0) {
            r = contrastFactor * (r - 128) + 128;
            g = contrastFactor * (g - 128) + 128;
            b = contrastFactor * (b - 128) + 128;
        }

        // 2. Brightness (Lighting)
        r += lighting;
        g += lighting;
        b += lighting;

        // 3. Skin Tone & Color Balance
        r += rAdjust;
        g += gAdjust;
        b += bAdjust;

        // Clamp values 0-255
        data[i] = r < 0 ? 0 : r > 255 ? 255 : r;
        data[i + 1] = g < 0 ? 0 : g > 255 ? 255 : g;
        data[i + 2] = b < 0 ? 0 : b > 255 ? 255 : b;
      }

      // Đưa dữ liệu pixel đã xử lý lại canvas
      ctx.putImageData(imageData, 0, 0);

      // --- LAYER 2: SMOOTH SKIN (BLUR BLENDING) ---
      if (settings.smoothSkin > 0) {
        // Tạo một canvas tạm để làm mờ
        const tempCanvas = document.createElement('canvas');
        tempCanvas.width = canvas.width;
        tempCanvas.height = canvas.height;
        const tempCtx = tempCanvas.getContext('2d');

        if (tempCtx) {
            // Vẽ ảnh hiện tại (đã chỉnh màu) lên temp
            tempCtx.drawImage(canvas, 0, 0);

            // Blur radius dựa trên settings (1-5)
            const blurRadius = settings.smoothSkin * 1.5;
            tempCtx.filter = `blur(${blurRadius}px)`;
            tempCtx.drawImage(canvas, 0, 0); // Vẽ đè lên chính nó với blur

            // Vẽ lại ảnh mờ lên ảnh gốc với độ trong suốt (Opacity blending)
            // Screen hoặc Lighten giúp làm sáng và mịn da
            ctx.globalAlpha = 0.4 + (settings.smoothSkin * 0.1); // 0.5 -> 1.0 opacity tùy level
            // Dùng 'lighten' để giữ chi tiết tối (mắt/tóc) nhưng làm mờ vùng sáng (da)
            // Tuy nhiên, đơn giản nhất là vẽ đè bình thường với opacity
            ctx.globalCompositeOperation = 'lighten'; 
            ctx.drawImage(tempCanvas, 0, 0);

            // Reset composite
            ctx.globalCompositeOperation = 'source-over';
            ctx.globalAlpha = 1.0;
        }
      }

      // --- LAYER 3: SHARPEN (Tăng nét nếu makeup intensity cao - giả lập makeup) ---
      // Bỏ qua để giữ hiệu năng tốt

      resolve(canvas.toDataURL('image/jpeg', 0.95));
    };

    img.onerror = () => {
      resolve(baseImageSrc); // Fallback
    };
  });
};

import { GoogleGenAI, Type } from "@google/genai";
import { BackgroundType, BeautySettings, PhotoSize, SkinToneType } from "../types";

const API_KEY = process.env.API_KEY || '';

const ai = new GoogleGenAI({ apiKey: API_KEY });

// Schema for the AI Camera analysis response
const analysisSchema = {
  type: Type.OBJECT,
  properties: {
    isCompliant: { type: Type.BOOLEAN },
    status: { type: Type.STRING, enum: ['VALID', 'ADJUSTING', 'INVALID'] },
    feedback: { type: Type.STRING },
    instruction: { type: Type.STRING },
    faceDetected: { type: Type.BOOLEAN }
  },
  required: ['isCompliant', 'status', 'feedback', 'instruction', 'faceDetected']
};

/**
 * Analyzes a webcam frame for ID photo compliance.
 */
export const analyzeIDPhotoFrame = async (base64Frame: string): Promise<{
  isCompliant: boolean;
  status: 'VALID' | 'ADJUSTING' | 'INVALID';
  feedback: string;
  instruction: string;
  faceDetected: boolean;
}> => {
  if (!API_KEY) return { isCompliant: true, status: 'VALID', feedback: 'API Key Missing', instruction: 'Ready', faceDetected: true };

  const cleanBase64 = base64Frame.replace(/^data:image\/(png|jpeg|jpg);base64,/, "");

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: {
        parts: [
          { inlineData: { mimeType: 'image/jpeg', data: cleanBase64 } },
          { text: `You are an automated ID Photo Biometric Compliance System. 
            Analyze this selfie frame for a formal ID/Passport photo.

            Strictly Check:
            1. Face visible and front-facing? (No profile views).
            2. Eyes open and looking at camera?
            3. Mouth closed (neutral expression)?
            4. Head straight (not tilted left/right/up/down)?
            5. Lighting sufficient (not too dark, no harsh shadows)?
            6. No objects covering face (hands, masks, dark glasses)?

            Output JSON. 
            - 'instruction' should be a short, direct command in Vietnamese (e.g., "Mở mắt to hơn", "Nhìn thẳng", "Ngẩng đầu lên").
            - If everything is perfect, 'instruction' should be "Giữ nguyên tư thế".
            ` 
          }
        ]
      },
      config: {
        responseMimeType: 'application/json',
        responseSchema: analysisSchema
      }
    });

    const text = response.text;
    if (!text) throw new Error("No response from AI");

    return JSON.parse(text);

  } catch (error: any) {
    console.error("AI Analysis Error", error);

    const errorStr = error.toString();
    const isQuotaError = errorStr.includes('429') || 
                         error.message?.includes('quota') || 
                         error.message?.includes('limit') ||
                         error.status === 429;

    if (isQuotaError) {
      return { 
        isCompliant: true, 
        status: 'VALID', 
        feedback: 'AI_LIMIT', 
        instruction: 'Chuyển chế độ thủ công', 
        faceDetected: true 
      };
    }

    return { 
      isCompliant: true, 
      status: 'VALID', 
      feedback: 'Lỗi mạng', 
      instruction: 'Chụp thủ công', 
      faceDetected: true 
    };
  }
};

/**
 * Processes the ID photo with strict Layer-based logic.
 * UPDATED: BEAUTY is now handled Client-Side. Gemini only handles Background & Clothing.
 */
export const processIDPhoto = async (
  imageBase64: string, 
  bgType: BackgroundType, 
  clothingPrompt: string | undefined,
  // beautySettings are IGNORED here now
  size: PhotoSize
): Promise<string> => {
  if (!API_KEY) {
    throw new Error("API Key chưa được cấu hình.");
  }

  const cleanBase64 = imageBase64.replace(/^data:image\/(png|jpeg|jpg);base64,/, "");

  // --- LAYER 3: BACKGROUND CONFIG ---
  let bgInstruction = "";
  if (bgType === BackgroundType.WHITE) {
    bgInstruction = "Layer 4 Action: MASK SUBJECT preciseley. FILL BACKGROUND with Pure White (#FFFFFF).";
  } else if (bgType === BackgroundType.BLUE) {
    bgInstruction = "Layer 4 Action: MASK SUBJECT preciseley. FILL BACKGROUND with ID Blue (#0057B7).";
  } else if (bgType === BackgroundType.GRAY) {
    bgInstruction = "Layer 4 Action: MASK SUBJECT preciseley. FILL BACKGROUND with Neutral Gray (#E5E7EB).";
  } else {
    bgInstruction = "Layer 4 Action: Keep Original Background.";
  }

  // --- LAYER 2: CLOTHING CONFIG ---
  let clothingInstruction = "";
  if (clothingPrompt) {
    clothingInstruction = `Layer 3 Action (Clothing): REPLACE current clothes with "${clothingPrompt}". 
    CRITICAL: The collar must sit naturally BELOW the chin/jawline. Do not obscure the chin. Match skin tone at neck.`;
  } else {
    clothingInstruction = "Layer 3 Action (Clothing): Preserve original clothing.";
  }

  // --- FINAL PROMPT CONSTRUCTION (NO BEAUTY) ---
  let prompt = `ROLE: Advanced Image Compositor & Biometric ID Specialist.
TASK: Process the input image through a strict Pipeline. 
OUTPUT: Return the Final Composite Image.

================================================================
🔒 LAYER 0: BIOMETRIC BASE (LOCKED - IMMUTABLE)
================================================================
- DEFINITION: The geometric structure of the face (Eyes, Nose, Mouth, Jawline, Chin, Ears).
- RULE: ZERO TOLERANCE for warping, morphing, or reshaping. 
- The distance between eyes, nose width, and mouth shape MUST be pixel-perfect to original.
- IDENTITY MUST BE PRESERVED 100%.

================================================================
👕 LAYER 2: CLOTHING (OVERLAY)
================================================================
- TARGET: Area below the neck.
${clothingInstruction}
- CONSTRAINT: Clothing layer must NOT overlap the chin or face (Layer 0).

================================================================
🖼️ LAYER 3: BACKGROUND (BOTTOM LAYER)
================================================================
- TARGET: All pixels NOT part of the Subject (Layer 0, 1, 2).
${bgInstruction}
- CONSTRAINT: Hair segmentation must be precise (strands). No "halo" effect.

================================================================
EXECUTION ORDER
================================================================
1. Mask Subject (Keep Face Protected).
2. Apply Layer 3 (Background).
3. Apply Layer 2 (Clothing) if requested.
4. Merge Layers -> Output JPEG.
`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: {
        parts: [
          {
            inlineData: {
              mimeType: 'image/jpeg',
              data: cleanBase64
            }
          },
          {
            text: prompt
          }
        ]
      }
    });

    const parts = response.candidates?.[0]?.content?.parts;
    if (parts) {
      for (const part of parts) {
        if (part.inlineData && part.inlineData.data) {
          return `data:image/jpeg;base64,${part.inlineData.data}`;
        }
      }
    }

    throw new Error("Không nhận được dữ liệu ảnh từ Gemini.");

  } catch (error) {
    console.error("Gemini processing error:", error);
    throw error;
  }
};

import React, { useState, useEffect, useRef } from 'react';
import { BackgroundType, PhotoSettings, PhotoSize, AppConfig, SkinToneType } from '../types';
import { processIDPhoto } from '../services/geminiService';
import { applyAlgorithmicBeauty } from '../utils/imageProcessor';

interface ImageEditorProps {
  originalImage: string;
  settings: PhotoSettings;
  onUpdateSettings: (newSettings: PhotoSettings) => void;
  onProcessedImage: (img: string) => void;
  onNext: () => void;
  onRetake: () => void;
  config: AppConfig;
}

type EditorTab = 'background' | 'beauty' | 'clothing';

const ImageEditor: React.FC<ImageEditorProps> = ({ 
  originalImage, 
  settings, 
  onUpdateSettings,
  onProcessedImage,
  onNext,
  onRetake,
  config
}) => {
  // FINAL displayed image
  const [processedUrl, setProcessedUrl] = useState<string>(originalImage);

  // BASE Layer (Result of AI Background/Clothing ONLY)
  // We keep this separate so when adjusting beauty, we don't re-call AI
  const [baseLayerUrl, setBaseLayerUrl] = useState<string>(originalImage);

  const [isProcessingAI, setIsProcessingAI] = useState(false);
  const [isProcessingBeauty, setIsProcessingBeauty] = useState(false);
  const [activeTab, setActiveTab] = useState<EditorTab>('background');
  const [loadingAction, setLoadingAction] = useState<string>('');

  // Before/After Slider State
  const [sliderPosition, setSliderPosition] = useState(50);
  const imageContainerRef = useRef<HTMLDivElement>(null);
  const isDraggingRef = useRef(false);

  // UI state for debouncing AI calls
  const [clothingInput, setClothingInput] = useState('');
  const [genderTab, setGenderTab] = useState<'male' | 'female'>('male');
  const [securityWarning, setSecurityWarning] = useState('');

  // Accordion state for Beauty Tab
  const [beautySection, setBeautySection] = useState<'skin' | 'makeup' | 'light'>('skin');

  // Initial Load - Process Background if default is set
  useEffect(() => {
    if (settings.background !== BackgroundType.ORIGINAL && baseLayerUrl === originalImage) {
      handleAIProcessing(settings.background, undefined, "Đang xử lý lớp Phông nền...");
    }
  }, []);

  // Effect: Whenever Base Layer OR Beauty Settings change -> Apply Algorithmic Beauty
  useEffect(() => {
    const applyBeauty = async () => {
      setIsProcessingBeauty(true);
      try {
        const beautified = await applyAlgorithmicBeauty(baseLayerUrl, settings.beauty);
        setProcessedUrl(beautified);
      } catch (e) {
        console.error(e);
      } finally {
        setIsProcessingBeauty(false);
      }
    };

    // Debounce slightly for smooth sliding
    const timer = setTimeout(applyBeauty, 50);
    return () => clearTimeout(timer);
  }, [baseLayerUrl, settings.beauty]);

  // --- HANDLER: AI PROCESSING (Background & Clothing ONLY) ---
  const handleAIProcessing = async (
    overrideBg?: BackgroundType, 
    overrideClothing?: string,
    actionName: string = "Đang xử lý AI..."
  ) => {
    setIsProcessingAI(true);
    setLoadingAction(actionName);
    setSecurityWarning('');

    const effBg = overrideBg !== undefined ? overrideBg : settings.background;
    const effClothing = overrideClothing !== undefined ? overrideClothing : settings.clothingPrompt;

    try {
      const isDefault = effBg === BackgroundType.ORIGINAL && !effClothing;

      if (isDefault) {
        setBaseLayerUrl(originalImage);
      } else {
        // Only call Gemini for BG and Clothing. Beauty is ignored in this service call now.
        const result = await processIDPhoto(originalImage, effBg, effClothing, settings.size);
        setBaseLayerUrl(result);
      }

      // Update settings
      onUpdateSettings({ 
        ...settings, 
        background: effBg, 
        clothingPrompt: effClothing
      });

    } catch (err: any) {
      console.error(err);
      setSecurityWarning("Lỗi xử lý AI. Vui lòng thử lại.");
    } finally {
      setIsProcessingAI(false);
      setLoadingAction('');
    }
  };

  // --- HANDLERS ---
  const handleBgChange = (bg: BackgroundType) => handleAIProcessing(bg, undefined, "Đang thay đổi lớp Phông nền...");

  const handleClothingClick = (prompt: string) => {
    setClothingInput(prompt);
    handleAIProcessing(undefined, prompt, prompt ? "Đang thay thế lớp Trang phục..." : "Đang hoàn tác lớp Trang phục...");
  };

  // Beauty Change: Just update state. The useEffect above will catch it and run Algorithmic processing.
  const handleBeautyChange = (key: keyof typeof settings.beauty, value: any) => {
    const newBeauty = { ...settings.beauty, [key]: value };
    onUpdateSettings({ ...settings, beauty: newBeauty });
  };

  const handleMouseMove = (e: React.MouseEvent | React.TouchEvent) => {
    if (!isDraggingRef.current || !imageContainerRef.current) return;
    const rect = imageContainerRef.current.getBoundingClientRect();
    const clientX = 'touches' in e ? e.touches[0].clientX : e.clientX;
    const x = Math.max(0, Math.min(clientX - rect.left, rect.width));
    setSliderPosition((x / rect.width) * 100);
  };

  const handleFinish = () => {
    const canvas = document.createElement('canvas');
    const img = new Image();
    img.src = processedUrl;
    img.crossOrigin = "anonymous";
    img.onload = () => {
      canvas.width = img.width;
      canvas.height = img.height;
      const ctx = canvas.getContext('2d');
      if (ctx) {
        ctx.drawImage(img, 0, 0);
        onProcessedImage(canvas.toDataURL('image/jpeg', 0.95));
        onNext();
      }
    };
  };

  // Filter clothing options
  const activeClothingOptions = config.clothingOptions.filter(item => item.gender === genderTab);

  const SkinToneOptions = [
    { id: SkinToneType.NATURAL, label: 'Tự nhiên', color: '#e5cba6' },
    { id: SkinToneType.FAIR, label: 'Trắng Sáng', color: '#fcebe3' },
    { id: SkinToneType.ROSY, label: 'Trắng Hồng', color: '#ffdee8' },
    { id: SkinToneType.TAN, label: 'Ngăm Khỏe', color: '#cd9b75' },
  ];

  const renderBackgrounds = () => {
    const bgs = [...config.backgroundConfig];
    return (
      <>
        {bgs.map(bg => (
           <button 
              key={bg.type}
              onClick={() => handleBgChange(bg.type)} 
              disabled={isProcessingAI}
              className={`relative h-32 rounded-2xl border-2 flex flex-col items-center justify-center gap-3 transition-all group ${
                settings.background === bg.type 
                  ? 'border-brand-500 bg-brand-50 shadow-md ring-1 ring-brand-200' 
                  : 'border-slate-100 hover:border-brand-200 hover:bg-slate-50'
              }`}
            >
              <div 
                className={`w-12 h-12 rounded-full shadow-inner ${settings.background === bg.type ? 'ring-2 ring-offset-2 ring-brand-400' : ''}`}
                style={{ backgroundColor: bg.hexColor }}
              ></div>
              <span className={`text-xs font-bold ${settings.background === bg.type ? 'text-brand-700' : 'text-gray-600'}`}>{bg.label}</span>

              {settings.background === bg.type && (
                <div className="absolute top-2 right-2 text-brand-500 bg-white rounded-full p-0.5 shadow-sm">
                  <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M5 13l4 4L19 7"></path></svg>
                </div>
              )}
            </button>
        ))}
        {/* Original */}
        <button 
          onClick={() => handleBgChange(BackgroundType.ORIGINAL)} 
          disabled={isProcessingAI}
          className={`relative h-32 rounded-2xl border-2 flex flex-col items-center justify-center gap-3 transition-all group ${
            settings.background === BackgroundType.ORIGINAL
              ? 'border-brand-500 bg-brand-50 shadow-md ring-1 ring-brand-200' 
              : 'border-slate-100 hover:border-brand-200 hover:bg-slate-50'
          }`}
        >
          <div className={`w-12 h-12 rounded-full shadow-inner bg-[url('https://placehold.co/32x32/png')] bg-cover opacity-50 ${settings.background === BackgroundType.ORIGINAL ? 'ring-2 ring-offset-2 ring-brand-400' : ''}`}></div>
          <span className={`text-xs font-bold ${settings.background === BackgroundType.ORIGINAL ? 'text-brand-700' : 'text-gray-600'}`}>Ảnh Gốc</span>
           {settings.background === BackgroundType.ORIGINAL && (
                <div className="absolute top-2 right-2 text-brand-500 bg-white rounded-full p-0.5 shadow-sm">
                  <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M5 13l4 4L19 7"></path></svg>
                </div>
              )}
        </button>
      </>
    );
  };

  const isProcessing = isProcessingAI || isProcessingBeauty;

  return (
    <div className="flex flex-col md:flex-row h-full w-full bg-slate-100 overflow-hidden font-sans"
      onMouseMove={handleMouseMove}
      onTouchMove={handleMouseMove}
      onMouseUp={() => { isDraggingRef.current = false; }}
      onTouchEnd={() => { isDraggingRef.current = false; }}
    >

      {/* LEFT: Sidebar / Controls */}
      <div className="w-full md:w-[420px] bg-white shadow-2xl z-20 flex flex-col h-full border-r border-gray-200">

        {/* Header */}
        <div className="p-5 border-b border-gray-100 bg-white flex justify-between items-center">
          <h2 className="text-xl font-extrabold text-gray-800 flex items-center gap-2">
            <span className="text-brand-600 text-2xl">✨</span> Chỉnh sửa
          </h2>
          <div className="flex flex-col items-end">
            <div className="text-[10px] font-bold text-gray-400 uppercase tracking-wider">Editor Pro</div>
            {isProcessingBeauty && <span className="text-[9px] text-blue-500 animate-pulse">Applying filters...</span>}
          </div>
        </div>

        {/* SEGMENTED CONTROL TABS */}
        <div className="px-5 pt-4 pb-2">
          <div className="flex bg-gray-100 p-1 rounded-xl">
            {(['background', 'beauty', 'clothing'] as EditorTab[]).map((tab) => (
               <button
                key={tab}
                onClick={() => setActiveTab(tab)}
                className={`flex-1 py-3 text-xs font-bold uppercase tracking-wide rounded-lg transition-all duration-200 ${
                  activeTab === tab 
                    ? 'bg-white text-brand-600 shadow-sm' 
                    : 'text-gray-500 hover:text-gray-700'
                }`}
              >
                {tab === 'background' ? 'Phông nền' : tab === 'beauty' ? 'Làm đẹp' : 'Trang phục'}
              </button>
            ))}
          </div>
        </div>

        {/* SCROLLABLE CONTENT */}
        <div className="flex-1 overflow-y-auto p-5 bg-white scrollbar-hide">

          {/* --- BACKGROUND TAB --- */}
          {activeTab === 'background' && (
            <div className="space-y-6 animate-fadeIn">
              <div className="grid grid-cols-2 gap-4">
                {renderBackgrounds()}
              </div>
            </div>
          )}

          {/* --- BEAUTY TAB (ALGORITHMIC) --- */}
          {activeTab === 'beauty' && (
            <div className="space-y-4 animate-fadeIn">

              <div className="bg-green-50/50 p-3 rounded-xl border border-green-100 mb-2">
                <p className="text-[11px] text-green-700 font-medium flex gap-2">
                  <svg className="w-4 h-4 shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M13 10V3L4 14h7v7l9-11h-7z"></path></svg>
                  Chế độ thuật toán (Algorithmic Mode): Xử lý nhanh, không sử dụng AI.
