          <span className={`text-xs font-bold ${settings.background === BackgroundType.ORIGINAL ? 'text-brand-700' : 'text-gray-600'}`}>Ảnh Gốc</span>
           {settings.background === BackgroundType.ORIGINAL && (
                <div className="absolute top-2 right-2 text-brand-500 bg-white rounded-full p-0.5 shadow-sm">
                  <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M5 13l4 4L19 7"></path></svg>
