import { GoogleGenAI, Type } from "@google/genai";
import { BackgroundType, PhotoSize } from "../types";

const API_KEY = process.env.API_KEY || '';

const ai = new GoogleGenAI({ apiKey: API_KEY });

// Schema for the AI Camera analysis response
const analysisSchema = {
  type: Type.OBJECT,
  properties: {
    isCompliant: { type: Type.BOOLEAN },
    status: { type: Type.STRING, enum: ['VALID', 'ADJUSTING', 'INVALID'] },
    feedback: { type: Type.STRING },
    instruction: { type: Type.STRING },
    faceDetected: { type: Type.BOOLEAN }
  },
  required: ['isCompliant', 'status', 'feedback', 'instruction', 'faceDetected']
};

/**
 * Analyzes a webcam frame for ID photo compliance.
 */
export const analyzeIDPhotoFrame = async (base64Frame: string): Promise<{
  isCompliant: boolean;
  status: 'VALID' | 'ADJUSTING' | 'INVALID';
  feedback: string;
  instruction: string;
  faceDetected: boolean;
}> => {
  if (!API_KEY) return { isCompliant: true, status: 'VALID', feedback: 'API Key Missing', instruction: 'Ready', faceDetected: true };

  const cleanBase64 = base64Frame.replace(/^data:image\/(png|jpeg|jpg);base64,/, "");

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: {
        parts: [
          { inlineData: { mimeType: 'image/jpeg', data: cleanBase64 } },
          { text: `You are an automated ID Photo Biometric Compliance System. 
            Analyze this selfie frame for a formal ID/Passport photo.

            Strictly Check:
            1. Face visible and front-facing? (No profile views).
            2. Eyes open and looking at camera?
            3. Mouth closed (neutral expression)?
            4. Head straight (not tilted left/right/up/down)?
            5. Lighting sufficient (not too dark, no harsh shadows)?
            6. No objects covering face (hands, masks, dark glasses)?

            Output JSON. 
            - 'instruction' should be a short, direct command in Vietnamese (e.g., "Mở mắt to hơn", "Nhìn thẳng", "Ngẩng đầu lên").
            - If everything is perfect, 'instruction' should be "Giữ nguyên tư thế".
            ` 
          }
        ]
      },
      config: {
        responseMimeType: 'application/json',
        responseSchema: analysisSchema
      }
    });

    const text = response.text;
    if (!text) throw new Error("No response from AI");

    return JSON.parse(text);

  } catch (error: any) {
    console.error("AI Analysis Error", error);

    const errorStr = error.toString();
    const isQuotaError = errorStr.includes('429') || 
                         error.message?.includes('quota') || 
                         error.message?.includes('limit') ||
                         error.status === 429;

    if (isQuotaError) {
      return { 
        isCompliant: true, 
        status: 'VALID', 
        feedback: 'AI_LIMIT', 
        instruction: 'Chuyển chế độ thủ công', 
        faceDetected: true 
      };
    }

    return { 
      isCompliant: true, 
      status: 'VALID', 
      feedback: 'Lỗi mạng', 
      instruction: 'Chụp thủ công', 
      faceDetected: true 
    };
  }
};

/**
 * Processes the ID photo with strict Layer-based logic.
 * UPDATED: Only handles CLOTHING now. Background and Beauty are handled algorithmically client-side.
 */
export const processIDPhoto = async (
  imageBase64: string, 
  bgType: BackgroundType, // Kept for interface compatibility but ignored for background generation logic inside AI
  clothingPrompt: string | undefined,
  size: PhotoSize
): Promise<string> => {
  if (!API_KEY) {
    throw new Error("API Key chưa được cấu hình.");
  }

  // If no clothing prompt, we just return the original because BG is now handled locally
  if (!clothingPrompt) {
      return imageBase64;
  }

  const cleanBase64 = imageBase64.replace(/^data:image\/(png|jpeg|jpg);base64,/, "");

  // --- LAYER 2: CLOTHING CONFIG ---
  const clothingInstruction = `Layer 3 Action (Clothing): REPLACE current clothes with "${clothingPrompt}". 
    CRITICAL: The collar must sit naturally BELOW the chin/jawline. Do not obscure the chin. Match skin tone at neck.`;

  // --- FINAL PROMPT CONSTRUCTION ---
  let prompt = `ROLE: Advanced Image Compositor & Biometric ID Specialist.
TASK: Replace clothing ONLY. Keep background and face exactly as is.
OUTPUT: Return the Final Composite Image.

================================================================
🔒 LAYER 0: BIOMETRIC BASE (LOCKED - IMMUTABLE)
================================================================
- DEFINITION: The geometric structure of the face (Eyes, Nose, Mouth, Jawline, Chin, Ears).
- RULE: ZERO TOLERANCE for warping, morphing, or reshaping. 
- IDENTITY MUST BE PRESERVED 100%.

================================================================
👕 LAYER 2: CLOTHING (OVERLAY)
================================================================
- TARGET: Area below the neck.
${clothingInstruction}
- CONSTRAINT: Clothing layer must NOT overlap the chin or face (Layer 0).

================================================================
EXECUTION ORDER
================================================================
1. Mask Subject (Keep Face Protected).
2. Apply Layer 2 (Clothing).
3. Merge Layers -> Output JPEG.
`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: {
        parts: [
          {
            inlineData: {
              mimeType: 'image/jpeg',
              data: cleanBase64
            }
          },
          {
            text: prompt
          }
        ]
      }
    });

    const parts = response.candidates?.[0]?.content?.parts;
    if (parts) {
      for (const part of parts) {
        if (part.inlineData && part.inlineData.data) {
          return `data:image/jpeg;base64,${part.inlineData.data}`;
        }
      }
    }

    throw new Error("Không nhận được dữ liệu ảnh từ Gemini.");

  } catch (error) {
    console.error("Gemini processing error:", error);
    throw error;
  }
};

import { BeautySettings, SkinToneType } from "../types";

// --- HELPER: COLOR SPACE CONVERSION ---
function rgbToYcbcr(r: number, g: number, b: number) {
  const y = 0.299 * r + 0.587 * g + 0.114 * b;
  const cb = 128 - 0.168736 * r - 0.331264 * g + 0.5 * b;
  const cr = 128 + 0.5 * r - 0.418688 * g - 0.081312 * b;
  return { y, cb, cr };
}

// --- HELPER: SKIN DETECTION ---
function isSkinPixel(r: number, g: number, b: number): boolean {
  const { cb, cr } = rgbToYcbcr(r, g, b);
  // Thresholds for skin in YCbCr (Empirical values)
  return (cb > 80 && cb < 130 && cr > 130 && cr < 170);
}

// --- ALGORITHM: FACE BLOB DETECTION ---
// Scans the image to find the bounding box of the face based on skin clusters
function detectFaceBounds(data: Uint8ClampedArray, width: number, height: number) {
  let minX = width, minY = height, maxX = 0, maxY = 0;
  let found = false;

  // Optimization: Skip step pixels to be faster
  const step = 4; 
  for (let y = 0; y < height; y += step) {
    for (let x = 0; x < width; x += step) {
      const i = (y * width + x) * 4;
      if (isSkinPixel(data[i], data[i+1], data[i+2])) {
        if (x < minX) minX = x;
        if (x > maxX) maxX = x;
        if (y < minY) minY = y;
        if (y > maxY) maxY = y;
        found = true;
      }
    }
  }

  if (!found) return null;

  const faceWidth = maxX - minX;
  const faceHeight = maxY - minY;

  // Heuristic adjustments:
  // Skin detection usually misses the forehead (hair) and chin shadow.
  // We expand the box to approximate the full head.
  return {
    x: Math.max(0, minX - faceWidth * 0.15),
    y: Math.max(0, minY - faceHeight * 0.4), // More space on top for hair/forehead
    width: Math.min(width, faceWidth * 1.3),
    height: Math.min(height, faceHeight * 1.6) // Extend down for neck/chin
  };
}

// --- ALGORITHM: FLOOD FILL BACKGROUND REMOVAL ---
// Replaces background with transparent pixels starting from corners
function removeBackgroundFloodFill(
  ctx: CanvasRenderingContext2D, 
  width: number, 
  height: number, 
  tolerance: number = 40
) {
  const imageData = ctx.getImageData(0, 0, width, height);
  const data = imageData.data;
  const visited = new Uint8Array(width * height); // 0: unvisited, 1: visited

  // Queue for BFS: [x, y]
  const queue: [number, number][] = [];

  // Start from 4 corners (assuming solid background)
  const seeds = [
    {x: 0, y: 0}, 
    {x: width-1, y: 0}, 
    {x: 0, y: height-1}, 
    {x: width-1, y: height-1}
  ];

  // Get reference background colors from seeds
  const bgColors: {r:number, g:number, b:number}[] = [];

  seeds.forEach(p => {
    const i = (p.y * width + p.x) * 4;
    bgColors.push({ r: data[i], g: data[i+1], b: data[i+2] });
    queue.push([p.x, p.y]);
    visited[p.y * width + p.x] = 1;
  });

  // Calculate average BG color for initial check
  const avgBg = bgColors.reduce((acc, c) => ({r: acc.r+c.r, g: acc.g+c.g, b: acc.b+c.b}), {r:0,g:0,b:0});
  avgBg.r /= bgColors.length;
  avgBg.g /= bgColors.length;
  avgBg.b /= bgColors.length;

  // Directions: Up, Down, Left, Right
  const dx = [0, 0, -1, 1];
  const dy = [-1, 1, 0, 0];

  while (queue.length > 0) {
    const [cx, cy] = queue.shift()!;
    const ci = (cy * width + cx) * 4;

    // Make pixel transparent
    data[ci + 3] = 0; 

    // Check neighbors
    for (let i = 0; i < 4; i++) {
      const nx = cx + dx[i];
      const ny = cy + dy[i];

      if (nx >= 0 && nx < width && ny >= 0 && ny < height) {
        const niOffset = ny * width + nx;
        if (visited[niOffset] === 0) {
          const ni = niOffset * 4;
          const nr = data[ni];
          const ng = data[ni+1];
          const nb = data[ni+2];

          // Color Distance
          const dist = Math.sqrt(
            Math.pow(nr - avgBg.r, 2) + 
            Math.pow(ng - avgBg.g, 2) + 
            Math.pow(nb - avgBg.b, 2)
          );

          if (dist < tolerance) {
            visited[niOffset] = 1;
            queue.push([nx, ny]);
          }
        }
      }
    }
  }

  ctx.putImageData(imageData, 0, 0);
}

// --- MAIN FUNCTION: ALGORITHMIC BEAUTY & MAKEUP ---
export const applyAlgorithmicBeauty = async (
  baseImageSrc: string,
  settings: BeautySettings
): Promise<string> => {
  return new Promise((resolve) => {
    const img = new Image();
    img.crossOrigin = "anonymous";
    img.src = baseImageSrc;

    img.onload = () => {
      const w = img.width;
      const h = img.height;

      const canvas = document.createElement("canvas");
      canvas.width = w;
      canvas.height = h;
      const ctx = canvas.getContext("2d");

      if (!ctx) {
        resolve(baseImageSrc);
        return;
      }

      // 1. Draw Original
      ctx.drawImage(img, 0, 0);

      const imageData = ctx.getImageData(0, 0, w, h);

      // --- STEP A: DETECT FACE BOUNDS (For Heuristic Makeup) ---
      // We detect face on the ORIGINAL image data before modifying it
      const face = detectFaceBounds(imageData.data, w, h);

      // --- STEP B: BASIC IMAGE CORRECTIONS (Lighting/Contrast) ---
      const d = imageData.data;
      const contrastF = (259 * (settings.contrast + 255)) / (255 * (259 - settings.contrast));
      const lighting = settings.lighting;

      for (let i = 0; i < d.length; i += 4) {
        let r = d[i], g = d[i+1], b = d[i+2];

        // Contrast
        r = contrastF * (r - 128) + 128;
        g = contrastF * (g - 128) + 128;
        b = contrastF * (b - 128) + 128;

        // Lighting
        r += lighting; g += lighting; b += lighting;

        // Clamp
        d[i] = Math.max(0, Math.min(255, r));
        d[i+1] = Math.max(0, Math.min(255, g));
        d[i+2] = Math.max(0, Math.min(255, b));
      }
      ctx.putImageData(imageData, 0, 0);

      // --- STEP C: SMOOTH SKIN (BLUR) ---
      if (settings.smoothSkin > 0) {
         // Create a skin mask
         const maskCanvas = document.createElement('canvas');
         maskCanvas.width = w; maskCanvas.height = h;
         const maskCtx = maskCanvas.getContext('2d')!;
         const maskData = maskCtx.createImageData(w, h);

         for(let i=0; i<d.length; i+=4) {
            if (isSkinPixel(d[i], d[i+1], d[i+2])) {
                maskData.data[i+3] = 255; // Skin = Opaque
            } else {
                maskData.data[i+3] = 0;   // Non-skin = Transparent
            }
         }
         maskCtx.putImageData(maskData, 0, 0);

         // Create Blurred version
         const blurCanvas = document.createElement('canvas');
         blurCanvas.width = w; blurCanvas.height = h;
         const blurCtx = blurCanvas.getContext('2d')!;
         blurCtx.drawImage(canvas, 0, 0);
         blurCtx.filter = `blur(${settings.smoothSkin * 1.5}px)`; 
         blurCtx.drawImage(blurCanvas, 0, 0);
         blurCtx.filter = 'none';

         // Composite: Blur where Mask is White
         blurCtx.globalCompositeOperation = 'destination-in';
         blurCtx.drawImage(maskCanvas, 0, 0);

         // Blend back
         ctx.globalCompositeOperation = 'lighten'; // Keep shadows sharp
         ctx.globalAlpha = 0.6;
         ctx.drawImage(blurCanvas, 0, 0);
         ctx.globalAlpha = 1.0;
         ctx.globalCompositeOperation = 'source-over';
      }

      // --- STEP D: MAKEUP (HEURISTIC REGIONS) ---
      // We use the detected face bounding box to guess where features are.
      if (face) {
         const fx = face.x;
         const fy = face.y;
         const fw = face.width;
         const fh = face.height;

         // 1. LIPSTICK (Môi)
         // Heuristic: Bottom 1/5 of face height, center horizontal
         if (settings.lipstickIntensity > 0) {
            const lipY = fy + fh * 0.78; // Approx position
            const lipX = fx + fw * 0.35;
            const lipW = fw * 0.3;
            const lipH = fh * 0.08;

            ctx.save();
            // 'soft-light' blends color nicely without killing texture
            ctx.globalCompositeOperation = 'soft-light'; 
            ctx.globalAlpha = settings.lipstickIntensity / 100;

            // Color Mapping
            let lipColor = '#ec4899'; // Default Pink
            if (settings.lipstickColor === 'red') lipColor = '#ef4444';
            if (settings.lipstickColor === 'orange') lipColor = '#f97316';
            if (settings.lipstickColor === 'nude') lipColor = '#d6a692';

            ctx.fillStyle = lipColor;

            // Draw Ellipse for lips
            ctx.beginPath();
            ctx.ellipse(lipX + lipW/2, lipY + lipH/2, lipW/2, lipH/2, 0, 0, 2 * Math.PI);
            ctx.filter = 'blur(8px)'; // Heavy blur to make it a soft tint
            ctx.fill();
            ctx.restore();
         }

         // 2. BLUSH (Má hồng)
         // Heuristic: Below eyes, outer cheeks
         if (settings.blushIntensity > 0) {
             const blushY = fy + fh * 0.55;
             const blushW = fw * 0.15;
             const blushH = fh * 0.1;

             ctx.save();
             ctx.globalCompositeOperation = 'multiply'; // Darkens/Tints skin
             ctx.globalAlpha = (settings.blushIntensity / 100) * 0.3; // Subtle
             ctx.fillStyle = '#f472b6'; // Pinkish
             ctx.filter = 'blur(20px)'; // Very soft, large area

             // Left Cheek
             ctx.beginPath();
             ctx.ellipse(fx + fw * 0.25, blushY, blushW, blushH, 0, 0, 2 * Math.PI);
             ctx.fill();

             // Right Cheek
             ctx.beginPath();
             ctx.ellipse(fx + fw * 0.75, blushY, blushW, blushH, 0, 0, 2 * Math.PI);
             ctx.fill();
             ctx.restore();
         }

         // 3. EYEBROWS (Chân mày)
         // Heuristic: Top 1/3, above eyes
         if (settings.eyebrowIntensity > 0) {
            const browY = fy + fh * 0.35;
            const browW = fw * 0.25;
            const browH = fh * 0.03;

            ctx.save();
            ctx.globalCompositeOperation = 'multiply'; // Darken
            ctx.globalAlpha = (settings.eyebrowIntensity / 100) * 0.4;
            ctx.fillStyle = '#1a1a1a'; // Dark Gray
            ctx.filter = 'blur(6px)'; // Soften

            // Left Brow
            ctx.beginPath();
            // Slightly arched path could be better, but ellipse is decent for heuristic tint
            ctx.ellipse(fx + fw * 0.3, browY, browW/2, browH, -0.1, 0, 2 * Math.PI);
            ctx.fill();

            // Right Brow
            ctx.beginPath();
            ctx.ellipse(fx + fw * 0.7, browY, browW/2, browH, 0.1, 0, 2 * Math.PI);
            ctx.fill();
            ctx.restore();
         }
      }

      resolve(canvas.toDataURL('image/jpeg', 0.95));
    };
    img.onerror = () => resolve(baseImageSrc);
  });
};

// --- ALGORITHM: AUTO CROP ---
export const autoCropFace = async (imageSrc: string): Promise<string> => {
   return new Promise((resolve) => {
      const img = new Image();
      img.src = imageSrc;
      img.crossOrigin = "anonymous";
      img.onload = () => {
         const canvas = document.createElement('canvas');
         canvas.width = img.width;
         canvas.height = img.height;
         const ctx = canvas.getContext('2d')!;
         ctx.drawImage(img, 0, 0);

         const imageData = ctx.getImageData(0,0, canvas.width, canvas.height);
         const face = detectFaceBounds(imageData.data, canvas.width, canvas.height);

         if (!face) {
            resolve(imageSrc); // No face found, return original
            return;
         }

         // Crop Logic
         // Ideally keep aspect ratio (e.g. 2:3 for 4x6).
         // Here we crop to the detected head with padding.
         const cropCanvas = document.createElement('canvas');
         cropCanvas.width = face.width;
         cropCanvas.height = face.height;
         const cropCtx = cropCanvas.getContext('2d')!;

         cropCtx.drawImage(
            canvas, 
            face.x, face.y, face.width, face.height, 
            0, 0, face.width, face.height
         );

         resolve(cropCanvas.toDataURL('image/jpeg', 0.95));
      };
   });
};

// --- ALGORITHM: BACKGROUND REPLACEMENT (ALGORITHMIC) ---
export const replaceBackgroundAlgorithmic = async (
    imageSrc: string, 
    hexColor: string | null
): Promise<string> => {
    return new Promise((resolve) => {
        const img = new Image();
        img.src = imageSrc;
        img.crossOrigin = "anonymous";
        img.onload = () => {
            const canvas = document.createElement('canvas');
            canvas.width = img.width;
            canvas.height = img.height;
            const ctx = canvas.getContext('2d')!;
            ctx.drawImage(img, 0, 0);

            // 1. Remove BG (Flood fill from corners)
            // Tolerance 35 covers minor shadows/noise in uniform backgrounds
            removeBackgroundFloodFill(ctx, canvas.width, canvas.height, 35);

            // 2. If hexColor is provided, composite it
            if (hexColor) {
                // Create a new canvas to put color behind
                const compCanvas = document.createElement('canvas');
                compCanvas.width = canvas.width;
                compCanvas.height = canvas.height;
                const compCtx = compCanvas.getContext('2d')!;

                // Fill BG
                compCtx.fillStyle = hexColor;
                compCtx.fillRect(0,0, compCanvas.width, compCanvas.height);

                // Draw Foreground
                compCtx.drawImage(canvas, 0, 0);
                resolve(compCanvas.toDataURL('image/jpeg', 0.95));
            } else {
                // Return PNG with transparency
                resolve(canvas.toDataURL('image/png'));
            }
        };
    });
};

import React, { useState, useEffect, useRef } from 'react';
import { BackgroundType, PhotoSettings, PhotoSize, AppConfig, SkinToneType } from '../types';
import { processIDPhoto } from '../services/geminiService';
import { applyAlgorithmicBeauty, autoCropFace, replaceBackgroundAlgorithmic } from '../utils/imageProcessor';

interface ImageEditorProps {
  originalImage: string;
  settings: PhotoSettings;
  onUpdateSettings: (newSettings: PhotoSettings) => void;
  onProcessedImage: (img: string) => void;
  onNext: () => void;
  onRetake: () => void;
  config: AppConfig;
}

type EditorTab = 'background' | 'beauty' | 'clothing';

const ImageEditor: React.FC<ImageEditorProps> = ({ 
  originalImage, 
  settings, 
  onUpdateSettings,
  onProcessedImage,
  onNext,
  onRetake,
  config
}) => {
  // FINAL displayed image
  const [processedUrl, setProcessedUrl] = useState<string>(originalImage);

  // BASE Layer (Result of Background/Crop/Clothing)
  // Beauty filters are applied ON TOP of this layer to allow real-time sliders
  const [baseLayerUrl, setBaseLayerUrl] = useState<string>(originalImage);

  const [isProcessingAI, setIsProcessingAI] = useState(false);
  const [isProcessingBeauty, setIsProcessingBeauty] = useState(false);
  const [activeTab, setActiveTab] = useState<EditorTab>('background');
  const [loadingAction, setLoadingAction] = useState<string>('');

  // Before/After Slider State
  const [sliderPosition, setSliderPosition] = useState(50);
  const imageContainerRef = useRef<HTMLDivElement>(null);
  const isDraggingRef = useRef(false);

  // UI state
  const [clothingInput, setClothingInput] = useState('');
  const [genderTab, setGenderTab] = useState<'male' | 'female'>('male');
  const [beautySection, setBeautySection] = useState<'skin' | 'makeup' | 'light'>('skin');

  // Initial Load - Process Background if default is set
  useEffect(() => {
    if (settings.background !== BackgroundType.ORIGINAL && baseLayerUrl === originalImage) {
      handleBackgroundProcessing(settings.background);
    }
  }, []);

  // Effect: Whenever Base Layer OR Beauty Settings change -> Apply Algorithmic Beauty
  useEffect(() => {
    const applyBeauty = async () => {
      setIsProcessingBeauty(true);
      try {
        const beautified = await applyAlgorithmicBeauty(baseLayerUrl, settings.beauty);
        setProcessedUrl(beautified);
      } catch (e) {
        console.error(e);
      } finally {
        setIsProcessingBeauty(false);
      }
    };

    // Debounce slightly for smooth sliding
    const timer = setTimeout(applyBeauty, 80);
    return () => clearTimeout(timer);
  }, [baseLayerUrl, settings.beauty]);

  // --- ALGORITHMIC HANDLERS ---

  const handleAutoCrop = async () => {
      setLoadingAction("Đang quét khuôn mặt...");
      setIsProcessingAI(true); 
      try {
          const cropped = await autoCropFace(baseLayerUrl);
          setBaseLayerUrl(cropped);
      } catch (e) {
          console.error(e);
      } finally {
          setIsProcessingAI(false);
          setLoadingAction('');
      }
  };

  const handleBackgroundProcessing = async (bgType: BackgroundType) => {
    setLoadingAction("Đang tách nền...");
    setIsProcessingAI(true);

    // Find Hex Color
    let hex = null;
    const bgConfig = config.backgroundConfig.find(b => b.type === bgType);
    if (bgConfig) hex = bgConfig.hexColor;

    try {
        if (bgType === BackgroundType.ORIGINAL) {
            setBaseLayerUrl(originalImage);
        } else {
            // Use Flood Fill Algorithm
            const result = await replaceBackgroundAlgorithmic(originalImage, hex);
            setBaseLayerUrl(result);
        }

        onUpdateSettings({ ...settings, background: bgType });
    } catch (e) {
        console.error(e);
    } finally {
        setIsProcessingAI(false);
        setLoadingAction('');
    }
  };

  const handleClothingChange = async (prompt: string) => {
      // Clothing still uses AI (Gemini) as requested
      setLoadingAction("Đang thay trang phục (AI)...");
      setIsProcessingAI(true);
      setClothingInput(prompt);
      try {
          // Pass the CURRENT BG Type, but logic is handled inside service
          const result = await processIDPhoto(originalImage, settings.background, prompt, settings.size);
          setBaseLayerUrl(result);
          onUpdateSettings({ ...settings, clothingPrompt: prompt });
      } catch (e) {
          console.error(e);
      } finally {
          setIsProcessingAI(false);
          setLoadingAction('');
      }
  };

  // --- HANDLERS ---

  const handleBeautyChange = (key: keyof typeof settings.beauty, value: any) => {
    const newBeauty = { ...settings.beauty, [key]: value };
    onUpdateSettings({ ...settings, beauty: newBeauty });
  };

  const handleMouseMove = (e: React.MouseEvent | React.TouchEvent) => {
    if (!isDraggingRef.current || !imageContainerRef.current) return;
    const rect = imageContainerRef.current.getBoundingClientRect();
    const clientX = 'touches' in e ? e.touches[0].clientX : e.clientX;
    const x = Math.max(0, Math.min(clientX - rect.left, rect.width));
    setSliderPosition((x / rect.width) * 100);
  };

  const handleFinish = () => {
    const canvas = document.createElement('canvas');
    const img = new Image();
    img.src = processedUrl;
    img.crossOrigin = "anonymous";
    img.onload = () => {
      canvas.width = img.width;
      canvas.height = img.height;
      const ctx = canvas.getContext('2d');
      if (ctx) {
        ctx.drawImage(img, 0, 0);
        onProcessedImage(canvas.toDataURL('image/jpeg', 0.95));
        onNext();
      }
    };
  };

  const activeClothingOptions = config.clothingOptions.filter(item => item.gender === genderTab);

  const SkinToneOptions = [
