          {isProcessing && (
            <div className="absolute inset-0 z-30 bg-black/40 flex flex-col items-center justify-center backdrop-blur-[2px]">
               <div className="bg-white p-6 rounded-2xl shadow-2xl flex flex-col items-center animate-bounce-in">
                 <div className="w-12 h-12 border-4 border-brand-200 border-t-brand-600 rounded-full animate-spin mb-3"></div>
                 <p className="text-brand-800 font-bold text-sm">{loadingAction || 'Đang xử lý...'}</p>
                 <p className="text-[10px] text-gray-400 mt-1">
                   Algorithmic Processing
                 </p>
               </div>
            </div>
          )}

          {/* BACKGROUND IMAGE (AFTER) */}
          <img 
            src={processedUrl} 
            alt="After" 
            className="absolute inset-0 w-full h-full object-contain pointer-events-none bg-white"
          />

          {/* FOREGROUND IMAGE (BEFORE) - Clipped */}
          <div 
            className="absolute inset-0 w-full h-full overflow-hidden border-r-2 border-white pointer-events-none bg-white"
            style={{ width: `${sliderPosition}%` }}
          >
             <img 
              src={originalImage} 
              alt="Before" 
              className="absolute inset-0 w-full h-full object-contain max-w-none" 
            />

            {/* Slider Handle */}
            <div className="absolute top-1/2 right-0 transform translate-x-1/2 -translate-y-1/2 w-10 h-10 bg-white rounded-full shadow-xl flex items-center justify-center z-20 cursor-ew-resize hover:scale-110 transition-transform border border-gray-100">
              <svg className="w-5 h-5 text-brand-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M8 9l4-4 4 4m0 6l-4 4-4-4"></path></svg>
            </div>
          </div>

        </div>

      </div>

      <style>{`
        .scrollbar-hide::-webkit-scrollbar {
            display: none;
        }
        .scrollbar-hide {
            -ms-overflow-style: none;
            scrollbar-width: none;
        }
        @keyframes fadeIn {
          from { opacity: 0; transform: translateY(5px); }
          to { opacity: 1; transform: translateY(0); }
        }
        .animate-fadeIn {
          animation: fadeIn 0.3s ease-out forwards;
        }
      `}</style>
    </div>
  );
};

export default ImageEditor;

import { GoogleGenAI, Type } from "@google/genai";
import { BackgroundType, PhotoSize } from "../types";

const API_KEY = process.env.API_KEY || '';

const ai = new GoogleGenAI({ apiKey: API_KEY });

// Schema for the AI Camera analysis response
const analysisSchema = {
  type: Type.OBJECT,
  properties: {
    isCompliant: { type: Type.BOOLEAN },
    status: { type: Type.STRING, enum: ['VALID', 'ADJUSTING', 'INVALID'] },
    feedback: { type: Type.STRING },
    instruction: { type: Type.STRING },
    faceDetected: { type: Type.BOOLEAN }
  },
  required: ['isCompliant', 'status', 'feedback', 'instruction', 'faceDetected']
};

/**
 * Analyzes a webcam frame for ID photo compliance.
 */
export const analyzeIDPhotoFrame = async (base64Frame: string): Promise<{
  isCompliant: boolean;
  status: 'VALID' | 'ADJUSTING' | 'INVALID';
  feedback: string;
  instruction: string;
  faceDetected: boolean;
}> => {
  if (!API_KEY) return { isCompliant: true, status: 'VALID', feedback: 'API Key Missing', instruction: 'Ready', faceDetected: true };

  const cleanBase64 = base64Frame.replace(/^data:image\/(png|jpeg|jpg);base64,/, "");

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: {
        parts: [
          { inlineData: { mimeType: 'image/jpeg', data: cleanBase64 } },
          { text: `You are an automated ID Photo Biometric Compliance System. 
            Analyze this selfie frame for a formal ID/Passport photo.

            Strictly Check:
            1. Face visible and front-facing? (No profile views).
            2. Eyes open and looking at camera?
            3. Mouth closed (neutral expression)?
            4. Head straight (not tilted left/right/up/down)?
            5. Lighting sufficient (not too dark, no harsh shadows)?
            6. No objects covering face (hands, masks, dark glasses)?

            Output JSON. 
            - 'instruction' should be a short, direct command in Vietnamese (e.g., "Mở mắt to hơn", "Nhìn thẳng", "Ngẩng đầu lên").
            - If everything is perfect, 'instruction' should be "Giữ nguyên tư thế".
            ` 
          }
        ]
      },
      config: {
        responseMimeType: 'application/json',
        responseSchema: analysisSchema
      }
    });

    const text = response.text;
    if (!text) throw new Error("No response from AI");

    return JSON.parse(text);

  } catch (error: any) {
    console.error("AI Analysis Error", error);

    const errorStr = error.toString();
    const isQuotaError = errorStr.includes('429') || 
                         error.message?.includes('quota') || 
                         error.message?.includes('limit') ||
                         error.status === 429;

    if (isQuotaError) {
      return { 
        isCompliant: true, 
        status: 'VALID', 
        feedback: 'AI_LIMIT', 
        instruction: 'Chuyển chế độ thủ công', 
        faceDetected: true 
      };
    }

    return { 
      isCompliant: true, 
      status: 'VALID', 
      feedback: 'Lỗi mạng', 
      instruction: 'Chụp thủ công', 
      faceDetected: true 
    };
  }
};

/**
 * Processes the ID photo with strict Layer-based logic.
 * UPDATED: Only handles CLOTHING now. Background and Beauty are handled algorithmically client-side.
 */
export const processIDPhoto = async (
  imageBase64: string, 
  bgType: BackgroundType, // Kept for interface compatibility but ignored for background generation logic inside AI
  clothingPrompt: string | undefined,
  size: PhotoSize
): Promise<string> => {
  if (!API_KEY) {
    throw new Error("API Key chưa được cấu hình.");
  }

  // If no clothing prompt, we just return the original because BG is now handled locally
  if (!clothingPrompt) {
      return imageBase64;
  }

  const cleanBase64 = imageBase64.replace(/^data:image\/(png|jpeg|jpg);base64,/, "");

  // --- LAYER 2: CLOTHING CONFIG ---
  const clothingInstruction = `Layer 3 Action (Clothing): REPLACE current clothes with "${clothingPrompt}". 
    CRITICAL: The collar must sit naturally BELOW the chin/jawline. Do not obscure the chin. Match skin tone at neck.`;

  // --- FINAL PROMPT CONSTRUCTION ---
  let prompt = `ROLE: Advanced Image Compositor & Biometric ID Specialist.
TASK: Replace clothing ONLY. Keep background and face exactly as is.
OUTPUT: Return the Final Composite Image.

================================================================
🔒 LAYER 0: BIOMETRIC BASE (LOCKED - IMMUTABLE)
================================================================
- DEFINITION: The geometric structure of the face (Eyes, Nose, Mouth, Jawline, Chin, Ears).
- RULE: ZERO TOLERANCE for warping, morphing, or reshaping. 
- IDENTITY MUST BE PRESERVED 100%.

================================================================
👕 LAYER 2: CLOTHING (OVERLAY)
================================================================
- TARGET: Area below the neck.
${clothingInstruction}
- CONSTRAINT: Clothing layer must NOT overlap the chin or face (Layer 0).

================================================================
EXECUTION ORDER
================================================================
1. Mask Subject (Keep Face Protected).
2. Apply Layer 2 (Clothing).
3. Merge Layers -> Output JPEG.
`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: {
        parts: [
          {
            inlineData: {
              mimeType: 'image/jpeg',
              data: cleanBase64
            }
          },
          {
            text: prompt
          }
        ]
      }
    });

    const parts = response.candidates?.[0]?.content?.parts;
    if (parts) {
      for (const part of parts) {
        if (part.inlineData && part.inlineData.data) {
          return `data:image/jpeg;base64,${part.inlineData.data}`;
        }
      }
    }

    throw new Error("Không nhận được dữ liệu ảnh từ Gemini.");

  } catch (error) {
    console.error("Gemini processing error:", error);
    throw error;
  }
};
